const fmt0 = v => v==null||!isFinite(v) ? '—' : Math.round(v).toString();
const fmt1 = v => v==null||!isFinite(v) ? '—' : v.toFixed(1);
const fmt2 = v => v==null||!isFinite(v) ? '—' : v.toFixed(2);
function _fmtCompact(v, dec) {
  if (v == null || !isFinite(v)) return '—';
  dec = dec == null ? 1 : dec;
  var pow = Math.pow(10, dec);
  return String(Math.round(v * pow) / pow);
}
function _fmtMetricVal(v, unit, key) {
  if (v == null || !isFinite(v)) return '';
  var u = unit || '';
  var d = 1;
  if (u === '°' || u === '%' || u === 'ms' || u === 'km/h') d = 1;
  else if (Math.abs(v) >= 1000) d = 0;
  else if (Math.abs(v) < 10 && u !== 'N' && u !== 'N·m') d = 2;
  return _fmtCompact(v, d) + u;
}
if (typeof window !== 'undefined') { window._fmtCompact = _fmtCompact; window._fmtMetricVal = _fmtMetricVal; }

