// 라이브 그래프 신호 목록을 7단계 메카닉 변인에서 자동 생성(단계=optgroup, _FC_SER 시계열 기준).
function _liveSignals(){
  var P=(typeof DATA!=='undefined')?DATA.phases:null, out=[];
  if(P&&P.stages){ P.stages.forEach(function(st){
    if(st.key==='consistency') return;
    (st.metrics||[]).forEach(function(m){
      var cfg=(m.key&&typeof _FC_SER!=='undefined')?_FC_SER[m.key]:null; if(!cfg) return;
      out.push({label:m.label, unit:m.unit||'', color:cfg.c, compute:cfg.fn, lines:cfg.lines, phase:st.label});
    });
  }); }
  return out.length?out:LC_SIGNALS;
}
function renderLiveChart(){
  if(!document.getElementById('lc-canvas')) return;
  var SIG=_liveSignals();
  var lcs=document.getElementById('lc-sel'); var i=lcs?(parseInt(lcs.value)||0):0; var sig=SIG[i]||SIG[0];
  var lines=sig.lines?sig.lines.map(function(l){return {compute:l.fn,color:l.c,label:l.label,width:2.4};})
    :[{compute:sig.compute, color:sig.color, label:sig.label, width:2.6}];
  plotWin('lc-canvas', {fast:_fastTrial(), slow:_slowTrial(), startEv:'i_start', startOff:0, endEv:'i_br', endOff:0.2,
    left:{label:sig.unit, lines:lines}});
}
if(typeof window!=='undefined'){ window.renderLiveChart=renderLiveChart; window._liveSignals=_liveSignals; }



