      back.onmouseenter = function(){ this.style.background='var(--cyan,#5bd3ff)'; this.style.color='#06202b'; };
      back.onmouseleave = function(){ this.style.background='var(--bg2,#1a2030)'; this.style.color='var(--cyan,#5bd3ff)'; };
      document.body.appendChild(back);
