function _coachCompactFitnessHtml(){
  var LF=(typeof LOAD_FITNESS_V1!=='undefined')?LOAD_FITNESS_V1:null;
  var hpa=(typeof DATA!=='undefined'&&DATA.hp_assessment)?DATA.hp_assessment:null;
  if(LF&&LF.coachFitnessCompactHtml){
    try{
      var v1=LF.coachFitnessCompactHtml(hpa,DATA);
      if(v1) return v1;
    }catch(e){}
  }
  var hints=[];
  try{
    var ph=(typeof DATA!=='undefined'&&DATA.phases)?DATA.phases:null;
    var br=ph&&ph.blockingRisk;
    if(br&&br.warning) hints.push('앞발 제동 능력 확인 필요');
    var kn=ph&&ph.leadKneeStrategy;
    if(kn&&(kn.type==='collapse'||/collapse|무너/i.test(String(kn.label||kn.easy||'')))) hints.push('앞무릎 버팀·제동 확인 필요');
    var tr=ph&&ph.trunkType;
    if(tr&&/early|빠르|조기/i.test(String(tr.easy||tr.label||''))) hints.push('흉추 회전 가동성 확인 필요');
    var hpa=(typeof DATA!=='undefined'&&DATA.hp_assessment)?DATA.hp_assessment:null;
    if(hpa&&hpa.asymmetry_flag) hints.push('좌우 하체 파워 차이 확인 필요');
    if(hpa&&hpa.weak_axes&&hpa.weak_axes.length){
      hpa.weak_axes.slice(0,2).forEach(function(ax){ hints.push(String(ax.label||ax.name||ax)+' 확인 필요'); });
    }
  }catch(e){}
  if(!hints.length) hints=['하체 제동 능력','회전 파워','고관절/흉추 가동성'];
  hints=hints.slice(0,4);
  return '<div class="card coach-fitness-compact" style="grid-column:1/-1;margin-top:12px">'
    +'<div style="font-size:12px;font-weight:800">체력은 강·약점 참고 · 구속 예측 아님</div>'
    +'<div class="sub2" style="margin-top:4px">상동고 팀 내부 기준 · 코치용 참고</div>'
    +'<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px">'
    +hints.map(function(h){ return '<span class="coach-fitness-badge">'+_ezLabel(h)+'</span>'; }).join('')
    +'</div>'
    +'<div class="sub2" style="margin-top:8px">자세한 체력 분석 → <button type="button" class="bm-focus-btn" onclick="setPage(\'hpa\')" style="font-size:11px;padding:3px 10px">체력 평가 탭</button></div></div>';
}
