  var fullViewport=document.body.classList.contains('report-mode-coach')||document.body.classList.contains('coach-today-summary-only')||document.body.classList.contains('coach-mech-summary-only')||document.body.classList.contains('hpa-reference-fullpage')||document.body.classList.contains('analyst-mech-summary-fullpage')||document.body.classList.contains('research-split-expert-layout');
