// ═══════════════════════════════════════════════════════════════════
// Chart helpers (axes + events + multi-line)
// ═══════════════════════════════════════════════════════════════════
function clearC(canvas) {
  const dpr = devicePixelRatio || 1;
  const w = canvas.clientWidth, h = canvas.clientHeight;
  canvas.width = w*dpr; canvas.height = h*dpr;
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr,0,0,dpr,0,0);
  ctx.clearRect(0,0,w,h);
  return {ctx,w,h};
}
function niceStep(range, target=5) {
  if (range <= 0) return 1;
  const raw = range/target, mag = Math.pow(10, Math.floor(Math.log10(raw))), n = raw/mag;
  return (n<1.5?1:n<3.5?2:n<7.5?5:10) * mag;
}
function plotRect(w, h, axes=true) {
  if (!axes) return {x:0,y:0,w,h};
  return {x:48, y:20, w:Math.max(10, w-56), h:Math.max(10, h-52)};
}
function autoRange(arrays, pad=0.10) {
  let lo=Infinity, hi=-Infinity;
  for (const arr of arrays) { if (!arr) continue; for (const v of arr) if (isFinite(v)) { if(v<lo)lo=v; if(v>hi)hi=v; } }
  if (!isFinite(lo) || lo===hi) { lo-=1; hi+=1; }
  const p=(hi-lo)*pad; return [lo-p, hi+p];
}
function drawAxes(ctx, pr, lo, hi, n, dt, i_fc, yLabel, xLabel) {
  ctx.strokeStyle='#3a4452'; ctx.lineWidth=1;
  ctx.beginPath(); ctx.moveTo(pr.x, pr.y); ctx.lineTo(pr.x, pr.y+pr.h); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(pr.x, pr.y+pr.h); ctx.lineTo(pr.x+pr.w, pr.y+pr.h); ctx.stroke();
  ctx.font='10px system-ui';
  const yStep = niceStep(hi-lo, 4);
  const yStart = Math.ceil(lo/yStep)*yStep;
  ctx.textAlign='right'; ctx.textBaseline='middle';
  for (let v=yStart; v<=hi+yStep*0.01; v+=yStep) {
    const y = pr.y + pr.h - (v-lo)/(hi-lo)*pr.h;
    ctx.strokeStyle='#252d3a'; ctx.beginPath(); ctx.moveTo(pr.x, y); ctx.lineTo(pr.x+pr.w, y); ctx.stroke();
    const lbl = yStep<0.1?v.toFixed(2):yStep<1?v.toFixed(1):Math.round(v);
    ctx.fillStyle = Math.abs(v)<1e-6 ? '#5bd3ff' : '#a9b4c2';
    ctx.fillText(lbl, pr.x-5, y);
  }
  if (dt && i_fc != null) {
    const t0 = -i_fc*dt, t1 = (n-1-i_fc)*dt;
    const xStep = niceStep(t1-t0, 6);
    const tStart = Math.ceil(t0/xStep)*xStep;
    ctx.textAlign='center'; ctx.textBaseline='top';
    for (let t=tStart; t<=t1+xStep*0.01; t+=xStep) {
      const frac = (t-t0)/(t1-t0);
      const x = pr.x + frac*pr.w;
      ctx.strokeStyle='#3a4452'; ctx.beginPath(); ctx.moveTo(x, pr.y+pr.h); ctx.lineTo(x, pr.y+pr.h+3); ctx.stroke();
      ctx.fillStyle = Math.abs(t)<0.01 ? '#5bd3ff' : '#a9b4c2';
      ctx.fillText(Math.abs(t)<1e-6?'0':t.toFixed(1), x, pr.y+pr.h+5);
    }
  }
  if (yLabel) { ctx.save(); ctx.translate(10, pr.y+pr.h/2); ctx.rotate(-Math.PI/2); ctx.fillStyle='#a8b3c2'; ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(yLabel, 0, 0); ctx.restore(); }
  if (xLabel) { ctx.fillStyle='#a8b3c2'; ctx.textAlign='right'; ctx.textBaseline='bottom'; ctx.fillText(xLabel, pr.x+pr.w, pr.y+pr.h+28); }
}
function drawEvents(ctx, pr, n, ev) {
  const lines = [
    {i: ev.i_kl_peak, c:'#a8b3c2', l:'KL'},
    {i: ev.i_fc,      c:'#3b82f6', l:'FC'},
    {i: ev.i_mer,     c:'#f5c542', l:'MER'},
    {i: ev.i_br,      c:'#ff4d4d', l:'BR'},
  ];
  ctx.setLineDash([3,3]); ctx.lineWidth=1; ctx.font='10.5px system-ui';
  for (const {i, c, l} of lines) {
    if (i==null) continue;
    const x = pr.x + i/(n-1)*pr.w;
    ctx.strokeStyle=c; ctx.beginPath(); ctx.moveTo(x, pr.y); ctx.lineTo(x, pr.y+pr.h); ctx.stroke();
    ctx.fillStyle=c; ctx.textAlign='center'; ctx.textBaseline='top'; ctx.fillText(l, x, pr.y-14);
  }
  ctx.setLineDash([]);
}
function drawLine(ctx, pr, arr, color, lo, hi, width) {
  ctx.strokeStyle=color; ctx.lineWidth=width||1.6; ctx.lineJoin='round'; ctx.beginPath();
  let first=true;
  for (let i=0; i<arr.length; i++) {
    const v = arr[i]; if (!isFinite(v)) { first=true; continue; }   // gap → break line (마스킹 구간)
    const x = pr.x + i/(arr.length-1)*pr.w, y = pr.y + pr.h - (v-lo)/(hi-lo)*pr.h;
    if (first) { ctx.moveTo(x,y); first=false; } else ctx.lineTo(x,y);
  }
  ctx.stroke();
}
function _cmpBfor(trial){ return (typeof window!=='undefined' && window._cmpB && window._cmpB!==trial) ? window._cmpB : null; }
function _bArrFor(B, l){ if (l.bArr) return l.bArr(B); if (l.arr && l.arr._mask){ var m=l.arr._mask; return _maskSeries(B, m.key, m.fromEv, m.toEv, m.tf); } if (l.key) return B.series[l.key]; return null; }
function _bRangeArrays(trial, lines){ var B=_cmpBfor(trial); return B?lines.map(function(l){return _bArrFor(B,l);}).filter(Boolean):[]; }
function _drawCmpB(ctx, pr, trial, lines, refDt, evFcAdj, visN, lo, hi){
  var B=_cmpBfor(trial); if(!B) return; var bfc=(B.events.i_fc||0), bdt=(B.meta.dt||refDt);
  ctx.save(); ctx.setLineDash([4,3]); ctx.globalAlpha=0.5;
  for(var li=0; li<lines.length; li++){ var a=_bArrFor(B, lines[li]); if(!a)continue; ctx.strokeStyle=lines[li].color; ctx.lineWidth=lines[li].width||1.6; ctx.beginPath(); var first=true;
    for(var bi=0;bi<a.length;bi++){ var v=a[bi]; if(!isFinite(v)){first=true;continue;} var t=(bi-bfc)*bdt; var j=evFcAdj+t/refDt; if(j<0||j>visN-1){first=true;continue;} var x=pr.x+j/(visN-1)*pr.w, y=pr.y+pr.h-(v-lo)/(hi-lo)*pr.h; if(first){ctx.moveTo(x,y);first=false;}else ctx.lineTo(x,y); } ctx.stroke(); }
  ctx.restore();
}
// 이벤트 구간 마스킹: fromEv~toEv(절대 frame) 밖은 NaN. tf 있으면 값 변환(부호 등).
function _maskSeries(trial, key, fromEv, toEv, tf) {
  const a = trial.series[key]; if (!a) return null;
  const ev = trial.events;
  const f = fromEv ? (ev[fromEv] ?? 0) : 0;
  const t = toEv ? (ev[toEv] ?? a.length-1) : a.length-1;
  const out = a.map((v, i) => (i>=f && i<=t && isFinite(v)) ? (tf ? tf(v) : v) : NaN);
  out._mask = { key: key, fromEv: fromEv || null, toEv: toEv || null, tf: tf || null };
  return out;
}
// 이벤트별 수치 표 (접이식 카드)
function _evIdx(trial){ const e=trial.events; return [['KL',e.i_kl_peak],['FC',e.i_fc],['MER',e.i_mer],['BR',e.i_br]]; }
function _evCard(trial, colTitle, rows){
  const cols=_evIdx(trial);
  const head=cols.map(c=>`<th>${c[0]}</th>`).join('');
  const body=rows.map(r=>{
    const a=r.arr||(r._xfArr?r._xfArr(trial):null)||trial.series[r.key];
    const cells=cols.map(c=>{ let v=(a&&c[1]!=null&&c[1]<a.length)?a[c[1]]:null; if(v!=null&&isFinite(v)&&r.tf)v=r.tf(v);
      return `<td>${(v==null||!isFinite(v))?'—':fmt1(v)}${(v!=null&&isFinite(v)&&r.unit)?`<span class="evu">${r.unit}</span>`:''}</td>`; }).join('');
    return `<tr><td class="evl">${r.label}</td>${cells}</tr>`;
  }).join('');
  return `<details class="ev-card"><summary>이벤트별 수치 (KL · FC · MER · BR)</summary>
    <table class="ev-table"><thead><tr><th class="evl">${colTitle}</th>${head}</tr></thead><tbody>${body}</tbody></table></details>`;
}
function drawCursor(ctx, pr, n, frame) {
  if (frame == null || n < 2) return;
  try{ if (typeof _gtFocus!=='undefined' && _gtFocus && typeof _gtActiveWin==='function'){
    var _cf=(typeof _currentFrame!=='undefined'?_currentFrame:0), _i0=_cf-frame, _aw=_gtActiveWin(_cf);
    if(_aw){ var _a0=pr.x+Math.max(0,Math.min(n-1,_aw[0]-_i0))/(n-1)*pr.w, _a1=pr.x+Math.max(0,Math.min(n-1,_aw[1]-_i0))/(n-1)*pr.w;
      ctx.save();
      ctx.fillStyle='rgba(255,255,255,.045)'; ctx.fillRect(_a0,pr.y,_a1-_a0,pr.h);
      ctx.fillStyle='rgba(14,18,24,.5)'; ctx.fillRect(pr.x,pr.y,Math.max(0,_a0-pr.x),pr.h); ctx.fillRect(_a1,pr.y,Math.max(0,pr.x+pr.w-_a1),pr.h);
      ctx.strokeStyle='rgba(63,134,207,.55)'; ctx.setLineDash([3,3]); ctx.lineWidth=1; ctx.beginPath(); ctx.moveTo(_a0,pr.y); ctx.lineTo(_a0,pr.y+pr.h); ctx.moveTo(_a1,pr.y); ctx.lineTo(_a1,pr.y+pr.h); ctx.stroke();
      ctx.restore();
    }
  } }catch(e){}
  const x = pr.x + Math.max(0, Math.min(n-1, frame))/(n-1)*pr.w;
  ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.moveTo(x, pr.y); ctx.lineTo(x, pr.y+pr.h); ctx.stroke();
}
function plot(canvasId, trial, lines, yLabel, opts) {
  const canvas = document.getElementById(canvasId); if (!canvas) return;
  const {ctx, w, h} = clearC(canvas);
  const rawArrays = lines.map(l => l.arr || trial.series[l.key]);
  if (!rawArrays.some(Boolean)) { ctx.fillStyle='#a8b3c2'; ctx.fillText('— no data —', w/2, h/2); return; }
  // v0.17: 가로축을 MaxKneeHeight(KL) 직전(−0.5s)부터 표시  [2026-06-01] -0.1s→-0.5s
  const dt = trial.meta.dt;
  const i0 = Math.max(0, (trial.events.i_start!=null ? trial.events.i_start : (trial.events.i_kl_peak||0) - Math.round(0.5/dt)));
  const arrays = rawArrays.map(a => a ? a.slice(i0) : null);
  const visN = trial.meta.n_frames - i0;
  const evAdj = {}; for (const k in trial.events) { const v = trial.events[k]; evAdj[k] = (typeof v==='number') ? v-i0 : v; }
  const [lo, hi] = autoRange(arrays.filter(Boolean).concat(_bRangeArrays(trial, lines)));
  const pr = plotRect(w, h, true);
  drawAxes(ctx, pr, lo, hi, visN, dt, evAdj.i_fc, yLabel, 'time from FC (s)');
  drawEvents(ctx, pr, visN, evAdj);
  // [2026-05-27] X-Factor 최대(분리 풀림 시작) 시점 마커 — 키네매틱 시퀀스 그래프에 분리 풀림 타이밍을 함께 표시.
  if (opts && opts.xfPeakFrame != null) {
    var _xi = opts.xfPeakFrame - i0;
    if (_xi >= 0 && _xi < visN) {
      var _xx = pr.x + _xi/(visN-1)*pr.w;
      ctx.save(); ctx.setLineDash([5,3]); ctx.strokeStyle='#c084fc'; ctx.lineWidth=2;
      ctx.beginPath(); ctx.moveTo(_xx, pr.y); ctx.lineTo(_xx, pr.y+pr.h); ctx.stroke();
      ctx.setLineDash([]); ctx.fillStyle='#c084fc'; ctx.font='10.5px system-ui'; ctx.textAlign='center'; ctx.textBaseline='bottom';
      ctx.fillText('X-Factor 최대(풀림 시작)', _xx, pr.y+pr.h-2);
      ctx.restore();
    }
  }
  if (lines.length > 1) {
    ctx.font='10px system-ui'; let lx = pr.x+10, ly = pr.y + 6;
    for (const l of lines) {
      ctx.fillStyle = l.color; ctx.fillRect(lx, ly, 10, 3);
      ctx.fillStyle = '#a9b4c2'; ctx.textAlign='left'; ctx.textBaseline='top';
      ctx.fillText(l.label || l.key, lx+14, ly-2);
      lx += ctx.measureText(l.label || l.key).width + 32;
    }
  }
  for (let i=0; i<lines.length; i++) {
    if (arrays[i]) drawLine(ctx, pr, arrays[i], lines[i].color, lo, hi, lines[i].width);
  }
  _drawCmpB(ctx, pr, trial, lines, dt, (evAdj.i_fc||0), visN, lo, hi);
  drawCursor(ctx, pr, visN, _currentFrame - i0);
}
// ── 스트라이드 구간(KL~FC)만 확대해 그리는 플롯 (뒷발 자유모멘트 등) ──
// plot() 과 동일 스타일이나 x축을 스트라이드 윈도우로 줌. FC 직후 약간(0.03s)만 tail 표시.
function plotStride(canvasId, trial, lines, yLabel) {
  const canvas = document.getElementById(canvasId); if (!canvas) return;
  const {ctx, w, h} = clearC(canvas);
  const ev = trial.events, dt = trial.meta.dt;
  const kl = ev.i_kl_peak, fc = ev.i_fc;
  if (kl == null || fc == null || fc <= kl) {
    ctx.fillStyle='#a8b3c2'; ctx.textAlign='center'; ctx.fillText('— 스트라이드 이벤트 없음 —', w/2, h/2); return;
  }
  const tail = Math.round(0.03 / dt);
  const from = Math.max(0, (ev.i_start!=null ? ev.i_start : kl));   // [2026-06-03] 동작 시작 통일
  const to   = Math.min(trial.meta.n_frames - 1, fc + tail);
  const rawArrays = lines.map(l => l.arr || trial.series[l.key]);
  if (!rawArrays.some(Boolean)) { ctx.fillStyle='#a8b3c2'; ctx.textAlign='center'; ctx.fillText('— no data —', w/2, h/2); return; }
  const arrays = rawArrays.map(a => a ? a.slice(from, to + 1) : null);
  const visN = to - from + 1;
  const evAdj = { i_kl_peak: kl - from, i_fc: fc - from };
  const [lo, hi] = autoRange(arrays.filter(Boolean).concat(_bRangeArrays(trial, lines)));
  const pr = plotRect(w, h, true);
  drawAxes(ctx, pr, lo, hi, visN, dt, evAdj.i_fc, yLabel, 'time from FC (s)');
  drawEvents(ctx, pr, visN, evAdj);
  if (lines.length >= 1) {
    ctx.font='10px system-ui'; let lx = pr.x + 10, ly = pr.y + 6;
    for (const l of lines) {
      ctx.fillStyle = l.color; ctx.fillRect(lx, ly, 10, 3);
      ctx.fillStyle = '#a9b4c2'; ctx.textAlign='left'; ctx.textBaseline='top';
      ctx.fillText(l.label || l.key, lx + 14, ly - 2);
      lx += ctx.measureText(l.label || l.key).width + 32;
    }
  }
  for (let i = 0; i < lines.length; i++) {
    if (arrays[i]) drawLine(ctx, pr, arrays[i], lines[i].color, lo, hi, lines[i].width);
  }
  _drawCmpB(ctx, pr, trial, lines, dt, (evAdj.i_fc||0), visN, lo, hi);
  drawCursor(ctx, pr, visN, _currentFrame - from);
}
function plotXF(trial) {
  const canvas = document.getElementById('ch-xf'); if (!canvas) return;
  const {ctx, w, h} = clearC(canvas);
  const xfRaw = trial.x_factor;
  if (!xfRaw || !xfRaw.length) return;
  const dt = trial.meta.dt;
  const i0 = Math.max(0, (trial.events.i_start!=null ? trial.events.i_start : (trial.events.i_kl_peak||0) - Math.round(0.5/dt)));
  const xf = xfRaw.slice(i0);
  const visN = trial.meta.n_frames - i0;
  const evAdj = {}; for (const k in trial.events) { const v = trial.events[k]; evAdj[k] = (typeof v==='number') ? v-i0 : v; }
  const xfLines = [{ color:'#5bd3ff', width:1.6, bArr:function(B){ return B.x_factor; } }];
  const [lo, hi] = autoRange([xf].concat(_bRangeArrays(trial, xfLines)));
  const pr = plotRect(w, h, true);
  drawAxes(ctx, pr, lo, hi, visN, dt, evAdj.i_fc, 'X-Factor (°)', 'time from FC (s)');
  drawEvents(ctx, pr, visN, evAdj);
  drawLine(ctx, pr, xf, '#5bd3ff', lo, hi);
  _drawCmpB(ctx, pr, trial, xfLines, dt, (evAdj.i_fc||0), visN, lo, hi);
  drawCursor(ctx, pr, visN, _currentFrame - i0);
}

