    prevTh=null;
    if(key==='gAbd'){ if(gS&&gE)v=ang(sub(gE,gS),down); }
    else if(key==='tAbd'){ if(tS&&tE)v=ang(sub(tE,tS),down); }                 /* [2026-05-26] 투구팔 외전(양팔 오버레이용) */
    else if(key==='gElbFlex'){ if(gS&&gE&&gW)v=180-ang(sub(gS,gE),sub(gW,gE)); }
    else if(key==='tElbFlex'){ if(tS&&tE&&tW)v=180-ang(sub(tS,tE),sub(tW,tE)); } /* [2026-05-26] 투구팔 팔꿈치 굴곡(양팔 오버레이용) */
    else if(key==='gHandH'){ if(gW&&gS)v=gW[1]-gS[1]; }
    else if(key==='counterAP'){ if(gS&&tS)v=gS[2]-tS[2]; }
    else if(key==='shTilt'){ if(gS&&tS){ var sl=sub(gS,tS); v=Math.atan2(sl[1],Math.hypot(sl[0],sl[2]))*180/Math.PI; } }
    else if(key==='abdSym'){ if(gS&&gE&&tS&&tE)v=ang(sub(tE,tS),down)-ang(sub(gE,gS),down); }
    else if(key==='shAbdAsym'){ if(gS&&gE&&tS&&tE)v=asym(ang(sub(tE,tS),down),ang(sub(gE,gS),down)); }
    else if(key==='leadKneeFlex'){ if(lHip&&lKn&&lHe)v=180-ang(sub(lHip,lKn),sub(lHe,lKn)); }
    else if(key==='backKneeFlex'){ if(bHip&&bKn&&bHe)v=180-ang(sub(bHip,bKn),sub(bHe,bKn)); }
    else if(key==='kneeFlexSym'){ if(lHip&&lKn&&lHe&&bHip&&bKn&&bHe)v=asym(180-ang(sub(lHip,lKn),sub(lHe,lKn)),180-ang(sub(bHip,bKn),sub(bHe,bKn))); }
    else if(key==='elbowFlexAsym'){ if(gS&&gE&&gW&&tS&&tE&&tW)v=asym(180-ang(sub(tS,tE),sub(tW,tE)),180-ang(sub(gS,gE),sub(gW,gE))); }
    else if(key==='trunkLat'){ if(nk&&pel){ var tl=sub(nk,pel); v=Math.atan2(tl[0],tl[1])*180/Math.PI; } }
