function getFastestTrial(D){
  if(!D||!D.trials||!D.trials.length) return { trial:null, trialIndex:0, velocityKmh:null, source:'none', warning:'trial 없음' };
  var trials=D.trials, best=null, bv=-1, i, t, v;
  for(i=0;i<trials.length;i++){ t=trials[i]; v=t.rapsodo&&t.rapsodo.velocity_kmh; if(v!=null&&isFinite(v)&&v>bv){ bv=v; best=i; } }
  if(best!=null) return { trial:trials[best], trialIndex:best, velocityKmh:bv, source:'rapsodo', warning:null };
  var bi=(D.best_trial_index||1)-1; if(bi<0||bi>=trials.length) bi=0;
  var warn='구속 trial 정보 없음 — 대표 trial로 비교';
  var vel=(D.measured_kmh!=null&&isFinite(D.measured_kmh))?D.measured_kmh:null;
  return { trial:trials[bi], trialIndex:bi, velocityKmh:vel, source:'best_trial_index', warning:warn };
}
function _cmpList(){
  var selfNm=(typeof DATA!=='undefined'&&DATA.player&&DATA.player.name)||'', out=[], seen={};
  function add(arr){ if(!arr||!arr.length) return; for(var i=0;i<arr.length;i++){ var p=arr[i]; if(!p) continue; var nm=String(p.name||(p.player&&p.player.name)||'').trim(); if(!nm||nm===selfNm||seen[nm]) continue; seen[nm]=1; out.push(p); } }
  if(typeof DATA!=='undefined'&&DATA._compare&&DATA._compare.length) add(DATA._compare);
  if(typeof window!=='undefined'&&window.__SESSION_COMPARE) add(window.__SESSION_COMPARE);
  if(typeof window!=='undefined'&&window.__COHORT_COMPARE) add(window.__COHORT_COMPARE);
  out.sort(function(a,b){ return String(a.name||'').localeCompare(String(b.name||''),'ko'); });
  return out;
}
