function _cmpSumDualBar(lbl, va, vb, unit, colA, colB){
  if(va==null||vb==null||!isFinite(va)||!isFinite(vb)) return '';
  var mx=Math.max(Math.abs(va),Math.abs(vb),1e-6), pa=Math.min(100,Math.abs(va)/mx*100), pb=Math.min(100,Math.abs(vb)/mx*100);
  var du=unit||'', d=(vb-va), ds=(d>0?'+':'')+_fmtCompact(d, 1);
  var vaS=_fmtMetricVal(va, du, ''), vbS=_fmtMetricVal(vb, du, '');
  return '<div style="flex:1 1 210px;min-width:190px;background:var(--bg2);border:1px solid var(--line);border-radius:8px;padding:9px 11px">'
    +'<div style="font-size:11.5px;font-weight:700;line-height:1.3;margin-bottom:6px">'+lbl+'</div>'
    +'<div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:5px">'
    +'<span style="color:'+colA+';font-weight:800">A '+vaS+'</span>'
    +'<span style="color:var(--fg2)">Δ'+ds+du+'</span>'
    +'<span style="color:'+colB+';font-weight:800">B '+vbS+'</span></div>'
    +'<div style="height:9px;background:var(--bg1);border-radius:5px;overflow:hidden;display:flex">'
    +'<div style="width:'+pa+'%;background:'+colA+'"></div><div style="width:'+pb+'%;background:'+colB+'"></div></div></div>';
}
function _cmpSumFromStages(stages, colA, colB, pickVal){
  var items=[];
  (stages||[]).forEach(function(st){
    (st.metrics||[]).forEach(function(m){
      if(!m.key) return;
      var va=pickVal(m,'a'), vb=pickVal(m,'b');
      if(va==null||vb==null||!isFinite(va)||!isFinite(vb)) return;
      var delta=Math.abs((typeof m.cmpDelta==='number'&&isFinite(m.cmpDelta))?m.cmpDelta:(va-vb));
      items.push({label:(typeof _ezLabel==='function')?_ezLabel(m.label):m.label, va:va, vb:vb, delta:delta, unit:m.unit||''});
    });
  });
  items.sort(function(a,b){return b.delta-a.delta;});
  return items.slice(0,8);
}
function _cmpSumTopStage(stages,pickA,pickB){
  var best=null;
  (stages||[]).forEach(function(st){
    if(st.aux) return;
    var sum=0,n=0;
    (st.metrics||[]).forEach(function(m){
      var va=pickA(m),vb=pickB(m);
      if(va==null||vb==null||!isFinite(va)||!isFinite(vb)) return;
      sum+=Math.abs((typeof m.cmpDelta==='number'&&isFinite(m.cmpDelta))?m.cmpDelta:(va-vb)); n++;
    });
    if(n&&(!best||sum/n>best.avg)) best={label:st.label,key:st.key,avg:sum/n};
  });
  return best;
}
function _cmpSumCoachLine(items,isFs,axMeta){
  if(!items.length) return '';
  var top=items[0], d=(top.vb-top.va);
  var lblA=(axMeta&&axMeta.baseLabel)||'A';
  var lblB=(axMeta&&axMeta.compareLabel)||'B';
  if(isFs){
    if(d>0) return _fvEsc(lblB)+' trial에서 <b>'+top.label+'</b> 차이가 가장 큼 → 이 구간 점검 권장.';
    if(d<0) return _fvEsc(lblA)+' trial에서 <b>'+top.label+'</b> 우위 → '+_fvEsc(lblB)+'에서 동일 패턴 연습 권장.';
    return _fvEsc(lblA)+'·'+_fvEsc(lblB)+' trial 간 <b>'+top.label+'</b> 차이가 가장 큼.';
  }
  if(d>0) return '비교 선수가 <b>'+top.label+'</b>에서 더 높음 → 기준 선수는 이 구간 보완 검토.';
  if(d<0) return '기준 선수가 <b>'+top.label+'</b>에서 더 높음 → 비교 선수 강점 구간.';
  return '선수 간 <b>'+top.label+'</b> 차이가 가장 큼.';
}
function _fsCompareSummaryHTML(){
  var ax=_fvConditionAxisKey();
  var meta=(typeof feedbackSummary!=='undefined'&&feedbackSummary.CONDITION_AXIS_META)?feedbackSummary.CONDITION_AXIS_META[ax]:null;
  var axLbl=(meta&&meta.labelKo)||'조건 비교';
  var lblA=(meta&&meta.baseLabel)||'A';
  var lblB=(meta&&meta.compareLabel)||'B';
  var tr=_fvAxisTrials(ax);
  var FS=(typeof FEEDBACK_SUMMARY!=='undefined')?FEEDBACK_SUMMARY:null;
  var cd=FS?_fvResolveConditionDelta(FS, ax):null;
  if(cd&&cd.available&&cd.topShifts&&cd.topShifts.length){
    var rows=cd.topShifts.slice(0,3).map(function(s){
      return _cmpSumDualBar(s.labelKo, s.base, s.compare, s.unit, '#5bb6e6', '#9aa7b6');
    }).join('');
    var head='<div style="display:flex;flex-wrap:wrap;gap:10px;align-items:baseline;margin-bottom:8px">'
      +'<b style="font-size:14px;color:#5bb6e6">'+_fvEsc(axLbl)+' 요약</b>'
      +'<span class="sub2">'+_fvEsc(lblA)+' '+cd.base.velocity_kmh+' km/h vs '+_fvEsc(lblB)+' '+cd.compare.velocity_kmh+' km/h</span>'
      +(cd.phaseSummary&&cd.phaseSummary.primaryPhaseLabel?('<span class="sub2">차이 큰 단계 <b>'+_fvEsc(cd.phaseSummary.primaryPhaseLabel)+'</b></span>'):'')
      +'</div>';
    var mech=cd.mechanicEvaluation&&cd.mechanicEvaluation.summaryLine;
    return '<div class="card" style="margin:8px 12px 0;padding:12px 14px;border-left:4px solid #5bb6e6">'+head
      +(mech?('<div class="note" style="margin-bottom:8px">'+_fvEsc(mech)+'</div>'):'')
      +'<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:8px">'+rows+'</div>'
      +'<div style="margin-top:10px;display:flex;flex-wrap:wrap;gap:10px;align-items:center">'
      +'<span class="note">스틱 실선='+_fvEsc(lblA)+' · 점선='+_fvEsc(lblB)+' · FC=0 정렬</span>'
      +'<button type="button" class="bm-focus-btn" onclick="_goLkResearch()">Research 상세 →</button></div></div>';
  }
  var P=(typeof DATA!=='undefined')?DATA.phases:null;
  if(!P||!P.stages) return '';
  var items=_cmpSumFromStages(P.stages,'#5bb6e6','#9aa7b6',function(m,side){ return side==='a'?m.fastV:m.slowV; });
  items=items.slice(0,3);
  if(!items.length) return '<div class="card" style="margin:8px 12px 0;padding:12px 14px;border-left:4px solid #5bb6e6"><div class="sub2">'+_fvEsc(axLbl)+' — 차이 큰 변인이 없습니다</div></div>';
  var ft=tr.a||_fastTrial(), st=tr.b||_slowTrial();
  var vA=ft&&ft.rapsodo&&ft.rapsodo.velocity_kmh, vB=st&&st.rapsodo&&st.rapsodo.velocity_kmh;
  var vDiff=(vA!=null&&vB!=null)?(vA-vB):null;
  var stg=_cmpSumTopStage(P.stages,function(m){return m.fastV;},function(m){return m.slowV;});
  var head2='<div style="display:flex;flex-wrap:wrap;gap:10px;align-items:baseline;margin-bottom:8px">'
    +'<b style="font-size:14px;color:#5bb6e6">'+_fvEsc(axLbl)+' 요약</b>'
    +(vDiff!=null?('<span class="sub2">구속 차이 <b style="color:#5bb6e6">'+vDiff.toFixed(1)+'</b> km/h ('+_fvEsc(lblA)+' '+vA.toFixed(1)+' · '+_fvEsc(lblB)+' '+vB.toFixed(1)+')</span>'):'')
    +(stg?('<span class="sub2">차이 큰 단계 <b>'+stg.label+'</b></span>'):'')
    +'</div>';
  return '<div class="card" style="margin:8px 12px 0;padding:12px 14px;border-left:4px solid #5bb6e6">'+head2
    +'<div class="note" style="margin-bottom:8px">'+_cmpSumCoachLine(items,true,meta)+'</div>'
    +'<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:8px">'+items.map(function(it){return _cmpSumDualBar(it.label,it.va,it.vb,it.unit,'#5bb6e6','#9aa7b6');}).join('')+'</div>'
    +'<div style="margin-top:10px;display:flex;flex-wrap:wrap;gap:10px;align-items:center">'
    +'<span class="note">스틱 실선='+_fvEsc(lblA)+' · 점선='+_fvEsc(lblB)+' · FC=0 정렬</span>'
    +'<button type="button" class="bm-focus-btn" onclick="_goLkResearch()">Research 상세 →</button></div></div>';
}
function _plCompareSummaryHTML(){
  var cp=_cmpPlayer(); var P=(typeof DATA!=='undefined')?DATA.phases:null;
  if(!cp||!P||!P.stages||!cp.phases||!cp.phases.stages) return '';
  var cmap={};
  cp.phases.stages.forEach(function(st){ (st.metrics||[]).forEach(function(m){ if(m.key&&m.value!=null) cmap[m.key]=m; }); });
  var items=[];
  P.stages.forEach(function(st){
    (st.metrics||[]).forEach(function(m){
      if(!m.key||m.value==null||!isFinite(m.value)) return;
      var cm=cmap[m.key]; if(!cm||cm.value==null||!isFinite(cm.value)) return;
      items.push({label:(typeof _ezLabel==='function')?_ezLabel(m.label):m.label, va:m.value, vb:cm.value, delta:Math.abs(m.value-cm.value), unit:m.unit||''});
    });
  });
  items.sort(function(a,b){return b.delta-a.delta;});
  items=items.slice(0,3);
  if(!items.length) return '<div class="card" style="margin:8px 12px 0;padding:12px 14px;border-left:4px solid '+_CMP_COL+'"><div class="sub2">선수 간 비교 — 공통 변인 차이 없음</div></div>';
  var bn=(DATA.player&&DATA.player.name)||'기준', cn=cp.name||'비교';
  var rA=getFastestTrial(DATA), rB=getFastestTrial(cp);
  var stg=_cmpSumTopStage(P.stages,function(m){return m.value;},function(m){return cmap[m.key]?cmap[m.key].value:null;});
  var baseWeak=items.filter(function(it){return it.va<it.vb;}).slice(0,2);
  var cmpStrong=items.filter(function(it){return it.vb>it.va;}).slice(0,2);
  var viewHint=_cmpView==='side'?'나란히 보기(측면 offset)':'겹쳐 보기(FC 정렬)';
  var radarHtml = '';
  if (typeof ENERGY_FLOW_DISPLAY !== 'undefined' && typeof DATA !== 'undefined') {
    radarHtml = ENERGY_FLOW_DISPLAY.compareRadarPanelHtml(DATA, cp) || '';
    if (radarHtml) radarHtml = radarHtml.replace('grid-column:1 / -1;', '');
  }
  return '<div class="card" style="margin:8px 12px 0;padding:12px 14px;border-left:4px solid '+_CMP_COL+'">'
    +'<div style="display:flex;flex-wrap:wrap;gap:10px;align-items:baseline;margin-bottom:8px">'
    +'<b style="font-size:14px;color:'+_CMP_COL+'">선수 간 비교 요약</b>'
    +'<span class="sub2">'+bn+' vs '+cn+'</span>'
    +'<span class="sub2">기준 '+((rA.velocityKmh!=null)?rA.velocityKmh.toFixed(1)+' km/h':'—')+' · 비교 '+((rB.velocityKmh!=null)?rB.velocityKmh.toFixed(1)+' km/h':'—')+'</span>'
    +(stg?('<span class="sub2">차이 큰 단계 <b>'+stg.label+'</b></span>'):'')
    +'</div>'
    +'<div class="note" style="margin-bottom:6px">'+_cmpSumCoachLine(items,false)+'</div>'
    +(baseWeak.length?'<div class="sub2">기준 선수 열위 → '+baseWeak.map(function(it){return it.label;}).join(' · ')+'</div>':'')
    +(cmpStrong.length?'<div class="sub2" style="margin-top:2px">비교 선수 우위 → '+cmpStrong.map(function(it){return it.label;}).join(' · ')+'</div>':'')
    +'<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:8px">'+items.map(function(it){return _cmpSumDualBar(it.label,it.va,it.vb,it.unit,'var(--cyan)',_CMP_COL);}).join('')+'</div>'
    +'<div style="margin-top:10px;display:flex;flex-wrap:wrap;gap:10px;align-items:center">'
    +'<span class="note">스틱 '+viewHint+' · compare에도 GRF/COM/손궤적 동일 파이프라인</span>'
    +'<button type="button" class="bm-focus-btn" onclick="_goLkResearch()">Research 상세 →</button></div></div>'
    + radarHtml;
}
