  var fwd=(D.fast.series.fwd!=null)?D.fast.series.fwd:2, lat=(fwd===0)?2:0, fSign=(D.fast.series.fwdSign!=null)?D.fast.series.fwdSign:1, LATm=_mirrorScaleSign(D.handed);
