function _cmpActive(){ try{ return !!(playback&&playback.isCompare&&playback.isCompare()); }catch(e){ return false; } }
function _cmpLabel(){ try{ if(typeof _cmpOn!=='undefined'&&_cmpOn){ var p=(typeof _cmpPlayer==='function')?_cmpPlayer():null; return (p&&p.name)?p.name:'상대'; } }catch(e){} return '느린공'; }
function _gaugeSlowPeak(key,i0,i1){ try{ var D=_WG.data; if(!D||!D.slow||!D.slow.series)return null; var a=D.slow.series[key]; if(!a)return null; var v=-Infinity, lo=(i0!=null?i0:0), hi=(i1!=null?i1:a.length-1); for(var i=lo;i<=hi&&i<a.length;i++){var x=a[i]; if(x!=null&&isFinite(x)&&(v===-Infinity||Math.abs(x)>Math.abs(v)))v=x;} return v===-Infinity?null:Math.round(v*100)/100; }catch(e){ return null; } }
