var _TG={ idx:0,i0:0,i1:0, contribPct:null, typeStr:'' };
_TG.win=function(){ var T=_WG.data.fast.series.time, ev=_WG.data.fast.series.ev, fc=ev.fc, br=ev.br; var lo=(fc!=null?fc:0)-100, hi=(br!=null?br:T[T.length-1])+60; var i0=0,i1=T.length-1; for(var i=0;i<T.length;i++){if(T[i]>=lo){i0=i;break;}} for(var j=T.length-1;j>=0;j--){if(T[j]<=hi){i1=j;break;}} if(i1<=i0)i1=T.length-1; return [i0,i1]; };
_TG.drawType=function(){ var cv=document.getElementById('tgcv-knetype'); if(!cv)return; var dpr=window.devicePixelRatio||1,W=cv.clientWidth||320,H=200; cv.width=W*dpr;cv.height=H*dpr; var c=cv.getContext('2d'); c.setTransform(dpr,0,0,dpr,0,0); c.clearRect(0,0,W,H);
  var pc=_TG.contribPct, x0=24,x1=W-24,y=H*0.52,span=x1-x0; function X(p){return x0+Math.max(0,Math.min(100,p))/100*span;}
  c.fillStyle='#e8ecf2';c.font='12px system-ui';c.textAlign='center';c.textBaseline='top';c.fillText('무릎 신전 기여 비율(%) — 위치로 유형 판단',W/2,6);
  c.fillStyle='rgba(70,201,140,0.18)';c.fillRect(X(20.6),y-14,X(38.7)-X(20.6),28);
  c.strokeStyle='#3a4452';c.lineWidth=2;c.beginPath();c.moveTo(x0,y);c.lineTo(x1,y);c.stroke();
  c.strokeStyle='rgba(70,201,140,0.85)';c.lineWidth=2;c.beginPath();c.moveTo(X(26.5),y-16);c.lineTo(X(26.5),y+16);c.stroke();
  c.fillStyle='#a8b3c2';c.font='10px system-ui';c.textAlign='center';c.textBaseline='bottom';c.fillText('코호트 중앙 26.5%',X(26.5),y-20);
  c.fillStyle='#a9b4c2';c.font='11px system-ui';c.textBaseline='top';c.textAlign='left';c.fillText('← 버팀-흡수형',x0,y+22);c.textAlign='right';c.fillText('신전형(밀어올리기) →',x1,y+22);
  if(pc!=null&&isFinite(pc)){ var px=X(pc); c.strokeStyle='#e8954e';c.lineWidth=2;c.beginPath();c.moveTo(px,y-22);c.lineTo(px,y+18);c.stroke(); c.fillStyle='#e8954e';c.beginPath();c.arc(px,y,7,0,7);c.fill(); c.fillStyle='#fff';c.font='bold 12px system-ui';c.textAlign='center';c.textBaseline='bottom';c.fillText(pc+'%',px,y-24); }
  // 선수 비교: 상대 선수 마커(보라) 추가 — 이영하-문서준식 비교
  var cpc=(typeof _cmpOn!=='undefined'&&_cmpOn)?_TG.cmpContribPct:null;
  if(cpc!=null&&isFinite(cpc)){ var qx=X(cpc); c.strokeStyle='#c084fc';c.lineWidth=2;c.beginPath();c.moveTo(qx,y-18);c.lineTo(qx,y+22);c.stroke(); c.fillStyle='#c084fc';c.beginPath();c.arc(qx,y,7,0,7);c.fill(); c.fillStyle='#fff';c.font='bold 11px system-ui';c.textAlign='center';c.textBaseline='top';c.fillText(cpc+'%',qx,y+10);
    c.fillStyle='#c084fc';c.font='10px system-ui';c.textAlign='right';c.textBaseline='top';c.fillText('보라='+(typeof _cmpLabel==='function'?_cmpLabel():'상대'),x1,6); }
  c.fillStyle='#c084fc';c.font='bold 13px system-ui';c.textAlign='center';c.textBaseline='top';c.fillText('판정: '+(_TG.typeStr||'–'),W/2,H-22);
};
