  var rings=[25,50,75,100].map(function(lv){var pts=stages.map(function(_,i){return pt(i,lv).map(function(v){return v.toFixed(1);}).join(',');}).join(' ');var hi=lv===100;return '<polygon points="'+pts+'" fill="none" stroke="'+(hi?'#5b6b82':'#2c3442')+'" stroke-width="'+(hi?1.4:1)+'" '+(hi?'':'stroke-dasharray="2 3"')+'/>';}).join('');
  var spokes=stages.map(function(_,i){var p=pt(i,CAP);return '<line x1="'+CX+'" y1="'+CY+'" x2="'+p[0].toFixed(1)+'" y2="'+p[1].toFixed(1)+'" stroke="#2c3442"/>';}).join('');
  var myPts=stages.map(function(st,i){return pt(i,st.score||0).map(function(v){return v.toFixed(1);}).join(',');}).join(' ');
  var myPoly='<polygon points="'+myPts+'" fill="rgba(232,140,46,0.30)" stroke="var(--amber)" stroke-width="2.5"/>';
  var myDots=stages.map(function(st,i){if(st.score==null)return '';var p=pt(i,st.score);return '<circle cx="'+p[0].toFixed(1)+'" cy="'+p[1].toFixed(1)+'" r="4" fill="var(--amber)" stroke="#0b0d12" stroke-width="1"/>';}).join('');
  var labels=stages.map(function(st,i){var p=pt(i,CAP*1.18);var an=Math.abs(p[0]-CX)<6?'middle':(p[0]>CX?'start':'end');return '<text x="'+p[0].toFixed(1)+'" y="'+p[1].toFixed(1)+'" text-anchor="'+an+'" font-size="11" font-weight="700" fill="#e8ecf2">'+_phaseShort(st.label)+'</text><text x="'+p[0].toFixed(1)+'" y="'+(p[1]+13).toFixed(1)+'" text-anchor="'+an+'" font-size="10" fill="#a8b3c2">'+(st.score!=null?st.score+'점':'—')+'</text>';}).join('');
  var ss=stages.filter(function(x){return x.score!=null;});
  var comp=ss.length?Math.round(ss.reduce(function(p,x){return p+x.score;},0)/ss.length):null;
  return '<svg viewBox="-70 -10 '+(SZ+140)+' '+(SZ+30)+'" width="100%" style="max-width:480px">'+spokes+rings+myPoly+myDots+labels+'<circle cx="'+CX+'" cy="'+CY+'" r="30" fill="var(--bg2)" stroke="var(--amber)" stroke-width="2"/><text x="'+CX+'" y="'+(CY-1)+'" text-anchor="middle" font-size="22" font-weight="800" fill="var(--amber)">'+(comp!=null?comp:'—')+'</text><text x="'+CX+'" y="'+(CY+13)+'" text-anchor="middle" font-size="8.5" fill="#a8b3c2">메카닉 종합</text></svg>';
