function _bmStagePctl(st){ var ps=[]; (st.metrics||[]).forEach(function(m){ if(m.neutral)return; var p=_bmPctl(m); if(p!=null)ps.push(p); }); return ps.length?Math.round(ps.reduce(function(a,b){return a+b;},0)/ps.length):null; }
function _bmCompPctl(){ var P=(typeof DATA!=='undefined')?DATA.phases:null; if(!P||!P.stages)return null; var ps=[]; P.stages.forEach(function(st){ if(st.key==='consistency')return; (st.metrics||[]).forEach(function(m){ if(m.neutral)return; var p=_bmPctl(m); if(p!=null)ps.push(p); }); }); return ps.length?Math.round(ps.reduce(function(a,b){return a+b;},0)/ps.length):null; }
