function _motionBanner(){
  var mt=_motionType(); if(!mt)return '';
  var col=mt.type==='드라이브-주도형'?'#5bb6e6':(mt.type==='회전-주도형'?'#c084fc':'#46c98c');
  var reason=mt.type==='드라이브-주도형'?'하체 선형 추진(전진속도·뒷다리 드라이브)에서 동력을 만드는 유형 · <b>드라이브 체인(② 드라이브)</b>=핵심 평가 / 회전 단계=부차'
    :mt.type==='회전-주도형'?'상체 회전(골반·몸통·팔 회전·분리)에서 동력을 만드는 유형 · <b>회전 체인(몸통 저장·생성·전달)</b>=핵심 평가 / 드라이브 단계=부차'
    :'드라이브·회전 동력 균형적(차이 '+mt.diff+'p) · 두 체인 모두 핵심 평가';
  return '<div class="card" style="margin-bottom:12px;border-left:5px solid '+col+'">'
    +'<div class="sub2" style="margin-bottom:3px">투구 동작 유형 <span style="font-size:11px">(엘리트 규준 백분위 기반)</span></div>'
    +'<div style="font-size:21px;font-weight:800;color:'+col+'">'+mt.type+'</div>'
    +'<div style="display:flex;gap:18px;margin:7px 0;font-size:12px;color:var(--fg1);flex-wrap:wrap"><span>드라이브 지수 <b style="color:#5bb6e6">'+mt.driveIdx+'p</b></span><span>회전 지수 <b style="color:#c084fc">'+mt.rotIdx+'p</b></span><span class="sub2">전진속도·드라이브일·추진·스트라이드 vs 골반·몸통·팔 회전·X-Factor 백분위 평균</span></div>'
    +'<div style="font-size:12.5px;color:var(--fg1);line-height:1.65">'+reason+'</div>'
    +'<div class="note" style="margin-top:6px">※ 두 유형 모두 유효한 엘리트 패턴 — 우열이 아니라 "어느 동력으로 던지는가" · 그 동력 체인의 결함을 우선 평가 · 각 단계 카드의 <b> 핵심 / 부차</b> 배지 참고</div></div>';
}
// 투구 유형별 맞춤 솔루션: 핵심 체인 교정은 강조, 부차 체인 교정은 톤다운, 핵심 강점은 유지·활용
function _typeSolutions(){
  var P=(typeof DATA!=='undefined')?DATA.phases:null; if(!P||!P.stages)return ''; var mt=(typeof _motionType==='function')?_motionType():null; if(!mt)return '';
  var core=[], minor=[], strongCore=[];
  P.stages.forEach(function(st){ if(st.key==='consistency')return; var role=_motionChainRole(st.key, mt.type);
    (st.metrics||[]).forEach(function(m){ if(!m.key||m.normNA||m.neutral||m.value==null||!m.dir)return; var nm=(typeof BIOMOTION_NORMS!=='undefined')?BIOMOTION_NORMS[m.key]:null; if(!nm)return; var s=_bmStat(m.value,nm,m.dir); if(!s)return;
      if(s.status==='flag'){ (role==='minor'?minor:core).push(m.label); }
      else if(s.status==='strong'&&(role==='core'||role==='common')){ strongCore.push(m.label); } }); });
  var dt=null; var tr=P.stages.filter(function(s){return s.key==='transfer';})[0]; if(tr){ var dm=(tr.metrics||[]).filter(function(x){return x.key==='driveType';})[0]; if(dm)dt=dm.value; }
  var kneeSol=dt?(String(dt).indexOf('신전')>=0?'앞무릎 <b>신전형(밀어올리기·에너지 생성)</b> — 앞무릎을 펴며 만든 신전 에너지를 회전·릴리스로 잇는 패턴. 앞무릎 신전 타이밍·신전일 활용을 극대화하는 드릴 권장.':'앞무릎 <b>버팀-흡수형(강성 버팀)</b> — 굽은 앞다리 축으로 회전하며 흡수하는 패턴. 앞무릎 강성 버팀(붕괴 최소화)·선형→회전 전환 효율을 강조.'):'';
  var focus=mt.type==='드라이브-주도형'?'핵심 = 드라이브·블록 체인(스트라이드·뒷발 추진·신전일·COM 속도·앞발 제동) · 회전 변인 다소 낮아도 "약점"이 아니라 유형 특성일 수 있음 → 드라이브·블록 효율 끝까지 끌어올리기에 집중':mt.type==='회전-주도형'?'핵심 = 분리(X-Factor)·외회전·회전 속도 사슬·시퀀스 · 드라이브 변인 낮아도 부차적 → 회전 가속·시퀀스 타이밍·채찍 효율 향상에 집중':'드라이브·회전 동력 균형적 — 양 체인 모두 핵심 · 더 낮은 쪽 우선 보강';
  function chips(arr,col){ return arr.length?arr.map(function(l){return '<span style="display:inline-block;background:'+col+'22;color:'+col+';border:1px solid '+col+'66;border-radius:6px;padding:2px 8px;margin:2px;font-size:12px">'+l+'</span>';}).join(''):'<span class="sub2">해당 없음</span>'; }
  return '<div class="card" style="margin-bottom:12px"><h3>유형별 맞춤 솔루션 <span class="sub2">'+mt.type+' 기준 — 핵심 체인 우선 · 부차 체인 톤다운</span></h3>'
    +'<div style="font-size:12.5px;color:var(--fg1);line-height:1.6;margin:4px 0 10px">'+focus+'</div>'
    +'<div style="margin-bottom:8px"><div class="sub2" style="margin-bottom:3px">우선 향상 (핵심 체인 교정 변인)</div>'+chips(core,'#e8954e')+'</div>'
    +'<div style="margin-bottom:8px"><div class="sub2" style="margin-bottom:3px">유형 특성 — 부차(우선순위 낮음)</div>'+chips(minor,'#a8b3c2')+'</div>'
    +(strongCore.length?'<div style="margin-bottom:8px"><div class="sub2" style="margin-bottom:3px">유지·활용 (핵심 체인 강점)</div>'+chips(strongCore,'#46c98c')+'</div>':'')
    +(kneeSol?'<div class="note" style="margin-top:6px">'+kneeSol+'</div>':'')
    +'<div class="note" style="margin-top:4px">※ 유형=우열이 아니라 동력 전략 · 부차 체인의 낮은 값은 결함이 아닐 수 있음 → 핵심 체인부터 개선</div></div>';
}
// ── 교정 우선순위 TOP 3 (엘리트 대비 편차 절댓값 상위 — design-handoff ISSUE-03) ──
function _bmPriorityTop3(){
  var s=_bmSummary(); if(!s||!s.flagged||!s.flagged.length) return '';
  var top=s.flagged.slice(0,3);  // flagged 는 z 오름차순(가장 음수=가장 큰 결함) 정렬됨
  var cards=top.map(function(f,i){
    var m=f.m, st=f.stage, nm=BIOMOTION_NORMS[m.key], unit=m.unit||'';
    var val=(m.value!=null)?m.value:'—';
    var note=_bmFlagNote(m,nm);
    return '<div class="bm-pri-card">'
      +'<div class="bm-pri-tag">'+(st.label||'')+' · #'+(i+1)+'</div>'
      +'<div class="bm-pri-name">'+m.label+'</div>'
      +'<div class="bm-pri-val"><span class="num">'+val+'<span class="u">'+unit+'</span></span><span class="bm-pri-z">'+_bmZ(f.z)+'</span></div>'
      +'<div class="bm-pri-note">'+note+'</div></div>';
  }).join('');
  return '<div class="card bm-pri-wrap"><div class="bm-pri-head">'
    +'<span class="bm-pri-kicker">교정 우선순위 TOP 3</span>'
    +'<span class="bm-pri-sub">엘리트 대비 편차(σ)가 가장 큰 변인 — 여기부터 개선</span></div>'
    +'<div class="bm-pri-grid">'+cards+'</div></div>';
}
// 교정 변인 한 줄 코칭 메모(중앙값 대비 방향 자동 생성)
function _bmFlagNote(m,nm){
  if(!nm||m.value==null) return '엘리트 정상 범위를 벗어남 — 우선 보강 필요';
  var goodHigh=(nm.p75>=nm.p25); var med=nm.med, u=m.unit||'';
  var lowGood='작을수록 강점', dir;
  // good 방향 판정: _bmEnds 와 동일 의미. value 가 bad 쪽이면 어디로 가야 하는지 안내
  var s=_bmStat(m.value,nm,m.dir);
  var toward=(s.e.good>=s.e.bad)?'↑ 높이기':'↓ 낮추기';
  return '엘리트 중앙값 '+(Math.round(med*10)/10)+u+' 대비 '+toward;
}
// 단계 헤더 미니 분포 막대(강점·정상·교정 6px 스택 — ISSUE-06)
function _bmMiniBar(c){
  var tot=(c.strong+c.normal+c.flag)||1;
  return '<div class="bm-mini-bar" title="강점 '+c.strong+' · 정상 '+c.normal+' · 교정 '+c.flag+'">'
    +'<i style="width:'+(c.strong/tot*100)+'%;background:var(--green)"></i>'
    +'<i style="width:'+(c.normal/tot*100)+'%;background:var(--cyan)"></i>'
    +'<i style="width:'+(c.flag/tot*100)+'%;background:var(--amber)"></i></div>';
}
// "읽는 법" 시각 범례 (텍스트 문단 대체 — ISSUE-05)
function _bmReadLegend(){
  var g='<svg viewBox="0 0 60 14" width="60" height="14" style="display:block">';
  // 띠
  var band=g+'<defs><linearGradient id="lgz" x1="0" x2="1"><stop offset="0" stop-color="var(--amber)" stop-opacity=".5"/><stop offset="1" stop-color="var(--green)" stop-opacity=".5"/></linearGradient></defs><rect x="2" y="4" width="56" height="6" rx="3" fill="url(#lgz)"/></svg>';
  var medG=g+'<line x1="2" y1="7" x2="58" y2="7" stroke="var(--line)" stroke-width="1.4"/><line x1="30" y1="2" x2="30" y2="12" stroke="var(--fg2)" stroke-width="1.4" stroke-dasharray="3 2"/></svg>';
  var youG=g+'<line x1="2" y1="7" x2="58" y2="7" stroke="var(--line)" stroke-width="1.4"/><line x1="22" y1="2" x2="22" y2="12" stroke="var(--cyan)" stroke-width="2"/><circle cx="22" cy="7" r="3.5" fill="var(--cyan)" stroke="var(--bg2)" stroke-width="1.5"/></svg>';
  function cell(svg,t){ return '<div class="bm-leg-cell">'+svg+'<span>'+t+'</span></div>'; }
  var statusCell='<div class="bm-leg-cell"><div class="bm-leg-chips">'
    +'<span style="color:var(--green)">▲ 강점</span><span style="color:var(--cyan)">● 정상</span><span style="color:var(--amber)">▼ 교정</span></div>'
    +'<span>띠 기준 위치로 분류</span></div>';
  return '<div class="card bm-legend-card"><div class="bm-legend-grid">'
    +cell(band,'엘리트 25–75% 정상범위')
    +cell(medG,'점선 = 엘리트 중앙값')
    +cell(youG,'세로선·점 = 이 선수 값')
    +statusCell
    +'</div></div>';
}
// ── sticky 페이즈 내비게이션 (점프 + 교정 카운트 배지 + 교정만 필터 — ISSUE-04) ──
function _bmPhaseNav(){
  var P=(typeof DATA!=='undefined')?DATA.phases:null; if(!P||!P.stages||!P.stages.length) return '';
  var s=_bmSummary();
  var chips=P.stages.filter(function(st){return !st.aux;}).map(function(st){
    var c=s.byStage[st.key]||{flag:0};
    var badge=(c.flag>0)?'<span class="bm-nav-badge">'+c.flag+'</span>':'';
    return '<button class="bm-nav-chip" onclick="_bmJump(\'bmph-'+st.key+'\')">'+st.label+badge+'</button>';
  }).join('');
  return '<div class="bm-phase-nav"><div class="bm-nav-chips">'+chips+'</div>'
    +'<button id="bm-filter-flag" class="bm-nav-filter" onclick="_bmFilterFlag(this)">교정만 보기</button></div>';
}
function _bmJump(id){ var el=document.getElementById(id); if(!el)return; var y=el.getBoundingClientRect().top+window.pageYOffset-150; window.scrollTo({top:y,behavior:'smooth'}); }
function _bmFilterFlag(btn){ var b=document.getElementById('bm-body'); if(!b)return; var on=b.classList.toggle('bm-filter-flag'); if(btn){ btn.classList.toggle('on',on); btn.textContent=on?'전체 보기':'교정만 보기'; } }
function _bmTallyBar(){
  var s=_bmSummary(), tot=(s.strong+s.normal+s.flag)||1;
  var bar='<div style="height:9px;border-radius:999px;overflow:hidden;display:flex;background:var(--bg2);margin-top:8px">'
    +'<i style="display:block;height:100%;width:'+(s.strong/tot*100)+'%;background:var(--green)"></i>'
    +'<i style="display:block;height:100%;width:'+(s.normal/tot*100)+'%;background:var(--cyan)"></i>'
    +'<i style="display:block;height:100%;width:'+(s.flag/tot*100)+'%;background:var(--amber)"></i></div>';
  return '<div class="card" style="margin-bottom:12px"><div style="display:flex;gap:22px;flex-wrap:wrap;align-items:baseline">'
    +'<div><span style="font-size:26px;font-weight:800;color:var(--green)">'+s.strong+'</span> <span style="font-size:12px;color:var(--fg2)">강점</span></div>'
    +'<div><span style="font-size:26px;font-weight:800;color:var(--cyan)">'+s.normal+'</span> <span style="font-size:12px;color:var(--fg2)">정상</span></div>'
    +'<div><span style="font-size:26px;font-weight:800;color:var(--amber)">'+s.flag+'</span> <span style="font-size:12px;color:var(--fg2)">교정 대상</span></div>'
    +'<div style="margin-left:auto;font-size:11px;color:var(--fg2)">엘리트 규준 코호트(n=19) 25–75% 띠 대비 · 점수 없이 위치로 판정</div></div>'+bar+'</div>';
}
function _phaseHdr(){ return '<div class="bm-row bm-row-header"><div class="bm-row-label">변인</div><div class="bm-row-value">측정값 · 편차</div><div class="bm-row-bar">엘리트 25–75% 규준 대비</div><div class="bm-row-mph"></div><div class="bm-row-score">상세</div></div>'; }
