  ctx.save(); ctx.translate(12,pr.y+pr.h/2); ctx.rotate(-Math.PI/2); ctx.textBaseline='middle'; ctx.fillStyle='#a8b3c2'; ctx.fillText(opt.yLabel||'',0,0); ctx.restore();
