var _EASY_IDX=(function(){ var m={}; Object.keys(_EASY_COACH).forEach(function(k){ _EASY_COACH[k].forEach(function(it){ m[it.t]=it; }); }); return m; })();
function _easyFor(title){ if(!title) return null; for(var i=0;i<_EASY_KW.length;i++){ if(title.indexOf(_EASY_KW[i][0])>=0) return _EASY_IDX[_EASY_KW[i][1]]||null; } return null; }
function _easyInner(it){ return '<div class="note" style="margin-top:2px"><b>무엇을 보나요?</b> '+it.w+'</div><div class="note" style="margin-top:5px"><b>약하면?</b> '+it.lo+'</div><div class="note" style="margin-top:5px"><b>주된 이유</b><ul style="margin:3px 0 0 16px;padding:0">'+it.why.map(function(x){return '<li>'+x+'</li>';}).join('')+'</ul></div><div class="note" style="margin-top:5px"><b>고치는 방법</b><div style="margin-top:2px">· 큐: <b style="color:var(--cyan)">'+it.cue+'</b></div><div>· 드릴: '+it.dr+'</div><div>· 목표: '+it.tg+'</div></div>'; }
// ── 진단 단계별 인라인 측면 스틱(관련 분절 강조 + 스크러버로 시계열 커서 동기화) ──
var _ED_STICK_SEG={
  windup:{hi:['trunk','pelvis'],label:'몸통·골반(힙힌지 로딩)',desc:'와인드업 로딩 — 몸통-골반 굽힘과 골반 닫힘을 봅니다.'},
  xftiming:{hi:['trunk','pelvis'],label:'골반-몸통 분리(X-factor)',desc:'골반과 몸통이 얼마나 분리되어 회전 준비가 되었는지, 착지까지 유지되다 풀리는지 봅니다.'},
  stride:{hi:['leadleg'],label:'앞다리·전진',desc:'앞다리 착지와 COM 전진 운동량 형성을 봅니다.'},
  blocking:{hi:['leadleg'],label:'앞다리 제동',desc:'앞발이 전진을 멈추는 제동(FC~제동 peak)을 봅니다.'},
  knee:{hi:['leadleg'],kneeDot:true,label:'앞무릎',desc:'앞무릎이 버티는지·펴는지·흡수하는지를 봅니다.'},
  pelvistrunk:{hi:['pelvis','trunk'],label:'골반→몸통',desc:'골반 회전이 몸통 회전으로 증폭되는지를 봅니다.'},
  trunk:{hi:['trunk'],label:'몸통 회전·굴곡',desc:'몸통 회전과 앞으로 굴곡하는 에너지 생산을 봅니다.'},
  trunkarm:{hi:['trunk','arm'],label:'몸통→팔',desc:'몸통 에너지가 던지는 팔로 넘어가는지를 봅니다.'},
  armball:{hi:['arm'],label:'팔→공',desc:'어깨 내회전→팔꿈치 신전→손 속도→릴리스 시퀀스를 봅니다.'}
};
function _edStickWin(key,t){ var e=t.events||{}, dt=(t.meta&&t.meta.dt)||0.00333, nF=(t.frames||[]).length-1;
  var KH=e.i_kl_peak||0, FC=e.i_fc||0, BR=(e.i_br!=null?e.i_br:nF), MER=e.i_mer||FC;
  function p(base,ms){ return Math.round(base+ms/1000/dt); }
  var W={windup:[KH,FC],xftiming:[KH,BR],stride:[KH,FC],blocking:[FC,p(FC,150)],knee:[FC,BR],pelvistrunk:[KH,BR],trunk:[KH,BR],trunkarm:[FC,BR],armball:[MER,BR]};
  var w=W[key]||[KH,BR]; return [Math.max(0,Math.min(w[0],nF)),Math.max(0,Math.min(w[1],nF))];
}
function _edStickBones(arm,lead){ return [
  ['head','neck','head'],['neck','MIDHIP','trunk'],['neck',lead+'_shoulder','shoulder'],['neck',arm+'_shoulder','shoulder'],
  [lead+'_hip',arm+'_hip','pelvis'],
  [arm+'_shoulder',arm+'_elbow','arm'],[arm+'_elbow',arm+'_wrist','arm'],[arm+'_wrist',arm+'_hand_tip','arm'],
  [lead+'_shoulder',lead+'_elbow','glove'],[lead+'_elbow',lead+'_wrist','glove'],
  [lead+'_hip',lead+'_knee','leadleg'],[lead+'_knee',lead+'_heel','leadleg'],[lead+'_heel',lead+'_toe','leadleg'],
  [arm+'_hip',arm+'_knee','rearleg'],[arm+'_knee',arm+'_heel','rearleg'],[arm+'_heel',arm+'_toe','rearleg']
]; }
function _edStickDraw(key){
  var cv=document.getElementById('edstk-'+key); if(!cv) return;
  var t=(typeof _fastTrial==='function')?_fastTrial():null; if(!t||!t.frames) return;
  var win=_edStickWin(key,t), e=t.events||{}, dt=(t.meta&&t.meta.dt)||0.00333;
  var cf=(typeof _currentFrame!=='undefined'&&_currentFrame!=null)?Math.round(_currentFrame):win[0];
  cf=Math.max(win[0],Math.min(win[1],cf));
  var fr=t.frames[cf]||{};
  var RHP=(((DATA.player&&DATA.player.handedness)||'R').toUpperCase()!=='L'), arm=RHP?'r':'l', lead=RHP?'l':'r';
  function J(name){ if(name==='MIDHIP'){ var a=fr[lead+'_hip'],b=fr[arm+'_hip']; return (a&&b)?[(a[2]+b[2])/2,(a[1]+b[1])/2]:null; } var j=fr[name]; return (j&&isFinite(j[2])&&isFinite(j[1]))?[j[2],j[1]]:null; }
  var seg=_ED_STICK_SEG[key]||{hi:[]}, bones=_edStickBones(arm,lead);
  var xs=[],ys=[]; bones.forEach(function(b){ var p1=J(b[0]),p2=J(b[1]); if(p1){xs.push(p1[0]);ys.push(p1[1]);} if(p2){xs.push(p2[0]);ys.push(p2[1]);} });
  var c=clearC(cv),ctx=c.ctx,w=c.w,h=c.h;
  if(!xs.length){ ctx.fillStyle='#a8b3c2';ctx.textAlign='center';ctx.fillText('— 프레임 없음 —',w/2,h/2); return; }
  var xmin=Math.min.apply(null,xs),xmax=Math.max.apply(null,xs),ymin=Math.min.apply(null,ys),ymax=Math.max.apply(null,ys);
  var pad=18, sc=Math.min((w-2*pad)/((xmax-xmin)||1),(h-2*pad)/((ymax-ymin)||1));
  var ox=(w-(xmax-xmin)*sc)/2-xmin*sc, oy=h-pad+ymin*sc;
  function X(p){return ox+p[0]*sc;} function Y(p){return oy-p[1]*sc;}
  // 홈 방향(우측 위) 화살표
  ctx.strokeStyle='#3a4452';ctx.fillStyle='#a8b3c2';ctx.lineWidth=1;ctx.font='10.5px system-ui';
  ctx.beginPath();ctx.moveTo(w-14,h-12);ctx.lineTo(w-14,18);ctx.stroke();ctx.beginPath();ctx.moveTo(w-14,12);ctx.lineTo(w-17,19);ctx.lineTo(w-11,19);ctx.closePath();ctx.fill();ctx.fillText('홈',w-24,12);
  bones.forEach(function(b){ var p1=J(b[0]),p2=J(b[1]); if(!p1||!p2)return; var hiOn=seg.hi.indexOf(b[2])>=0; ctx.strokeStyle=hiOn?'#1d9e75':'#8a8f98'; ctx.lineWidth=hiOn?3.4:2; ctx.lineCap='round'; ctx.beginPath();ctx.moveTo(X(p1),Y(p1));ctx.lineTo(X(p2),Y(p2));ctx.stroke(); });
  var hd=J('head'); if(hd){ ctx.fillStyle='#8a8f98';ctx.beginPath();ctx.arc(X(hd),Y(hd),5,0,7);ctx.fill(); }
  if(seg.kneeDot){ var k=J(lead+'_knee'); if(k){ ctx.fillStyle='#D85A30';ctx.beginPath();ctx.arc(X(k),Y(k),5.5,0,7);ctx.fill();ctx.strokeStyle='#0b0d12';ctx.lineWidth=1.3;ctx.stroke(); } }
  var lab=document.getElementById('edstk-t-'+key); if(lab){ var ms=Math.round((cf-(e.i_fc||0))*dt*1000); lab.textContent='FC'+(ms>=0?'+':'')+ms+'ms'; }
}
// 변인 카드용 스틱 게이지 — 현재 프레임(_currentFrame, 좌측 3D 스틱 동기) 측면 자세, 관련 분절(hiArr) 녹색 강조
// 카드 스틱 게이지(측면) — 골반(MIDHIP) 기준 상대좌표 + 윈도우 전체 고정 스케일 → 재생 중 크기·위치 일정.
// opt.win=[w0,w1] 스케일 산출 구간, opt.readout=[{txt,color,big}] 현재 프레임 수치 오버레이.
function _edCardStick(cid, hiArr, opt){
  opt=opt||{};
  var _HZ=(opt.view==='side')?2:0;  /* [2026-05-29] rear/front=정면(x,y) / side=측면(z,y) */
  var _MX=((opt.view==='front')?-1:1)*((_HZ===0)?_mirrorScaleSign(DATA&&DATA.player&&DATA.player.handedness):1);  /* x축 투영에서만 좌완 미러 */
  var cv=document.getElementById(cid); if(!cv) return;
  var t=(typeof _fastTrial==='function')?_fastTrial():null; if(!t||!t.frames) return;
  var nF=t.frames.length-1;
  var RHP=(((DATA.player&&DATA.player.handedness)||'R').toUpperCase()!=='L'), arm=RHP?'r':'l', lead=RHP?'l':'r';
  var bones=_edStickBones(arm,lead), hi=hiArr||[]; if(opt.only){ bones=bones.filter(function(b){return opt.only.indexOf(b[2])>=0;}); } var _aj=opt.anchorHeel?(lead+'_heel'):null;
  // 골반 중심(MIDHIP) 기준 상대좌표 — 전진 이동 제거 → 그림이 가운데 고정
  function anc(fr){ if(_aj){var _jj=fr[_aj];return (_jj&&isFinite(_jj[_HZ])&&isFinite(_jj[1]))?[_jj[_HZ],_jj[1]]:null;} var a=fr[lead+'_hip'],b=fr[arm+'_hip']; return (a&&b&&isFinite(a[_HZ])&&isFinite(b[_HZ])&&isFinite(a[1])&&isFinite(b[1]))?[(a[_HZ]+b[_HZ])/2,(a[1]+b[1])/2]:null; }
  function J(fr,name){ var an=anc(fr); if(!an)return null; if(name==='MIDHIP')return [0,0]; var j=fr[name]; return (j&&isFinite(j[_HZ])&&isFinite(j[1]))?[(j[_HZ]-an[0])*_MX, j[1]-an[1]]:null; }
  // 윈도우 전체에서 bbox(상대좌표) → 고정 스케일
  var w0=0,w1=nF; if(opt.win){ w0=Math.max(0,opt.win[0]); w1=Math.min(nF,opt.win[1]); }
  var xmin=1e9,xmax=-1e9,ymin=1e9,ymax=-1e9;
  for(var fi=w0;fi<=w1;fi++){ var f=t.frames[fi]; if(!f)continue; for(var bi=0;bi<bones.length;bi++){ var b=bones[bi]; var p1=J(f,b[0]),p2=J(f,b[1]); [p1,p2].forEach(function(p){ if(p){ if(p[0]<xmin)xmin=p[0]; if(p[0]>xmax)xmax=p[0]; if(p[1]<ymin)ymin=p[1]; if(p[1]>ymax)ymax=p[1]; } }); } }
  var c=clearC(cv),ctx=c.ctx,w=c.w,h=c.h; if(xmin>xmax){ return; }
  var pad=12, sc=Math.min((w-2*pad)/((xmax-xmin)||1),(h-2*pad)/((ymax-ymin)||1));
  var ox=(w-(xmax-xmin)*sc)/2-xmin*sc, oy=(h-(ymax-ymin)*sc)/2+ymax*sc;
  function X(p){return ox+p[0]*sc;} function Y(p){return oy-p[1]*sc;}
  var cf=(typeof _currentFrame!=='undefined'&&_currentFrame!=null)?Math.round(_currentFrame):((t.events&&t.events.i_br)||nF);
  cf=Math.max(0,Math.min(nF,cf)); var fr=t.frames[cf]||{};
  bones.forEach(function(b){ var p1=J(fr,b[0]),p2=J(fr,b[1]); if(!p1||!p2)return; var on=hi.indexOf(b[2])>=0; ctx.strokeStyle=on?'#1d9e75':'#8a8f98'; ctx.lineWidth=on?3.4:1.8; ctx.lineCap='round'; ctx.beginPath();ctx.moveTo(X(p1),Y(p1));ctx.lineTo(X(p2),Y(p2));ctx.stroke(); });
  if(!opt.only){ var hd=J(fr,'head'); if(hd){ ctx.fillStyle='#8a8f98';ctx.beginPath();ctx.arc(X(hd),Y(hd),4,0,7);ctx.fill(); } }
  if(opt.readout) _edStickReadout(cid, opt.readout);
}
// 스틱 게이지 캔버스 좌상단에 현재 프레임 수치 오버레이
function _edStickReadout(cid, lines){
  var cv=document.getElementById(cid); if(!cv||!lines||!lines.length) return;
  var dpr=window.devicePixelRatio||1, ctx=cv.getContext('2d'); ctx.setTransform(dpr,0,0,dpr,0,0);
  ctx.textAlign='left'; ctx.textBaseline='top'; var y=6;
  lines.forEach(function(l){ if(!l||_isStickAngleLabel(l.txt))return; ctx.font='bold '+(l.big?15:12)+'px system-ui'; ctx.fillStyle=l.color||'#cdd6e2'; ctx.fillText(l.txt,7,y); y+=(l.big?19:15); });
}
// ── 진단2~9 공통: 폴더용 이벤트 테이블 + 변인 정의 카드(전역) ──
function _edFoldG(label,inner){ return '<details style="margin-top:8px;border:1px solid var(--line);border-radius:8px;background:var(--bg2)"><summary style="cursor:pointer;padding:8px 11px;font-size:12px;font-weight:700;color:var(--cyan)">'+label+'</summary><div style="padding:2px 11px 11px">'+inner+'</div></details>'; }
function _edDefCardG(d){ return '<div class="note" style="line-height:1.85"><b>정의</b> '+(d.def||'')+'<br><b>산출 방법</b> '+(d.calc||'')+'<br><b>결과 해석</b> '+(d.interp||'')+'<br><b>평가 방법</b> '+(d.evalm||'')+'</div>'; }
function _edEvtListG(idxMap, fast){ var ix=idxMap||{}, mer=(fast&&fast.events)?fast.events.i_mer:null; return [['KH',ix.KH],['SO',ix.SO],['FC',ix.FC],['MER',mer],['BR',ix.BR]].filter(function(e){return e[1]!=null&&isFinite(e[1]);}); }
function _edEvtTableG(EVT, rows){ var th='<tr><th style="text-align:left;padding:4px 6px">변인</th>'+EVT.map(function(e){return '<th style="padding:4px 6px;text-align:right">'+e[0]+'</th>';}).join('')+'</tr>';
  var tr=rows.map(function(rw){ return '<tr><td style="text-align:left;padding:4px 6px">'+rw.label+(rw.unit?' <span style="color:var(--fg2)">('+rw.unit+')</span>':'')+'</td>'+EVT.map(function(e){var val=rw.get(e[1]);return '<td style="text-align:right;padding:4px 6px">'+(val==null?'–':val)+'</td>';}).join('')+'</tr>'; }).join('');
  return '<table class="ev-table" style="width:100%;border-collapse:collapse;font-size:11.5px;margin-top:2px">'+th+tr+'</table><div class="note" style="font-size:11px;margin-top:5px;color:var(--fg2)">값 = 각 이벤트 프레임에서의 변인 값 (폴더·기록용). KH 뒷무릎 최고높이 · SO 스트라이드 시작 · FC 앞발 착지 · MER 어깨 최대외회전 · BR 릴리스</div>'; }
// 시리즈 name 의 frame 값(prec 자리, abs 옵션)
function _edSV(fast,name,frame,prec,abs){ var a=fast&&fast.series&&fast.series[name]; if(!a||!isFinite(a[frame]))return null; var v=a[frame]; if(abs)v=Math.abs(v); var p=(prec==null?1:prec); return Math.round(v*p)/p; }
// COM 자체 경로의 휘어짐(좌우 편차, m) 시계열. + = 글러브 쪽, − = 던지는 팔 쪽.
//  COM(KH)→COM(FC) 직선(전진 방향)을 기준선으로 두고, 각 프레임 COM이 그 직선에서 좌우로 벗어난 수직거리.
//  발 배치 각도와 무관하게 "전진 운동이 옆으로 새는(사이드 워블)" 정도만 본다.
function _strideLatDevSeries(t){
  if(!t||!t.series||!t.events) return null;
  var S=t.series, e=t.events, rhp=(typeof _bmRHP==='function')?_bmRHP():true;
  var cx=S.Pelvis_COM_X, cy=S.Pelvis_COM_Y;
  if(!cx||!cy) return null;
  var ifc=(e.i_fc!=null&&e.i_fc<cx.length)?e.i_fc:(cx.length-1);
  var i0=(e.i_kl_peak!=null&&e.i_kl_peak<cx.length)?e.i_kl_peak:0;
  var ax=cx[i0], ay=cy[i0], bx=cx[ifc], by=cy[ifc];
  if(!(isFinite(ax)&&isFinite(ay)&&isFinite(bx)&&isFinite(by))) return null;
  var ux=bx-ax, uy=by-ay, Ln=Math.sqrt(ux*ux+uy*uy)||1; ux/=Ln; uy/=Ln;
  var nx=-uy, ny=ux, sgn=rhp?1:-1; // 좌우 부호를 좌/우완 일관되게(+ 글러브 쪽)
  return cx.map(function(x,i){ var y=cy[i]; if(!isFinite(x)||!isFinite(y)) return NaN; return sgn*((x-ax)*nx+(y-ay)*ny); });
}
// 한 단계의 폴더 영역(이벤트 표 + 변인 정의) 카드 1개 생성
function _edStageFolds(fast, idxMap, evRows, defRows){
  var EVT=_edEvtListG(idxMap, fast);
  var tbl=(evRows&&evRows.length&&EVT.length)? _edFoldG('이벤트별 데이터 표', _edEvtTableG(EVT, evRows)) : '';
  var def=(defRows&&defRows.length)? _edFoldG('변인 정의·산출·해석·평가', defRows.map(function(d){return '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--line)"><div style="font-size:12px;font-weight:700;color:var(--fg0)">'+d.name+'</div>'+_edDefCardG(d)+'</div>';}).join('')) : '';
  if(!tbl&&!def) return '';
  return '<div class="card" style="grid-column:1 / -1"><div style="font-size:12px;font-weight:800;color:var(--fg1)">변인 데이터·정의</div>'+tbl+def+'</div>';
}
// 증거(_WG) 탑뷰/뒷발 게이지를 진단 카드 캔버스에 그린다 — 메인 3D 스틱(_currentFrame)에 동기화
function _edWGStick(key, cvId){
  if(!document.getElementById(cvId)) return;
  try{ if(!_WG.data) _WG.data=_WG.build(); }catch(e){}
  if(!_WG.data || !_WG.data.fast || !_WG.data.fast.series) return;
  if(key==='freeMo'){ try{ _WG.initFoot(); }catch(e){} }
  var nF=(_WG.data.fast.series.top||[]).length-1; if(nF<0) return;
  var cf=(typeof _currentFrame!=='undefined'&&_currentFrame!=null)?Math.round(_currentFrame):nF;
  _WG.idx=Math.max(0,Math.min(nF,cf));
  var G={key:key};
  try{ if(key==='freeMo') _WG.drawFoot(G,cvId); else _WG.drawTop(G,cvId); }catch(e){}
}
var _edStickRAF={};
function _edStickAttach(key){
  var root=document.getElementById('ed-body-'+key); if(!root) return;
  var t=(typeof _fastTrial==='function')?_fastTrial():null; if(!t||!t.frames){ return; }
  if(document.getElementById('edstk-wrap-'+key)){ _edStickDraw(key); return; }
  var win=_edStickWin(key,t), seg=_ED_STICK_SEG[key]||{};
  var card=document.createElement('div'); card.className='card'; card.id='edstk-wrap-'+key; card.style.gridColumn='1 / -1';
  card.innerHTML='<div style="font-size:13px;font-weight:800">동작 스틱(측면) · <span style="color:var(--cyan)">'+(seg.label||'')+' 강조</span> <span class="sub2">스크러버로 좌측 시계열 커서와 함께 이동 · 윈도우=단계 구간</span></div>'
    +'<div style="display:flex;gap:14px;align-items:flex-start;flex-wrap:wrap;margin-top:6px"><canvas id="edstk-'+key+'" style="width:300px;height:226px;flex:0 0 300px;display:block"></canvas>'
    +'<div style="flex:1;min-width:220px"><div style="display:flex;align-items:center;gap:8px"><button id="edstk-play-'+key+'" class="bm-focus-btn" style="font-size:12px;background:var(--bg1);border:1px solid var(--line);color:var(--cyan);border-radius:6px;padding:5px 12px;cursor:pointer">재생</button>'
    +'<input type="range" id="edstk-sl-'+key+'" min="'+win[0]+'" max="'+win[1]+'" value="'+win[0]+'" step="1" style="flex:1"><span id="edstk-t-'+key+'" class="note" style="min-width:64px;text-align:right"></span></div>'
    +'<div class="note" style="margin-top:8px">'+(seg.desc||'')+' 녹색=관련 분절 강조.</div></div></div>';
  root.insertBefore(card, root.firstChild);
  var sl=document.getElementById('edstk-sl-'+key), pb=document.getElementById('edstk-play-'+key);
  sl.addEventListener('input',function(){ _currentFrame=parseInt(sl.value,10); _edStickDraw(key); try{_queueCharts();}catch(e){} });
  pb.addEventListener('click',function(){
    if(_edStickRAF[key]){ cancelAnimationFrame(_edStickRAF[key]); _edStickRAF[key]=null; pb.textContent='재생'; return; }
    pb.textContent='정지'; var last=performance.now();
    (function tick(now){ var d=(now-last)/1000; last=now; var dtt=(t.meta&&t.meta.dt)||0.00833; var step=Math.max(1,Math.round(d/dtt*0.5));
      var nf=(parseInt(sl.value,10)||win[0])+step; if(nf>=win[1])nf=win[0]; sl.value=nf; _currentFrame=nf; _edStickDraw(key); try{_queueCharts();}catch(e){}
      _edStickRAF[key]=requestAnimationFrame(tick); })(last);
  });
  _currentFrame=win[0]; _edStickDraw(key);
}
// ── 선수 요약(UX 재설계 지침 v1): 9단계 종합 → 한 문장·강점·TOP3 병목·우선과제·다음 목표·팔 부담 ──
function _ps9(){
  var X=(typeof ETDIAG!=='undefined')?ETDIAG:null; if(!X) return null;
  var d=[
    ['windup','와인드업','와인드업 로딩 형성',X.windup&&X.windup.composite,0.5,'ed-windup',X.windup&&X.windup.typeKo,X.windup&&X.windup.summary,X.windup&&X.windup.type,'store'],
    ['xftiming','몸통 꼬임·풀림 타이밍','몸통 꼬임 보존·풀림 타이밍',X.xftiming&&X.xftiming.timingScore,0.9,'ed-xftiming',X.xftiming&&X.xftiming.typeKo,X.xftiming&&X.xftiming.summary,X.xftiming&&X.xftiming.type,'eff'],
    ['stride','스트라이드','스트라이드 전진 에너지',X.stride&&X.stride.momentumScore,0.7,'ed-stride',X.stride&&X.stride.typeKo,X.stride&&X.stride.summary,X.stride&&X.stride.type,'out'],
    ['blocking','앞발 제동','블로킹: 전진 에너지 제동',X.blocking&&X.blocking.functionalScore,0.9,'ed-blocking',X.blocking&&X.blocking.typeKo,X.blocking&&X.blocking.summary,X.blocking&&X.blocking.type,'out'],
    ['knee',_kneeUiName(),'유형·연결·타이밍',null,0.9,'ed-blocking',X.knee5&&X.knee5.typeKo,X.knee5&&X.knee5.summary,X.knee5&&X.knee5.type,'eff'],
    ['pelvistrunk','골반-몸통','골반→몸통 회전 증폭',X.pelvistrunk6&&X.pelvistrunk6.ampScore,1.0,'ed-pelvistrunk',X.pelvistrunk6&&X.pelvistrunk6.typeKo,X.pelvistrunk6&&X.pelvistrunk6.summary,X.pelvistrunk6&&X.pelvistrunk6.type,'eff'],
    ['trunk','몸통 에너지','몸통 회전+굴곡 에너지',X.trunk7&&X.trunk7.prodScore,0.85,'ed-trunk',X.trunk7&&X.trunk7.typeKo,X.trunk7&&X.trunk7.summary,X.trunk7&&X.trunk7.type,'out'],
    ['trunkarm','몸통-팔','몸통→팔 전달 맞물림',X.trunkarm8&&X.trunkarm8.taScore,1.2,'ed-trunkarm',X.trunkarm8&&X.trunkarm8.typeKo,X.trunkarm8&&X.trunkarm8.summary,X.trunkarm8&&X.trunkarm8.type,'load'],
    ['armball','팔-공','팔→공 방출 효율·부하',X.armball9&&X.armball9.abScore,0.7,'ed-armball',X.armball9&&X.armball9.typeKo,X.armball9&&X.armball9.summary,X.armball9&&X.armball9.type,'load']
  ];
  return d.map(function(x){
    var sc=(x[3]==null?null:Math.round(x[3]));
    var st;
    if(x[0]==='knee'){
      var k5=X.knee5;
      st=!k5?'na':((k5.type==='collapse'||k5.type==='ext_late_collapse')?'bottleneck':((k5.coupling==='good'||k5.coupling==='양호')?'good':'caution'));
    } else {
      st=sc==null?'na':(sc>=78?'good':(sc>=62?'caution':'bottleneck'));
    }
    return {key:x[0],pName:x[1],cName:x[2],score:sc,imp:x[4],tab:x[5],typeKo:x[6],summary:x[7],type:x[8],status:st,cat:x[9]};
  });
}
