  var COL={low:'#46c98c',moderate:'#e8954e',high:'#e24b4a'}[I.level]||'#a8b3c2';
  function v(x,u){return x==null?'–':(x+(u||''));}
  function lvc(l){return l==null?'#a8b3c2':['#46c98c','#e8954e','#e24b4a'][l];}
