  function btn(lbl,pg2){return '<button class="bm-focus-btn" onclick="setPage(\''+pg2+'\')" style="font-size:12px;background:var(--bg1);border:1px solid var(--line);color:var(--cyan);border-radius:6px;padding:4px 10px;cursor:pointer;margin:2px 4px 2px 0">'+lbl+'</button>';}
  function kpi(lbl,val,col){return '<div style="flex:1 1 150px;background:var(--bg2);border-radius:8px;padding:9px 11px"><div class="note" style="font-size:11px">'+lbl+'</div><div style="font-size:16px;font-weight:800;margin-top:2px;color:'+(col||'inherit')+'">'+val+'</div></div>';}
  var h='<div class="card" style="grid-column:1 / -1;border-left:4px solid '+COL+'">'
    +'<div style="display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:8px"><div style="font-size:14px;font-weight:800">진단 기반 팔 부담·부하 평가</div><div style="font-size:13px;font-weight:800;color:'+COL+'">팔 부담 '+I.levelKo+'</div></div>'
    +'<div class="note" style="margin-top:3px">'+I.basis+' · <b>부상 예측이 아니라 "구속을 만드는 팔 부담 비용"</b> 관점</div>'
