function _fvBtn(tab){ return '<button type="button" class="bm-focus-btn" onclick="setPage(\''+tab+'\')" style="font-size:12px;background:var(--bg1);border:1px solid var(--line);color:var(--cyan);border-radius:6px;padding:5px 11px;cursor:pointer;margin-top:8px">자세히 보기 (연구자 분석) ›</button>'; }
