window._fvApplyHighlight=function(phaseKey){
  if(_isCoachReportMode()){ window._fvClearHighlight(); return; }
  var FS=FEEDBACK_SUMMARY||(DATA&&DATA.feedbackSummary); if(!FS) return;
  var hi=FS.highlight||{};
  if(phaseKey&&typeof feedbackSummary!=='undefined'&&feedbackSummary.HIGHLIGHT){
    var h=feedbackSummary.HIGHLIGHT[phaseKey]; if(h) hi={phase:phaseKey,label:h.label,caption:hi.caption,startEv:h.startEv,startOff:h.startOff,endEv:h.endEv,endOff:h.endOff};
  }
  var trial=_fvSelectedTrial(), win=_fvResolveHighlight(trial,hi);
  if(!win){ _fvSyncStickBanner(false); return; }
  window._fvHighlightPhase=hi.phase||phaseKey||'block';
  try{ if(typeof stick3D!=='undefined'&&stick3D.setHighlightRange) stick3D.setHighlightRange(win.i0,win.i1); }catch(e){}
  var mid=Math.round((win.i0+win.i1)/2);
  try{ if(typeof playback!=='undefined'&&playback.setFrame) playback.setFrame(mid); }catch(e){ _currentFrame=mid; }
  _fvSyncStickBanner(true, hi.label||'구간');
};
window._fvClearHighlight=function(){
  window._fvHighlightPhase=null;
  try{ if(typeof stick3D!=='undefined'&&stick3D.clearHighlightRange) stick3D.clearHighlightRange(); }catch(e){}
  _fvSyncStickBanner(false);
};
window._fvJumpHighlight=function(which){
  if(!window._fvHighlightPhase){ window._fvApplyHighlight(); return; }
  var FS=FEEDBACK_SUMMARY||(DATA&&DATA.feedbackSummary); if(!FS||!FS.highlight) return;
  var hi=FS.highlight, trial=_fvSelectedTrial(), win=_fvResolveHighlight(trial,hi);
  if(!win) return;
  var f=which==='end'?win.i1:(which==='start'?win.i0:Math.round((win.i0+win.i1)/2));
  try{ if(typeof playback!=='undefined'&&playback.setFrame) playback.setFrame(f); }catch(e){ _currentFrame=f; }
};
function _fvReapplyHighlight(){
  if(_isCoachReportMode()){ window._fvClearHighlight(); return; }
  var ap=document.querySelector('.tab.active');
  if(!ap||ap.dataset.page!=='feedback-view') return;
  if(window._fvHighlightPhase) window._fvApplyHighlight(window._fvHighlightPhase);
  else window._fvApplyHighlight();
}
