      +(ng.successHint?('<div class="note" style="margin-top:4px;line-height:1.55"><b>감각·에너지</b> · '+_fvEsc(ng.successHint)+'</div>'):'')
      +(ng.l3&&ng.l3.mechanicLine&&(tier==='pro'||tier==='elite')?('<div class="note" style="margin-top:4px;line-height:1.6"><b>메카닉 맥락</b> · '+_fvEsc(ng.l3.mechanicLine)+'</div>'):'')
      +(cues?('<div class="note" style="margin-top:4px"><b>관찰</b><ul style="margin:4px 0 0 18px">'+cues+'</ul></div>'):'')
