        +'<div style="padding:11px 14px;border-right:1px solid var(--line)">'
        +'<div style="font-size:12px;font-weight:800;color:#9c8cff">체력 (엔진 — S&amp;C)</div>'
        +(fitSc==null?'<div class="note" style="color:var(--fg2);margin-top:6px">체력 측정 없음</div>'
          :_gauge('linear-gradient(90deg,#7048e8,#c4b3f3)','점수 · /100',fitSc,null))
        +'<div style="margin-top:6px;font-size:11px;color:#9c8cff">경로: 웨이트·플라이오메트릭</div>'
        +'</div>'
        // 메카닉 출력
        +'<div style="padding:11px 14px;border-right:1px solid var(--line)">'
        +'<div style="font-size:12px;font-weight:800;color:#5bd3ff">메카닉 출력 (생성 단계)</div>'
        +_gauge('linear-gradient(90deg,#1b80c4,#5bd3ff)','점수 · 백분위',outSc,outPct)
        +(genWorst?'<div style="margin-top:6px;font-size:11px"><b style="color:#5bd3ff">생성 약한 곳:</b> '+(NODE_NAME[genWorst.k]||genWorst.k)+' '+genWorst.sc+'점</div>':'')
        +'<div style="margin-top:6px;font-size:11px;color:#5bd3ff">경로: 생성 메카닉 드릴</div>'
