var _cvAdopted={};
function _cvRestoreAll(){
  Object.keys(_cvAdopted).forEach(function(key){
    var el=document.getElementById('ed-body-'+key);
    var rec=_cvAdopted[key];
    if(el&&rec&&rec.parent){
      if(rec.nextSibling) rec.parent.insertBefore(el,rec.nextSibling);
      else rec.parent.appendChild(el);
    }
  });
  _cvAdopted={};
}
function _cvAdoptInto(key, slot){
  var el=document.getElementById('ed-body-'+key);
  if(!el||!slot) return false;
  if(!_cvAdopted[key]){
    _cvAdopted[key]={parent:el.parentNode, nextSibling:el.nextSibling};
  }
  slot.appendChild(el);
  try{ renderEdNode(key); }catch(e){console.warn('renderEdNode',key,e);}
  return true;
}
