// [2026-06-03 valid_trial_policy §4 P1] 선수 UI 반복성 라벨 — CV 우선, |평균|≤SD(0근처) 변인은 SD·range
function _repeatMeta(x){
  if(!x) return null;
  var P=_EFPAL;
  var cv=(x.cv!=null&&isFinite(x.cv)&&x.cv<=60)?x.cv:null;
  if(cv!=null){
    if(cv<5) return {label:'반복성 높음',color:P.good,detail:'CV '+Math.round(cv*10)/10+'%'};
    if(cv<15) return {label:'반복성 보통',color:P.warn,detail:'CV '+Math.round(cv*10)/10+'%'};
    return {label:'반복성 낮음',color:P.bad,detail:'CV '+Math.round(cv*10)/10+'%'};
  }
  var u=x.unit||'', sd=x.sd, rng=x.range;
  if(sd==null&&rng==null) return null;
  if(u==='°'||u==='°/s'){
    if(sd!=null){
      if(sd<1.5) return {label:'반복성 높음',color:P.good,detail:'편차 ±'+Math.round(sd*10)/10+u};
      if(sd<3.5) return {label:'반복성 보통',color:P.warn,detail:'편차 ±'+Math.round(sd*10)/10+u};
      return {label:'반복성 낮음',color:P.bad,detail:'편차 ±'+Math.round(sd*10)/10+u};
    }
    if(rng!=null){
      if(rng<3) return {label:'반복성 높음',color:P.good,detail:'구간 '+Math.round(rng*10)/10+'°'};
      if(rng<7) return {label:'반복성 보통',color:P.warn,detail:'구간 '+Math.round(rng*10)/10+'°'};
      return {label:'반복성 낮음',color:P.bad,detail:'구간 '+Math.round(rng*10)/10+'°'};
    }
  }
  if(u==='s'&&sd!=null){
    if(sd<0.04) return {label:'반복성 높음',color:P.good,detail:'편차 ±'+Math.round(sd*100)/100+'s'};
    if(sd<0.08) return {label:'반복성 보통',color:P.warn,detail:'편차 ±'+Math.round(sd*100)/100+'s'};
    return {label:'반복성 낮음',color:P.bad,detail:'편차 ±'+Math.round(sd*100)/100+'s'};
  }
  if(sd!=null){
    if(sd<1) return {label:'반복성 높음',color:P.good,detail:'편차 ±'+Math.round(sd*10)/10+(u||'')};
    if(sd<2.5) return {label:'반복성 보통',color:P.warn,detail:'편차 ±'+Math.round(sd*10)/10+(u||'')};
    return {label:'반복성 낮음',color:P.bad,detail:'편차 ±'+Math.round(sd*10)/10+(u||'')};
  }
  if(rng!=null){
    if(rng<2) return {label:'반복성 높음',color:P.good,detail:'구간 '+Math.round(rng*10)/10};
    if(rng<5) return {label:'반복성 보통',color:P.warn,detail:'구간 '+Math.round(rng*10)/10};
    return {label:'반복성 낮음',color:P.bad,detail:'구간 '+Math.round(rng*10)/10};
  }
  return null;
}
