function collectStageDriveMetrics(){
  var cfg=STAGE_DRIVE_VIS, out=[], seen={}, coach=cfg.coachPriorityKeys||[];
  (cfg.groups||[]).forEach(function(g){
    (g.keys||[]).forEach(function(key){
      if(seen[key]) return;
      if(key==='strideType'){
        var syn=_driveStrideTypeRow();
        if(syn){ seen[key]=1; var reg=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(key):null;
          out.push({key:key,labelKo:syn.label,value:syn.value,unit:'',group:g.id,isTypeContext:true,priority:_varVisPriorityRank(syn,key,coach),coachMeaning:(reg&&reg.coachMeaning)||'',warning:'',_row:{label:syn.label,val:syn.value,score:null,status:'neutral',key:key,neutral:true}});
        }
        return;
      }
      var hit=_phaseMetricByKey(key);
      if(!hit||!hit.metric) return;
      var m=hit.metric;
      if(m.value==null||!isFinite(m.value)){ if(!m.warn) return; }
      seen[key]=1;
      var reg=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(key):null;
      out.push({key:key,labelKo:m.label,value:m.value,unit:m.unit||'',group:g.id,priority:_varVisPriorityRank(m,key,coach),coachMeaning:(reg&&reg.coachMeaning)||(m.note||'').split('.')[0]||'',warning:m.warn||'',_row:_driveMetricToDetailRow(hit)});
    });
  });
  try{
    var ph=(typeof DATA!=='undefined'&&DATA.phases)?DATA.phases:null;
    if(ph&&ph.strideRisk&&ph.strideRisk.length){
      ph.strideRisk.forEach(function(r,i){
        out.push({key:'strideRisk_'+i,labelKo:r.label||'위험 신호',value:null,unit:'',group:'risk',priority:3+i,coachMeaning:r.detail||'',warning:r.label||'',_row:null,isRisk:true,isCriticalRisk:true});
      });
    }
  }catch(e){}
  return out;
}
function _collectStageVisMetricsForCfg(cfg){
  if(cfg===STAGE_DRIVE_VIS&&typeof collectStageDriveMetrics==='function') return collectStageDriveMetrics();
  if(cfg===STAGE_BLOCKING_VIS&&typeof collectStageBlockingMetrics==='function') return collectStageBlockingMetrics();
  if(cfg===STAGE_WINDUP_VIS&&typeof collectStageWindupMetrics==='function') return collectStageWindupMetrics();
  if(cfg===STAGE_TRUNK_VIS&&typeof collectStageTrunkMetrics==='function') return collectStageTrunkMetrics();
  if(cfg===STAGE_ARM_VIS&&typeof collectStageArmMetrics==='function') return collectStageArmMetrics();
  if(cfg===LEAD_KNEE_TRANSFER&&typeof collectLeadKneeTransferMetrics==='function') return collectLeadKneeTransferMetrics(typeof DATA!=='undefined'?DATA:null);
  if(cfg===STAGE_COMMAND_VIS&&typeof collectStageCommandMetrics==='function') return collectStageCommandMetrics();
  return [];
}
