      if(seen[k]) return;
      var spec=VAR_VIS.get(k);
      if(!spec||spec.phase!==cfg.registryPhase) return;
      var hit=_phaseMetricByKey(k);
      if(!hit) return;
      var card=_metricRowFromHit(hit);
      if(!card) return;
      seen[k]=1;
      card.displayPolicy=_cardDisplayPolicy(hit.metric,k,spec);
      card.priority=_varVisPriorityRank(hit.metric,k,coachKeys);
      card.group=card.group||('reg-'+spec.phase);
