        var role=COACH_FIELD_V3.roleForKey(key);
        if(role==='independent') return '<span class="core35-tier-badge field-feedback">핵심 문제</span>';
        if(role==='auxiliary_layer') return '<span class="core35-tier-badge aux-layer">보조 레이어</span>';
