function _coachProblemOneLine(key,m,spec,card){
  var preset=_coachFieldCopy(key,'problem');
  if(preset) return preset;
  var cp=_varCopyResolve(key,spec,m);
  if(cp.coachSummary) return _sanitizeCoachPanelText(cp.coachSummary);
  if(card&&card.coachMeaning) return _sanitizeCoachPanelText(card.coachMeaning);
  if(spec&&spec.easyExplanation) return _sanitizeCoachPanelText(spec.easyExplanation);
  return _sanitizeCoachPanelText((spec&&spec.labelKo)||_core35CoachLabel(key)||'오늘 이 동작에서 확인할 포인트');
}
function _coachPlayerTalkLine(key,spec,m){
  var preset=_coachFieldCopy(key,'player');
  if(preset) return preset;
  var cp=_varCopyResolve(key,spec,m);
  if(cp.playerSentence) return _sanitizeCoachPanelText(cp.playerSentence);
  if(cp.coachSummary) return _sanitizeCoachPanelText(cp.coachSummary);
  if(spec&&spec.coachMeaning) return _sanitizeCoachPanelText(spec.coachMeaning);
  return '';
}
