function _reportAuxCollapse(collapsed){
  var panel=document.getElementById('var-stick-viz-panel'), btn=document.getElementById('var-stick-aux-toggle');
  if(!panel) return;
  if(collapsed){
    panel.classList.remove('aux-expanded');
    panel.classList.add('aux-collapsed');
    if(btn) btn.setAttribute('aria-expanded','false');
    try{ _coachAuxGraphHintUpdate(_vsSelectedKey||window.selectedVariableKey||null); }catch(e){}
  }else{
    panel.classList.add('aux-expanded');
    panel.classList.remove('aux-collapsed');
    if(btn) btn.setAttribute('aria-expanded','true');
    try{ _coachAuxGraphHintUpdate(_vsSelectedKey||window.selectedVariableKey||null); }catch(e){}
    setTimeout(function(){
      try{
        var k=_vsSelectedKey||window.selectedVariableKey;
        if(k){ var sp=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(k):null; _paintVarStickVizChart(k); }
      }catch(e){}
    },60);
  }
  try{ document.body.classList.toggle('coach-aux-expanded',!collapsed&&(_isCoachReportMode()||_isResearchExpertPage(_currentReportPageId))); }catch(e){}
  if(window._playbackActive) return;
  try{
    if(typeof stick3D!=='undefined'&&stick3D.resize) stick3D.resize();
    if(typeof stick3D!=='undefined'&&stick3D.coachAutoFit){
      var k=_vsSelectedKey||window.selectedVariableKey||null;
      var tr=(typeof _fvSelectedTrial==='function')?_fvSelectedTrial():null;
      var fi=typeof _currentFrame!=='undefined'?_currentFrame:0;
      var fr=tr&&tr.frames?tr.frames[fi]:null;
      stick3D.coachAutoFit(k,null,fr);
    }
  }catch(e){}
}
