  var nextM=_coachFieldCopy(key,'next')||(spec&&spec.nextMeasure&&!/^[a-z]/.test(String(spec.nextMeasure))?spec.nextMeasure:'')||('다음 측정 · '+_coachFieldLabel(key));
  side.innerHTML=_coachCuePanelHtml(problem, playerCue, drill, nextM, _coachRefBadgesHtml(FS));
