function _renderResearchExpertSide(key){
  var side=document.getElementById('analyst-doc-side'); if(!side) return;
  side.classList.add('research-expert-panel');
  var rdxActive=_isResearchStageExpertPage(_currentReportPageId)&&typeof RESEARCH_STAGE_PANEL_V2!=='undefined'&&RESEARCH_STAGE_PANEL_V2.panelHtml;
  if(rdxActive){
    side.hidden=false;
    if(!key){
      /* [2026-06-10 완성] 단계 진입 디폴트 = 9섹션 단계 오버뷰(req-20260608-researcher-5stage-expert).
         변인 칩·행 클릭 → 변인 상세(rdx v2) · navbar [단계 개요] → 본 오버뷰 복귀. display-only. */
      var rsxOv=null; try{ rsxOv=_renderResearchStageExpertOverview(_currentReportPageId); }catch(e){}
      if(rsxOv){
        side.innerHTML=rsxOv;
        try{ _syncResearchStageNav(_currentReportPageId, '__overview__'); }catch(e){}
        return;
      }
      var pack=_researchStageCollectCards(_currentReportPageId);
      var cards=(pack&&pack.cards)||[];
      for(var i=0;i<cards.length;i++){ if(cards[i]&&cards[i].key&&!cards[i].isRisk){ key=cards[i].key; break; } }
    }
    side.innerHTML=RESEARCH_STAGE_PANEL_V2.panelHtml(key);
    try{ _syncResearchStageNav(_currentReportPageId, key); }catch(e){}
    return;
  }
  if(!key&&_isResearchStageExpertPage(_currentReportPageId)){
    side.hidden=false;
    var rsx=_renderResearchStageExpertOverview(_currentReportPageId);
    if(rsx){ side.innerHTML=rsx; return; }
  }
  if(!key){
    side.innerHTML='<div class="research-expert-title">전문 해석 패널</div><div class="analyst-doc-empty sub2">변인을 선택하면 정의·산출·norm·해석·가설·관련 변인이 표시됩니다.</div>';
    side.hidden=false;
    return;
  }
  var Wfp=(typeof WINDUP_V1!=='undefined')?WINDUP_V1:null;
  var Dfp=(typeof DRIVE_V1!=='undefined')?DRIVE_V1:null;
  var Bfp=(typeof BLOCKING_V1!=='undefined')?BLOCKING_V1:null;
  if(Wfp&&Wfp.isFpWindupVariable&&Wfp.isFpWindupVariable(key)&&!Wfp.shouldShowFpVariable(key,_fvSelectedTrial(),DATA)){
    side.hidden=false;
    side.innerHTML='<div class="research-expert-title">'+_ezLabel(key)+'</div>'
      +'<div class="ad-sec" style="color:var(--amber)"><b>FP 접지 QC</b><br>'+_ezLabel(Wfp.fpQcMessage())+'</div>'
      +'<div class="ad-sec sub2">값 표시·임퓨테이션 없음 · 낮은 Fz를 힘 부족으로 해석하지 않음</div>';
    return;
  }
  if(Dfp&&Dfp.isFpDriveVariable&&Dfp.isFpDriveVariable(key)&&!Dfp.shouldShowFpVariable(key,_fvSelectedTrial(),DATA)){
    side.hidden=false;
    side.innerHTML='<div class="research-expert-title">'+_ezLabel(key)+'</div>'
      +'<div class="ad-sec" style="color:var(--amber)"><b>FP 접지 QC</b><br>'+_ezLabel(Dfp.fpQcMessage())+'</div>'
      +'<div class="ad-sec sub2">드라이브 FP 탐색 · 선수·코치 미노출 · QC 미통과 trial</div>';
    return;
  }
  if(Bfp&&Bfp.isFpBlockingVariable&&Bfp.isFpBlockingVariable(key)&&!Bfp.shouldShowFpVariable(key,_fvSelectedTrial(),DATA)){
    side.hidden=false;
    side.innerHTML='<div class="research-expert-title">'+_ezLabel(key)+'</div>'
      +'<div class="ad-sec" style="color:var(--amber)"><b>FP2 접지 QC</b><br>'+_ezLabel(Bfp.fpQcMessage())+'</div>'
      +'<div class="ad-sec sub2">블로킹 FP2 탐색 · 선수·코치 미노출 · QC 미통과 trial · 낮은 Fz=약한 블로킹 해석 금지</div>';
    return;
  }
  var Av=(typeof ARM_RELEASE_V1!=='undefined')?ARM_RELEASE_V1:null;
  if(Av&&_currentReportPageId==='ed-armball'&&Av.isLowConfidenceKey&&Av.isLowConfidenceKey(key)){
    side.hidden=false;
    side.innerHTML='<div class="research-expert-title">'+_ezLabel(key)+'</div>'
      +'<div class="ad-sec" style="color:var(--amber)"><b>측정 신뢰 · low</b><br>선수·코치 독립판정 금지 · 공 추적/마커 재검증 후 재평가</div>'
      +'<div class="ad-sec sub2">CV=정밀도≠정확도 · MER·몸통 전달·부하와 교차 확인</div>';
    return;
  }
  if(Av&&_currentReportPageId==='ed-armball'&&Av.isOutputKey&&Av.isOutputKey(key)){
    var hitOut=_varDetailMetricHit(key), mOut=hitOut?hitOut.metric:null;
    side.hidden=false;
    side.innerHTML='<div class="research-expert-title">'+_ezLabel(key)+'</div>'
      +'<div class="ad-sec"><b>출력 결과 · 독립 판정 아님</b><br>'+_ezLabel(Av.coachOutputPanelHtml?Av.coachOutputPanelHtml(key,mOut):Av.COACH_OUTPUT_INTRO)+'</div>'
      +'<div class="ad-sec sub2">rate cue·속도 목표 교정 금지 · MER·타이밍·부하 레이어 우선</div>';
    return;
  }
  if(Av&&_currentReportPageId==='ed-armball'&&Av.isLoadLayerKey&&Av.isLoadLayerKey(key)){
    side.hidden=false;
    side.innerHTML='<div class="research-expert-title">'+_ezLabel(key)+'</div>'
      +'<div class="ad-sec"><b>부하 레이어</b><br>독립 성능 판정 아님 · injury/부하 탭과 MER 과다 신호 교차 확인</div>'
      +'<div class="ad-sec sub2"><button type="button" class="btn-xs" onclick="setPage(\'injury\')">부하 단계 →</button></div>';
    return;
  }

  side.hidden=false;
  var hit=_varDetailMetricHit(key), m=hit?hit.metric:null, card=_vsResolveCard(key);
  var spec=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(key):null;
  var cp=_varCopyResolve(key,spec,m);
  var label=(spec&&spec.labelKo)||(m&&m.label)||(card&&card.labelKo)||key;
  var st=_varDetailStatusLabel(m,key,spec);
  var valTxt=(m&&m.value!=null&&isFinite(m.value))?(m.value+(m.unit||'')):((card&&card.value!=null)?(card.value+(card.unit||'')):'—');
  var dirHint=(m&&m.dir==='range')?'적정 범위 변인 · p75 초과=무조건 우수 아님':((m&&m.dir===-1)?'낮을수록 유리':'높을수록 유리(방향 자동 반영)');
  side.innerHTML='<div class="research-expert-title">'+_ezLabel(label)+'</div>'
    +'<div class="ad-stat" style="color:'+st.color+'">'+valTxt+' · '+st.label+'</div>'
    +'<div class="ad-sec"><b>정의</b><br>'+_ezLabel(cp.analystDefinition||'—')+'</div>'
    +'<div class="ad-sec"><b>산출 방식</b><br>'+_ezLabel(cp.analystCalculation||'—')+'</div>'
    +_researchExpertEventWindowHtml(key,spec)
    +'<div class="ad-sec"><b>평가 정책</b><br>'+_ezLabel(cp.evaluationPolicy||'엘리트 3밴드')+' · '+_ezLabel(dirHint)+'</div>'
    +_researchExpertNormsLine(key,m)
    +'<div class="ad-sec"><b>현재 선수 해석</b><br>'+_ezLabel(cp.analystInterpretation||cp.coachSummary||'—')+'</div>'
    +'<div class="ad-sec"><b>원인 가설</b><br>'+_ezLabel(_researchExpertHypothesisLine(key,cp,spec,m,st))+'</div>'
    +_researchExpertRelatedHtml(key,spec)
    +'<div class="ad-sec"><b>보상 전략</b><br>'+_ezLabel(_researchExpertCompensationLine(key,cp,spec))+'</div>'
    +_researchExpertFollowUps(key)
    +'<div class="ad-sec"><b>선수·코치 전달용 요약</b><br>'+_ezLabel(_researchExpertCoachTransferLine(cp,spec))+'</div>';
}
function _renderAnalystDocSide(key){
  var side=document.getElementById('analyst-doc-side'); if(!side) return;
  if(_currentReportPageId==='hpa'){
    _renderResearchFitnessExpertSide();
    return;
  }
  if(_currentReportPageId==='injury'){
    _renderResearchLoadExpertSide();
    return;
  }
  if(_isResearchExpertPage(_currentReportPageId)){
    _renderResearchExpertSide(key);
    return;
  }
  if(!_isAnalystReportMode()||!key){
    side.innerHTML='<div class="analyst-doc-empty sub2">변인을 선택하면 정의·산출·해석이 표시됩니다.</div>';
    side.hidden=true;
    return;
  }
  side.hidden=false;
  var hit=_varDetailMetricHit(key), m=hit?hit.metric:null, card=_vsResolveCard(key);
  var spec=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(key):null;
  var cp=_varCopyResolve(key,spec,m);
  var label=(spec&&spec.labelKo)||(m&&m.label)||key;
  var st=_varDetailStatusLabel(m,key,spec);
  var stickVt=spec?_resolveStickVisualType(key,spec,m):'bandGauge';
  var valTxt=(m&&m.value!=null&&isFinite(m.value))?(m.value+(m.unit||'')):'—';
  var audit=_isDebugAuditMode()?('<div class="ad-sec report-audit-only"><b>audit</b> · key='+key+' · source='+(hit&&hit.sourceLabel||'phases')+'</div>'):'';
  side.innerHTML='<div class="ad-var">'+_ezLabel(label)+'</div>'
    +'<div class="ad-stat" style="color:'+st.color+'">'+valTxt+' · '+st.label+'</div>'
    +'<div class="ad-sec"><b>정의</b><br>'+_ezLabel(cp.analystDefinition||'—')+'</div>'
    +'<div class="ad-sec"><b>산출</b><br>'+_ezLabel(cp.analystCalculation||'—')+'</div>'
    +'<div class="ad-sec"><b>해석</b><br>'+_ezLabel(cp.analystInterpretation||'—')+'</div>'
    +'<div class="ad-sec"><b>평가</b><br>'+_ezLabel(cp.evaluationPolicy||'엘리트 3밴드')+'</div>'
    +'<div class="ad-viz">시각화 · '+stickVt+' · 좌측 preview + 보조 패널</div>'
    +(_coachCueDrillLine(key)?('<div class="ad-sec"><b>드릴</b><br>'+_ezLabel(_coachCueDrillLine(key))+'</div>'):'')
    +(cp.researchNote?('<div class="ad-sec report-audit-only"><b>research</b><br>'+_ezLabel(cp.researchNote)+'</div>'):'')
    +audit;
}
function _renderReportSidePanels(key){
  if(_isAnalystMechSummaryFullpage()){
    try{
      var cue0=document.getElementById('coach-cue-side'); if(cue0) cue0.innerHTML='';
      var side0=document.getElementById('analyst-doc-side'); if(side0){ side0.innerHTML=''; side0.hidden=true; }
    }catch(e){}
    return;
  }
  if(_isCoachTodaySummaryPage()){
    try{
      var cue=document.getElementById('coach-cue-side');
      if(cue) cue.innerHTML='';
    }catch(e){}
    _renderAnalystDocSide(key);
    return;
  }
  _renderCoachCueSide(key);
  _renderAnalystDocSide(key);
}
function setDualReportMode(mode){
  _dualReportMode=(mode==='analyst')?'analyst':'coach';
  try{ localStorage.setItem(_dualReportStorageKey(),_dualReportMode); }catch(e){}
  document.body.classList.toggle('report-mode-coach',_isCoachReportMode());
  document.body.classList.toggle('report-mode-analyst',_isAnalystReportMode());
  document.querySelectorAll('.dual-report-mode-toggle .drm-btn').forEach(function(btn){
    btn.classList.toggle('on',btn.dataset.drm===_dualReportMode);
  });
  if(_isAnalystReportMode()) _reportAuxCollapse(false);
  else if(_vsSelectedKey||window.selectedVariableKey) _reportAuxCollapse(false);
  else _reportAuxCollapse(true);
  try{ _applyNavTabVisibility(_reportMode); }catch(e){}
  try{
    if(_isCoachReportMode()){
      if(_navPageOk('feedback-view')) setPage('feedback-view');
    }else{
      var _act=document.querySelector('.tab.active');
      if(_act&&_act.dataset.page==='theory'){
        setPage(_navPageOk('psummary')?'psummary':(_navPageOk('feedback-view')?'feedback-view':'psummary'));
      }
    }
  }catch(e){}
  try{ _populateCoachOvDropdown(); }catch(e){}
  _renderReportSidePanels(_vsSelectedKey||window.selectedVariableKey||null);
  try{ if(typeof renderFeedbackView==='function') renderFeedbackView(); }catch(e){}
  try { if(typeof stick3D!=='undefined'&&stick3D.setRenderMode) stick3D.setRenderMode('stick'); }catch(e){}
  try{ if(typeof stick3D!=='undefined'&&stick3D.resize) stick3D.resize(); }catch(e){}
  try{
    if(typeof stick3D!=='undefined'&&stick3D.resetViewToFit) stick3D.resetViewToFit({ force: true, allowUserLock: true });
    else if(typeof stick3D!=='undefined'&&stick3D.coachAutoFit) stick3D.coachAutoFit(null,null,null);
  }catch(e){}
  try{ _fitWidthZoom(); }catch(e){}
  try{ if(typeof _syncReportChrome==='function') _syncReportChrome(); }catch(e){}
  try{ _vsScheduleTsRedraw(); }catch(e){}
  try{ _refreshGlobalTransport(); }catch(e){}
  try{ _initPdfSaveMenu(); _closePdfSaveMenu(); }catch(e){}
  try{ _syncResearchSplitExpertLayout(_currentReportPageId||(document.querySelector('.tab.active')&&document.querySelector('.tab.active').dataset.page)); }catch(e){}
}
function _coachOvVarDisplayLabel(key){
  if(!key) return '— 변인 선택 —';
  if(typeof CORE35_VAR_GROUPS!=='undefined'&&CORE35_VAR_GROUPS.coachLabel){
    var gl=CORE35_VAR_GROUPS.coachLabel(key);
    if(gl) return gl;
  }
  if(typeof TOP20_VAR_GROUPS!=='undefined'&&TOP20_VAR_GROUPS.coachLabel){
    var gl2=TOP20_VAR_GROUPS.coachLabel(key);
    if(gl2) return gl2;
  }
  var sp=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(key):null;
  return (sp&&sp.labelKo)||key;
}
function _setCoachOvVarValue(key){
  var hid=document.getElementById('coach-ov-var');
  var btn=document.getElementById('coach-ov-var-btn');
  var menu=document.getElementById('coach-ov-var-menu');
  if(hid) hid.value=key||'';
  if(btn) btn.textContent=_coachOvVarDisplayLabel(key);
  if(menu) menu.querySelectorAll('.coach-ov-var-item').forEach(function(it){
    it.classList.toggle('on',it.dataset.varKey===key);
  });
}
function _closeCoachOvVarMenu(){
  var menu=document.getElementById('coach-ov-var-menu');
  var btn=document.getElementById('coach-ov-var-btn');
  if(menu) menu.hidden=true;
  if(btn) btn.setAttribute('aria-expanded','false');
}
function _openCoachOvVarMenu(){
  var menu=document.getElementById('coach-ov-var-menu');
  var btn=document.getElementById('coach-ov-var-btn');
  if(!menu) return;
  menu.hidden=false;
  if(btn) btn.setAttribute('aria-expanded','true');
}
function _populateCoachOvGroupedMenu(){
  var menu=document.getElementById('coach-ov-var-menu');
  var hid=document.getElementById('coach-ov-var');
  if(!menu||typeof SKELETON_PLATFORM==='undefined') return;
  var cur=hid?hid.value:'';
  menu.innerHTML='';
  menu.classList.remove('coach-ov-var-flat');
  function addItem(key,label){
    if(_isCoachReportMode()&&!_isCoachFieldMenuKey(key)) return;
    var b=document.createElement('button');
    b.type='button'; b.className='coach-ov-var-item'; b.dataset.varKey=key; b.textContent=label||_coachFieldLabel(key);
    if(key===cur) b.classList.add('on');
    b.addEventListener('click',function(){
      _setCoachOvVarValue(key);
      _closeCoachOvVarMenu();
      if(typeof selectVariableForCoach==='function') selectVariableForCoach(key);
    });
    menu.appendChild(b);
  }
  if(_isCoachReportMode()&&typeof COACH_FIELD_V3!=='undefined'&&COACH_FIELD_V3.menuGroups){
    COACH_FIELD_V3.menuGroups().forEach(function(grp){
      var items=(grp.keys||[]).filter(function(k){ return _isCoachFieldMenuKey(k); });
      if(!items.length) return;
      var head=document.createElement('div');
      head.className='coach-ov-var-grp'; head.textContent=grp.label;
      menu.appendChild(head);
      items.forEach(function(k){ addItem(k,_coachFieldLabel(k)); });
    });
  }else if(_isCoachReportMode()&&typeof CORE35_VAR_GROUPS!=='undefined'&&CORE35_VAR_GROUPS.groups){
    CORE35_VAR_GROUPS.groups.forEach(function(grp){
      var items=(grp.items||[]).filter(function(it){ return _isCoachFieldMenuKey(it.key); });
      if(!items.length) return;
      var head=document.createElement('div');
      head.className='coach-ov-var-grp'; head.textContent=grp.label;
      menu.appendChild(head);
      items.forEach(function(it){ addItem(it.key,it.label); });
    });
  }else{
    menu.classList.add('coach-ov-var-flat');
    var map=SKELETON_PLATFORM.map||{};
    Object.keys(map).sort().forEach(function(k){
      var sp=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(k):null;
      addItem(k,(sp&&sp.labelKo)||k);
    });
  }
  _setCoachOvVarValue(cur||'');
}
function _wireCoachOvGroupedSelector(){
  var btn=document.getElementById('coach-ov-var-btn');
  var wrap=document.getElementById('coach-ov-var-wrap');
  if(btn&&!btn._covGrpWired){
    btn._covGrpWired=true;
    btn.addEventListener('click',function(e){
      e.stopPropagation();
      var menu=document.getElementById('coach-ov-var-menu');
      if(menu&&menu.hidden) _openCoachOvVarMenu(); else _closeCoachOvVarMenu();
    });
  }
  if(!document._coachOvMenuCloseWired){
    document._coachOvMenuCloseWired=true;
    document.addEventListener('click',function(e){
      if(wrap&&!wrap.contains(e.target)) _closeCoachOvVarMenu();
    });
    document.addEventListener('keydown',function(e){
      if(e.key==='Escape') _closeCoachOvVarMenu();
    });
  }
}
function _populateCoachOvDropdown(){
  _populateCoachOvGroupedMenu();
  _wireCoachOvGroupedSelector();
}
function _initDualReportMode(){
  try{
    var stored=localStorage.getItem(_dualReportStorageKey());
    if(stored==='analyst') _dualReportMode='analyst';
    else if(stored==='coach') _dualReportMode='coach';
    else{
      var legacy=localStorage.getItem('bm_coach_present_mode');
      _dualReportMode=(legacy==='1')?'coach':'coach';
    }
  }catch(e){ _dualReportMode='coach'; }
  try{ _coachOvAuto=localStorage.getItem(_coachOvAutoStorageKey())!=='0'; }catch(e){ _coachOvAuto=true; }
  document.body.classList.toggle('report-mode-coach',_isCoachReportMode());
  document.body.classList.toggle('report-mode-analyst',_isAnalystReportMode());
  document.body.setAttribute('data-audit-ui',_isDebugAuditMode()?'1':'0');
  document.querySelectorAll('.dual-report-mode-toggle .drm-btn').forEach(function(btn){
    btn.classList.toggle('on',btn.dataset.drm===_dualReportMode);
    btn.addEventListener('click',function(){ setDualReportMode(btn.dataset.drm); });
  });
  var auxBtn=document.getElementById('var-stick-aux-toggle');
  if(auxBtn) auxBtn.addEventListener('click',function(e){
    e.preventDefault();
    var panel=document.getElementById('var-stick-viz-panel');
    _reportAuxCollapse(!(panel&&panel.classList.contains('aux-expanded')));
  });
  if(_isCoachReportMode()) _reportAuxCollapse(!!(_vsSelectedKey||window.selectedVariableKey));
  else _reportAuxCollapse(false);
  var ovAutoCb=document.getElementById('coach-ov-auto');
  if(ovAutoCb){
    ovAutoCb.checked=_coachOvAuto;
    ovAutoCb.addEventListener('change',function(){
      _coachOvAuto=ovAutoCb.checked;
      try{ localStorage.setItem(_coachOvAutoStorageKey(),_coachOvAuto?'1':'0'); }catch(e){}
      if(_coachOvAuto&&_vsSelectedKey){
        var sp=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(_vsSelectedKey):null;
        if(typeof stick3D!=='undefined'&&stick3D.applyCoachOverlayProfile) stick3D.applyCoachOverlayProfile(_vsSelectedKey,sp,_fvSelectedTrial());
      }
    });
  }
  _populateCoachOvDropdown();
  _wireCoachOvGroupedSelector();
  _renderReportSidePanels(_vsSelectedKey||window.selectedVariableKey||null);
  _initCoachOvQuick();
  try{ _applyNavTabVisibility(_reportMode); }catch(e){}
  try{ _syncResearchSplitExpertLayout(document.querySelector('.tab.active')&&document.querySelector('.tab.active').dataset.page||'feedback-view'); }catch(e){}
}
function _initCoachOvQuick(){
  document.querySelectorAll('.cov-btn').forEach(function(btn){
    if(btn._covWired) return;
    btn._covWired=true;
    var key=btn.dataset.cov;
    btn.addEventListener('click',function(){
      var on=!btn.classList.contains('on');
      btn.classList.toggle('on',on);
      try{ if(typeof stick3D!=='undefined'&&stick3D.setCoachManualOverlay) stick3D.setCoachManualOverlay(key,on); }catch(e){}
    });
    if(btn.classList.contains('on')&&typeof stick3D!=='undefined'&&stick3D.setCoachManualOverlay){
      stick3D.setCoachManualOverlay(key,true);
    }
  });
}
window.setDualReportMode=setDualReportMode;
window.setCoachPresentMode=function(on){ setDualReportMode(on?'coach':'analyst'); };
window._initDualReportMode=_initDualReportMode;
window._initCoachPresentationMode=_initDualReportMode;

function _vsApplyVarHighlight(key,spec){
  try{
    var trial=_fvSelectedTrial(), win=_vsResolveEventWindow(trial,spec);
    if(_isCoachReportMode()){
      var cvis=(typeof COACH_VIS_PRESETS!=='undefined')?COACH_VIS_PRESETS[key]:null;
      if(cvis&&cvis.overlay&&typeof stick3D!=='undefined'&&stick3D.applyCoachVisOverlayExclusive){
        stick3D.applyCoachVisOverlayExclusive(cvis.overlay,key,trial,cvis.view||null);
        if(cvis.view&&stick3D.setView) stick3D.setView(cvis.view);
      }else if(typeof stick3D!=='undefined'&&stick3D.applyCoachOverlayProfile&&_coachOvAutoEnabled()){
        stick3D.applyCoachOverlayProfile(key,spec,trial);
      }
      window._fvHighlightPhase=null;
      try{ if(typeof stick3D!=='undefined'&&stick3D.clearHighlightRange) stick3D.clearHighlightRange(); }catch(e){}
      _fvSyncStickBanner(false);
      return;
    }
    if(!win){ _fvSyncStickBanner(false); return; }
    window._fvHighlightPhase=(spec&&spec.phase)||null;
    if(typeof stick3D!=='undefined'&&stick3D.setHighlightRange) stick3D.setHighlightRange(win.i0,win.i1);
    var winLbl=spec?_vsEventWindowLabel(spec):'';
    var banLbl=(spec&&spec.labelKo)||key;
    if(winLbl) banLbl=banLbl+' · '+winLbl;
    _fvSyncStickBanner(true,banLbl);
    var mid=Math.round((win.i0+win.i1)/2);
    try{ if(typeof playback!=='undefined'&&playback.setFrame) playback.setFrame(mid); }catch(e){ _currentFrame=mid; }
  }catch(e){}
}
function _paintVarStickAuxCharts(key,spec){
  var hit=_varDetailMetricHit(key), m=hit?hit.metric:null;
  var stickVt=_resolveStickVisualType(key,spec,m);
  _paintVarStickVizChart(key);
  if(_isCoachReportMode()) return;
  if(_skipAuxMiniStick(key,stickVt)) return;
  _paintVarStickTopViewSeparation(key);
  _paintVarStickTorqueCircle(key);
  if(stickVt==='kneeCollapseGauge'||key==='kneeCollapse') _paintVarStickKneeCollapse(key);
  if(stickVt==='eventSnapshot') _paintVarStickEventSnapshot(key,spec);
}
function _vsCurrentFrameValueText(key,m,spec){
  var fast=(typeof _fastTrial==='function')?_fastTrial():null;
  var cf=(typeof _currentFrame!=='undefined'&&_currentFrame!=null)?Math.round(_currentFrame):null;
  var unit=(m&&m.unit)||(spec&&spec.unit)||'';
  var v=(fast&&cf!=null)?_varDetailEvtVal(fast,key,cf):null;
  if(v==null&&m&&m.value!=null&&isFinite(m.value)) v=m.value;
  var valTxt=(v!=null&&isFinite(v))?(v+unit):'—';
  var out=!_vsFrameInPlotWindow(key,spec);
  return '현재 프레임 값 · '+valTxt+(cf!=null?(' (frame '+cf+')'):'')+(out?' · 표시 구간 밖':'');
}
function _vsResolveCard(key){
  try{
    var hit=_varDetailMetricHit(key);
    if(!hit||!hit.metric) return null;
    var m=hit.metric, spec=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(key):null;
    return {key:key,labelKo:(spec&&spec.labelKo)||m.label||key,value:m.value,unit:m.unit||'',priority:m.priority};
  }catch(e){ return null; }
}
function _coachVisualGrade(key,spec){
  if(spec&&spec.visualQualityGrade) return spec.visualQualityGrade;
  if(spec&&spec.displayPolicy==='research_only') return 'D';
  return 'B';
}
function _coachVisualUseFallback(key,spec){
  if(typeof _isResearchView==='function'&&_isResearchView()) return false;
  var g=_coachVisualGrade(key,spec);
  return g==='C'||g==='D';
}
function _coachVisualFallbackHtml(key,m,spec,st,valTxt){
  var v=valTxt||(m&&m.value!=null&&isFinite(m.value)?(m.value+(m.unit||spec.unit||'')):'—');
  return '<div class="coach-visual-fallback" style="padding:12px 14px;background:var(--bg2);border:1px solid var(--line);border-radius:8px;margin-top:8px">'
    +'<div style="font-size:12px;font-weight:700;color:var(--fg2);line-height:1.55">이 변인은 현재 요약 수치로만 표시됩니다. 자세한 해석은 오른쪽 설명을 참고하세요.</div>'
    +'<div style="margin-top:10px;font-size:22px;font-weight:800;color:'+st.color+'">'+v+' · '+st.label+'</div></div>';
}
function _varStickVizPanelHtml(key,card,stageKey){
  var hit=_varDetailMetricHit(key), m=hit?hit.metric:null;
  var spec=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(key):null;
  var label=(spec&&spec.labelKo)||(card&&card.labelKo)||(m&&m.label)||key;
  var st=_varDetailStatusLabel(m,key,spec);
  var valTxt=(card&&card.value!=null&&card.value!=='')?(card.value+(card.unit||'')):(m&&m.value!=null&&isFinite(m.value)?(m.value+(m.unit||'')):'—');
  if((_VAR_DETAIL_TYPE_KEYS[key]||_STICK_TYPE_DIAGRAM_KEYS[key])&&m&&m.value!=null&&key!=='leadFootAngleFC') valTxt=String(m.value);
  if(key==='leadFootAngleFC'&&m&&m.value!=null&&isFinite(m.value)) valTxt=_strideFootCoachDisplay(m.value,_playerHandedness());
  if(_isCoachReportMode()&&_coachVisualUseFallback(key,spec)){
    _vdP1Log(key,'coach_fallback',stageKey,true);
    return '<div class="var-stick-viz-head">'
      +'<div style="font-size:13px;font-weight:800">'+_ezLabel(label)+'</div>'
      +'<div style="margin-top:4px;font-size:14px;font-weight:800;color:'+st.color+'">'+st.label+'</div></div>';
  }
  if(_coachVisualUseFallback(key,spec)){
    _vdP1Log(key,'coach_fallback',stageKey,true);
    return '<div class="var-stick-viz-head">'
      +'<div style="font-size:13px;font-weight:800">'+_ezLabel(label)+'</div>'
      +'<div style="margin-top:4px;font-size:14px;font-weight:800;color:'+st.color+'">'+valTxt+' · '+st.label+'</div></div>'
      +_coachVisualFallbackHtml(key,m,spec,st,valTxt);
  }
  var stickVt=_resolveStickVisualType(key,spec,m);
  var forcedVt=_coachForcedStickVt(key);
  if (forcedVt) stickVt=forcedVt;
  var isTs=(stickVt==='eventTimeSeries'||stickVt==='impulseArea');
  var layoutCls=_helperGraphLayoutClass(stickVt,key);
  var bodyHtml=_stickVizBodyHtml(key,m,spec,stickVt);
  var evtHtml=(_isCoachReportMode()||!_stickHasPerEventValues(key,stickVt))?'':_varDetailEvtTableHtml(key,m,spec,{inline:true,stickVt:stickVt});
  var syncStrip=_isCoachReportMode()?'':_vsStickSyncStripHtml(key,spec,stickVt);
  _vdP1Log(key,stickVt,stageKey,false);
  var headStat=_isCoachReportMode()?st.label:(valTxt+' · '+st.label);
  var graphInner=(isTs?bodyHtml:('<div id="var-stick-viz-gauge" class="var-detail-viz">'+bodyHtml+'</div>'))
    +(isTs&&!_isCoachReportMode()?('<div id="var-stick-viz-frame" class="sub2" style="margin-top:6px;font-weight:600;color:var(--fg1)">'+_vsCurrentFrameValueText(key,m,spec)+'</div>'):'')
    +evtHtml;
  return '<div class="var-stick-viz-head">'
    +'<div style="font-size:13px;font-weight:800">'+_ezLabel(label)+'</div>'
    +'<div style="margin-top:4px;font-size:14px;font-weight:800;color:'+st.color+'">'+headStat+'</div></div>'
    +syncStrip
    +'<div class="coach-helper-graph-body '+layoutCls+'" data-helper-layout="'+_helperGraphLayoutKind(stickVt,key)+'" data-stick-vt="'+stickVt+'">'+graphInner+'</div>';
}
function _paintVarStickVizChart(key){
  var spec=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(key):null;
  var hit=_varDetailMetricHit(key), m=hit?hit.metric:null;
  var stickVt=_resolveStickVisualType(key,spec,m);
  if(stickVt!=='eventTimeSeries'&&stickVt!=='impulseArea') return;
  if(typeof plotWin!=='function'||typeof _FC_SER==='undefined'||!_FC_SER[key]) return;
  var cv=document.getElementById('var-stick-viz-ts'); if(!cv) return;
  var cfg=_FC_SER[key], ft=(typeof _fastTrial==='function')?_fastTrial():null;
  if(!ft) return;
  var tw=_vsResolveTsPlotWindow(key,spec,{impulseArea:stickVt==='impulseArea'});
  var core=_vsCoreEventWindow(spec);
  var fillImpulse=(stickVt==='impulseArea');
  try{
    plotWin('var-stick-viz-ts',{fast:ft,slow:(typeof _slowTrial==='function')?_slowTrial():null,
      startEv:tw.startEv,startOff:tw.startOff,endEv:tw.endEv,endOff:tw.endOff,
      lockWindow:tw.lockWindow,varTs:true,shadeCore:core,dimPadding:tw.lockWindow&&!tw.fullRange,peakAbs:true,
      left:{label:'',lines:[{compute:cfg.fn,color:cfg.c||'#5bb6e6',label:(spec&&spec.labelKo)||key,width:2.4}]},
      noGauge:true,fillToZero:fillImpulse,markPeaks:(stickVt==='eventTimeSeries')});
  }catch(e){}
}
function _redrawVarStickVizPanel(){
  if(!_vsSelectedKey) return;
  try{
    var specR=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(_vsSelectedKey):null;
    _paintVarStickAuxCharts(_vsSelectedKey,specR);
  }catch(e){}
  try{
    var el=document.getElementById('var-stick-viz-frame');
    if(el){
      var hit=_varDetailMetricHit(_vsSelectedKey), m=hit?hit.metric:null;
      var spec=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(_vsSelectedKey):null;
      el.textContent=_vsCurrentFrameValueText(_vsSelectedKey,m,spec);
    }
  }catch(e){}
}
var _vsTsResizeObs=null, _vsTsResizeT=null;
function _vsScheduleTsRedraw(){
  if(_vsTsResizeT) clearTimeout(_vsTsResizeT);
  _vsTsResizeT=setTimeout(function(){ _vsTsResizeT=null; try{ _redrawVarStickVizPanel(); }catch(e){} }, 80);
}
function _vsInitTsResize(){
  if(_vsTsResizeObs) return;
  try{
    var targets=[], panel=document.getElementById('var-stick-viz-panel'), lp=document.querySelector('.left-panel');
    if(panel) targets.push(panel);
    if(lp) targets.push(lp);
    if(typeof ResizeObserver!=='undefined'&&targets.length){
      _vsTsResizeObs=new ResizeObserver(function(){ _vsScheduleTsRedraw(); });
      targets.forEach(function(el){ _vsTsResizeObs.observe(el); });
    }
    window.addEventListener('resize', _vsScheduleTsRedraw);
  }catch(e){}
}
function _selectVarStickViz(key){
  try{
    var panel=document.getElementById('var-stick-viz-panel'), body=document.getElementById('var-stick-viz-body');
    if(!panel||!body){ if(typeof console!=='undefined'&&console.warn) console.warn('[selectVarStickViz] #var-stick-viz-panel missing'); return; }
    if(!key){
      _vsSelectedKey=null;
      window.selectedVariableKey=null;
      body.innerHTML='';
      panel.classList.remove('is-active');
      panel.removeAttribute('hidden');
      var ph0=panel.querySelector('.var-stick-viz-placeholder'); if(ph0) ph0.style.display='';
      try{ if(typeof stick3D!=='undefined'&&stick3D.applyCoachOverlayProfile) stick3D.applyCoachOverlayProfile(null); }catch(e){}
      return;
    }
    _vsSelectedKey=key;
    window.selectedVariableKey=key;
    var card=_vsResolveCard(key);
    var spec=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(key):null;
    var stageKey=(spec&&spec.phase)||'';
    if(typeof _isResearchView==='function'&&!_isResearchView()){
      window._vaiHighlightKey=null; window._vaiFocusKey=null; window._vaiRoundTrip=null;
      _vaiClearReturnBar(); _vaiClearPersistHighlight();
    }
    try{
      body.innerHTML=_varStickVizPanelHtml(key,card,stageKey);
    }catch(inner){
      var hitFb=_varDetailMetricHit(key), mFb=hitFb?hitFb.metric:null;
      var lbl=(spec&&spec.labelKo)||key;
      var stickVtFb=_resolveStickVisualType(key,spec,mFb);
      var bodyFb=_stickVizBodyHtml(key,mFb,spec,stickVtFb);
      var evtFb=_stickHasPerEventValues(key,stickVtFb)?_varDetailEvtTableHtml(key,mFb,spec,{inline:true,stickVt:stickVtFb}):'';
      body.innerHTML='<div class="var-stick-viz-head"><div style="font-size:13px;font-weight:800">'+_ezLabel(lbl)+'</div></div>'
        +'<div id="var-stick-viz-gauge" class="var-detail-viz">'+bodyFb+'</div>'+evtFb;
    }
    panel.removeAttribute('hidden');
    panel.classList.add('is-active');
    if(_isCoachReportMode()){
      panel.classList.add('coach-graph-only');
      var hitVt=_varDetailMetricHit(key), mVt=hitVt?hitVt.metric:null;
      var stickVtPanel=_resolveStickVisualType(key,spec,mVt);
      var forcedVtPanel=_coachForcedStickVt(key);
      if(forcedVtPanel) stickVtPanel=forcedVtPanel;
      panel.setAttribute('data-helper-layout',_helperGraphLayoutKind(stickVtPanel,key));
      panel.setAttribute('data-stick-vt',stickVtPanel||'');
    }else{
      panel.classList.remove('coach-graph-only');
      panel.removeAttribute('data-helper-layout');
      panel.removeAttribute('data-stick-vt');
    }
    if(_isCoachReportMode()||_isResearchExpertPage(_currentReportPageId)){
      try{ _coachAuxGraphHintUpdate(key); }catch(e){}
    }else{
      var ph=panel.querySelector('.var-stick-viz-placeholder'); if(ph) ph.style.display='none';
    }
    if(spec) _vsApplyVarHighlight(key,spec);
    try{ _vsInitTsResize(); }catch(e){}
    setTimeout(function(){ _paintVarStickAuxCharts(key,spec); },40);
    setTimeout(function(){ _paintVarStickAuxCharts(key,spec); },180);
    try{ _renderReportSidePanels(key); }catch(e){}
    try{
      _setCoachOvVarValue(key);
    }catch(e){}
    if(_isCoachReportMode()){
      _reportAuxCollapse(false);
      try{ _coachAuxGraphHintUpdate(key); }catch(e){}
    } else _reportAuxCollapse(false);
    try{ if(panel.scrollIntoView) panel.scrollIntoView({behavior:'smooth',block:'nearest'}); }catch(e){}
  }catch(e){ if(typeof console!=='undefined'&&console.warn) console.warn('[selectVarStickViz]',e); }
}
var _BM_VAR_SEL=null;
function _isMechanicsSummaryPage(){
  try{
    var cur=(document.querySelector('.tab.active')||{}).dataset;
    return !!(cur&&cur.page==='psummary'&&(document.getElementById('mdm-root')||document.getElementById('bm-root')));
  }catch(e){ return false; }
}
function _msVarInfo(key){
  try{ return (typeof _NEWVAR_INFO!=='undefined'&&_NEWVAR_INFO[key])?_NEWVAR_INFO[key]:null; }catch(e){ return null; }
}
function _msMeaningLine(key,cp,spec,m){
  if(cp.coachSummary) return cp.coachSummary;
  if(cp.playerSentence) return cp.playerSentence;
  if(spec&&spec.coachMeaning) return spec.coachMeaning;
  if(spec&&spec.easyExplanation) return spec.easyExplanation;
  var info=_msVarInfo(key);
  if(info&&info.def) return info.def;
  if(typeof _EZ_EXPL!=='undefined'&&_EZ_EXPL[key]) return _EZ_EXPL[key];
  if(m&&m.note){ var s=m.note.replace(/<[^>]+>/g,'').split('.')[0]; if(s) return s; }
  return '—';
}
function _msProblemLine(key,cp,spec,st,m){
  var weak=(st.label==='미흡'||st.label==='위험'||st.label==='주의'||st.label==='부족'||st.label==='높음');
  if(!weak) return '엘리트 범위 내 — 우선 교정 포인트 낮음';
  if(cp.coachObservation) return cp.coachObservation;
  if(spec&&spec.coachWarning) return spec.coachWarning;
  if(m&&m.warn) return m.warn;
  try{
    if(typeof coachingPrescription!=='undefined'&&coachingPrescription.getCause){
      var c=coachingPrescription.getCause(key);
      if(c&&c.problem) return c.problem;
      if(c&&c.caution) return c.caution;
    }
  }catch(e){}
  if(cp.caution) return cp.caution;
  var info=_msVarInfo(key);
  if(info&&info.interp){
    var ix=info.interp;
    if(/낮으면|부족|미흡|주의|위험|손실|제한/.test(ix)){
      var cut=ix.split(/\.|。/)[0];
      return cut.length>150?cut.slice(0,147)+'…':cut;
    }
  }
  if(st.label==='미흡'||st.label==='부족') return '엘리트 하위 범위 — 이 구간 연결·타이밍이 약할 수 있음';
  if(st.label==='높음') return '엘리트 상위 범위 초과 — 과도한 패턴 여부 확인';
  if(st.label==='위험'||st.label==='위험·주의'||st.label==='주의') return '주의 신호 — 단계별 타이밍·연결 확인 권장';
  return '엘리트 범위 이탈 패턴 — 코치 관점에서 연결·타이밍 확인';
}
function _msCueLine(key,cp,spec,st){
  if(spec&&spec.displayPolicy==='type_context') return '유형 변인 — 코칭 cue 해당 없음';
  if(spec&&spec.displayPolicy==='research_only') return '연구 보조 변인 — 코칭 cue 선택';
  if(cp.coachCue) return cp.coachCue;
  if(spec&&spec.correctionCue) return spec.correctionCue;
  try{
    if(typeof coachingPrescription!=='undefined'&&coachingPrescription.drillsForKey){
      var ds=coachingPrescription.drillsForKey(key,1);
      if(ds&&ds[0]&&ds[0].coachingCue) return ds[0].coachingCue;
    }
  }catch(e){}
  if(st&&(st.label==='미흡'||st.label==='부족'||st.label==='주의'||st.label==='위험')){
    var pk=null;
    try{ if(_BM_PH){ for(var i=0;i<_BM_PH.length;i++){ var det=_BM_PH[i]; if(det&&det.sub){ for(var j=0;j<det.sub.length;j++) if(det.sub[j]&&det.sub[j].key===key){ pk=det.key; break; } } if(pk) break; } } }catch(e){}
    if(pk&&typeof _BM_DRILL!=='undefined'&&_BM_DRILL[pk]&&_BM_DRILL[pk].cue) return _BM_DRILL[pk].cue;
  }
  return '코치 맥락에서 관찰 포인트 확인';
}
function _renderMechanicsSummaryInspectorDeep(key,m,spec,cp,card){
  var nm=(key&&typeof BIOMOTION_NORMS!=='undefined')?BIOMOTION_NORMS[key]:null;
  function fN(x){return (Math.round(x*10)/10);}
  var normsLine='';
  if(nm) normsLine='<div class="note" style="margin-top:4px"><b>엘리트 분포</b> · p25 '+fN(nm.p25)+' · 중앙 '+fN(nm.med)+' · p75 '+fN(nm.p75)+(nm.n?' (n='+nm.n+')':'')+'</div>';
  var raw=(m&&m.value!=null&&isFinite(m.value))?(m.value+(m.unit||'')):((card&&card.value!=null)?(card.value+(card.unit||'')):'—');
  return '<div style="margin-top:8px;line-height:1.55;padding-left:2px">'
    +'<div class="note"><b>변인 정의</b> · '+cp.analystDefinition+'</div>'
    +'<div class="note" style="margin-top:4px"><b>산출 방법</b> · '+cp.analystCalculation+'</div>'
    +'<div class="note" style="margin-top:4px"><b>평가 기준</b> · '+cp.evaluationPolicy+'</div>'
    +'<div class="note" style="margin-top:4px"><b>분석원용 해석</b> · '+cp.analystInterpretation+'</div>'
    +_coachRxDrillSection(key)
    +'<div class="note" style="margin-top:4px"><b>raw value</b> · '+raw+'</div>'
    +(cp.researchNote?('<div class="note" style="margin-top:4px;color:var(--fg2)"><b>research note</b> · '+cp.researchNote+'</div>'):'')
    +normsLine+'</div>';
}
function _renderMechanicsSummaryInspector(key){
  try{
    var hit=_varDetailMetricHit(key), m=hit?hit.metric:null;
    var spec=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(key):null;
    var card=_vsResolveCard(key);
    var cp=_varCopyResolve(key,spec,m);
    var label=(spec&&spec.labelKo)||(card&&card.labelKo)||(m&&m.label)||key;
    var st=_varDetailStatusLabel(m,key,spec);
    var meta=(typeof mech5!=='undefined'&&mech5&&mech5.bandMeta)?mech5.bandMeta(st.label):null;
    var vis=_efBandVisual(st.label,meta,(st.label==='위험'||st.label==='위험·주의'));
    var valTxt=(card&&card.value!=null&&card.value!=='')?(card.value+(card.unit||'')):(m&&m.value!=null&&isFinite(m.value)?(m.value+(m.unit||'')):'—');
    var weak=(st.label==='미흡'||st.label==='위험'||st.label==='주의'||st.label==='부족'||st.label==='높음');
    var probCls=weak?'bm-compact-problem-weak':'bm-compact-problem-ok';
    var nm=(key&&typeof BIOMOTION_NORMS!=='undefined')?BIOMOTION_NORMS[key]:null;
    var bandMini=(nm&&m&&m.value!=null&&isFinite(m.value))?('<div class="bm-compact-band">'+_bmBandSVG(m.value,nm,m.dir,null,!!m.neutral,true,{hideNums:true,summary:true})+'</div>'):'';
    return '<article class="bm-compact-inspector-inner" id="bm-inspector-'+key+'" data-bm-inspector-key="'+key+'">'
      +'<div class="bm-compact-head"><div><div style="font-size:14px;font-weight:800">'+_ezLabel(label)+'</div><div style="margin-top:4px;font-size:15px;font-weight:800;color:'+st.color+'">'+valTxt+'</div></div>'+vis.chip+'</div>'
      +bandMini
      +'<dl class="bm-compact-fields">'
      +'<div class="bm-compact-row"><dt>현재 상태</dt><dd style="color:'+st.color+';font-weight:800">'+st.label+'</dd></div>'
      +'<div class="bm-compact-row"><dt>한 줄 의미</dt><dd>'+_msMeaningLine(key,cp,spec,m)+'</dd></div>'
      +'<div class="bm-compact-row '+probCls+'"><dt>문제 가능성</dt><dd>'+_msProblemLine(key,cp,spec,st,m)+'</dd></div>'
      +'<div class="bm-compact-row"><dt>코칭 cue</dt><dd>'+_msCueLine(key,cp,spec,st)+'</dd></div>'
      +'</dl>'
      +'<div class="bm-compact-actions">'
      +'<details class="bm-compact-deep"><summary>자세히 보기</summary>'+_renderMechanicsSummaryInspectorDeep(key,m,spec,cp,card)+'</details>'
      +'<button type="button" class="bm-focus-btn" onclick="_goMechanicsSummaryPhaseDetail(\''+key+'\')">단계 상세에서 보기</button>'
      +'</div></article>';
  }catch(e){ return '<div class="note">inspector 오류: '+key+'</div>'; }
}
function _updateMechanicsSummaryInspectorUI(key){
  try{
    document.querySelectorAll('.bm-var-tile.is-active').forEach(function(el){ el.classList.remove('is-active'); });
    if(key){
      var tile=document.getElementById('bm-var-'+key)||document.querySelector('.bm-var-tile[data-bm-var-key="'+key+'"]');
      if(tile) tile.classList.add('is-active');
    }
    var host=document.getElementById('bm-compact-inspector');
    if(!host) return;
    if(!key){
      host.setAttribute('hidden','');
      host.classList.remove('has-selection');
      var body0=document.getElementById('bm-compact-inspector-body'); if(body0) body0.innerHTML='';
      var ph0=host.querySelector('.bm-compact-inspector-placeholder'); if(ph0) ph0.style.display='';
      return;
    }
    host.removeAttribute('hidden');
    host.classList.add('has-selection');
    var ph=host.querySelector('.bm-compact-inspector-placeholder'); if(ph) ph.style.display='none';
    var body=document.getElementById('bm-compact-inspector-body');
    if(body) body.innerHTML=_renderMechanicsSummaryInspector(key);
    host.scrollIntoView({behavior:'smooth',block:'nearest'});
  }catch(e){ if(typeof console!=='undefined'&&console.warn) console.warn('[updateMechanicsSummaryInspectorUI]',e); }
}
function selectMechanicsSummaryVar(key){
  if(!key) return;
  _BM_VAR_SEL=key;
  window.selectedVariableKey=key;
  if(_isAnalystMechSummaryFullpage()){
    try{
      if(typeof MECH_DEFECT_MAP!=='undefined'&&MECH_DEFECT_MAP.selectVar) MECH_DEFECT_MAP.selectVar(key);
    }catch(e){}
    return;
  }
  _selectVarStickViz(key);
  _updateMechanicsSummaryInspectorUI(key);
  _renderReportSidePanels(key);
}
function _goMechanicsSummaryPhaseDetail(key){
  if(!key) return;
  var pg=_pageForVarDetail(key);
  if(!pg||typeof setPage!=='function') return;
  setPage(pg);
  setTimeout(function(){
    if(typeof selectVariableForCoach==='function') selectVariableForCoach(key);
    try{
      var panel=document.getElementById('var-stick-viz-panel');
      if(panel&&panel.scrollIntoView) panel.scrollIntoView({behavior:'smooth',block:'nearest'});
      else if(typeof _scrollToVarDetailOnly==='function') _scrollToVarDetailOnly(key);
    }catch(e){}
  },280);
}
window.selectMechanicsSummaryVar=selectMechanicsSummaryVar;
window._goMechanicsSummaryPhaseDetail=_goMechanicsSummaryPhaseDetail;
function _updateVarInspectorUI(key){
  try{
    if(!key) return;
    document.querySelectorAll('.phase-var-pill.is-active').forEach(function(el){ el.classList.remove('is-active'); });
    var pill=document.getElementById('var-pill-'+key)||document.querySelector('.phase-var-pill[data-var-key="'+key+'"]');
    if(pill) pill.classList.add('is-active');
    var pg=_pageForVarDetail(key);
    var host=pg?document.getElementById('phase-var-inspector-'+pg):null;
    if(!host) return;
    var ph=host.querySelector('.phase-var-inspector-placeholder');
    var body=host.querySelector('.phase-var-inspector-body');
    if(!body) return;
    var card=_vsResolveCard(key);
    body.innerHTML=_renderVariableInspectorContent(key,card,pg);
    body.style.display='';
    if(ph) ph.style.display='none';
    host.classList.add('has-selection');
  }catch(e){ if(typeof console!=='undefined'&&console.warn) console.warn('[updateVarInspectorUI]',e); }
}
function selectVariableForCoach(key){
  if(!key) return;
  if(_isCoachReportMode()&&_isCoachFieldHiddenKey(key)) return;
  if(_isMechanicsSummaryPage()){ selectMechanicsSummaryVar(key); return; }
  window.selectedVariableKey=key;
  if(_isCoachReportMode()){
    window._coachNavActiveVar=key;
    var pk=_coachPhaseKeyForVar(key);
    if(pk) window._coachNavActivePhase=pk;
  }
  var curTab=document.querySelector('.tab.active');
  var curPage=(curTab&&curTab.dataset)?curTab.dataset.page:'';
  var run=function(){
    var stickSource = (typeof _isResearchView === 'function' && _isResearchView() && !_isCoachReportMode()) ? 'research' : 'detail';
    try {
      applyStickVisualPreset({
        key: key,
        source: stickSource,
        updateCoachNav: false,
        renderCoachCue: !!_isCoachReportMode(),
        scrollDetail: false
      });
    } catch (e) {
      _selectVarStickViz(key);
    }
    _updateVarInspectorUI(key);
    _renderReportSidePanels(key);
    try{
      document.querySelectorAll('.core35-var-chip').forEach(function(ch){
        ch.classList.toggle('on',ch.dataset&&ch.dataset.varKey===key);
      });
      document.querySelectorAll('.core35-energy-node[data-axis-id]').forEach(function(n){ n.classList.remove('energy-axis-active'); });
    }catch(e){}
  };
  if(_isCoachReportMode()&&(curPage==='feedback-view'||curPage==='coach-view')){
    run();
    return;
  }
  if(curPage==='hpa'){
    run();
    return;
  }
  var pg=_pageForVarDetail(key);
  var runPhase=function(){
    run();
    var insp=pg?document.getElementById('phase-var-inspector-'+pg):null;
    if(insp) insp.scrollIntoView({behavior:'smooth',block:'nearest'});
  };
  if(pg&&curPage!==pg&&typeof setPage==='function'){ setPage(pg); setTimeout(runPhase,240); }
  else runPhase();
}
function _selectVarCoachView(key){ selectVariableForCoach(key); }
function _scrollToVarDetailOnly(key){
  try{
    if(!key) return;
    var el=document.getElementById('var-detail-'+key);
    if(!el) el=document.querySelector('[data-var-detail-key="'+key+'"]');
    if(!el) return;
    var det=el.closest('details.phase-research-extra-acc');
    if(det&&!det.open) det.open=true;
    el.scrollIntoView({behavior:'smooth',block:'start'});
    el.style.outline='2px solid var(--cyan)';
    el.classList.add('var-detail-selected');
    document.querySelectorAll('.phase-var-detail.var-detail-selected').forEach(function(x){ if(x!==el) x.classList.remove('var-detail-selected'); });
    setTimeout(function(){ el.style.outline=''; },1400);
  }catch(e){}
}
function _scrollToVarDetail(key){
  try{
    if(!key) return;
    if(typeof _isResearchView==='function'&&!_isResearchView()&&typeof selectVariableForCoach==='function'){
      selectVariableForCoach(key);
      return;
    }
    _selectVarStickViz(key);
    var el=document.getElementById('var-detail-'+key);
    if(!el) el=document.querySelector('[data-var-detail-key="'+key+'"]');
    if(!el){
      var pg=_pageForVarDetail(key);
      if(pg&&typeof setPage==='function'){
        var cur=(document.querySelector('.tab.active')||{}).dataset;
        if(!cur||cur.page!==pg){ setPage(pg); setTimeout(function(){ _scrollToVarDetailOnly(key); },240); return; }
      }
    }
    if(el){
      var det=el.closest('details.phase-research-extra-acc');
      if(det&&!det.open) det.open=true;
      el.scrollIntoView({behavior:'smooth',block:'start'});
      el.style.outline='2px solid var(--cyan)';
      el.classList.add('var-detail-selected');
      document.querySelectorAll('.phase-var-detail.var-detail-selected').forEach(function(x){ if(x!==el) x.classList.remove('var-detail-selected'); });
      setTimeout(function(){ el.style.outline=''; },1400);
      return;
    }
    var msg='변인 상세 블록 없음: '+key;
    if(typeof console!=='undefined'&&console.warn) console.warn('[scrollToVarDetail]',msg);
    var host=document.querySelector('section.page.visible')||document.querySelector('.right-panel');
    if(host){
      var noteId='var-detail-miss-'+key;
      var prev=document.getElementById(noteId);
      if(prev) prev.remove();
      var note=document.createElement('div');
      note.id=noteId; note.className='note'; note.style.cssText='grid-column:1/-1;margin:8px 0;padding:10px 12px;border:1px solid var(--amber);border-radius:8px;color:var(--amber)';
      note.textContent=msg+' · 해당 단계에 detail_block/research_extra 등록 여부 확인';
      host.insertBefore(note, host.firstChild);
      setTimeout(function(){ try{ note.remove(); }catch(e){} },5000);
    }
  }catch(e){ if(typeof console!=='undefined'&&console.warn) console.warn('[scrollToVarDetail]',e); }
}
