function _varDetailStatusLabel(m,key,spec){
  var M6=(typeof mech5!=='undefined')?mech5:null, NB=(typeof BIOMOTION_NORMS!=='undefined')?BIOMOTION_NORMS:null;
  if(spec&&spec.displayPolicy==='type_context') return {label:'전략 유형 · 점수/결함 판정 없음',color:'var(--cyan)'};
  if(_VAR_DETAIL_PENALTY_KEYS[key]||(spec&&spec.displayPolicy==='penalty')) return {label:'조건부 penalty · 우수/미흡 판정 없음',color:'var(--amber)'};
  if(_VAR_DETAIL_RISK_KEYS[key]||(spec&&spec.displayPolicy==='risk_flag')) return {label:(m&&m.warn)?'위험·주의':'위험 참고',color:'var(--amber)'};
  if(_VAR_DETAIL_LOAD_KEYS[key]||_VAR_DETAIL_LOAD_CONTEXT_KEYS[key]||(spec&&spec.displayPolicy==='load_context')) return {label:'부하·맥락 · 우수/미흡 판정 없음',color:'var(--cyan)'};
  if(!m||m.value==null) return {label:'값 없음',color:'var(--fg2)'};
  var ddir=_displayDirForMetric(key,m);
  if(M6&&NB&&NB[key]&&M6.bandWord&&ddir){
    var w=M6.bandWord(m.value,NB[key],ddir);
    var meta=M6.bandMeta?M6.bandMeta(w):null;
    return {label:w||'—',color:(meta&&meta.color)||'var(--fg1)'};
  }
  return {label:'분포·맥락',color:'var(--cyan)'};
}
function _varDetailStatusColor(code){
  if(code==='weak') return 'var(--amber)';
  if(code==='strong') return 'var(--green)';
  if(code==='risk'||code==='caution') return 'var(--red)';
  return 'var(--cyan)';
}
function _varDetailMetricBand(m,key){
  var M6=(typeof mech5!=='undefined')?mech5:null, NB=(typeof BIOMOTION_NORMS!=='undefined')?BIOMOTION_NORMS:null;
  if(_VAR_DETAIL_PENALTY_KEYS[key]) return {code:'caution',label:'penalty'};
  if(_VAR_DETAIL_LOAD_KEYS[key]||_VAR_DETAIL_LOAD_CONTEXT_KEYS[key]) return {code:'na',label:'부하·맥락'};
  var ddir=_displayDirForMetric(key,m);
  if(!m||m.value==null||!isFinite(m.value)||m.neutral||!ddir||!M6||!NB||!NB[key]) return {code:'na',label:'—'};
  var b=M6.band(m.value,NB[key],ddir);
  if(!b) return {code:'na',label:'—'};
  if(b==='미흡') return {code:'weak',label:'미흡'};
  if(b==='우수') return {code:'strong',label:'우수'};
  if(b==='부족'||b==='높음') return {code:'caution',label:b};
  return {code:'ok',label:b||'정상'};
}
function _varDetailResolveVizType(key,spec,m){
  if(!spec) return 'bandGauge';
  var vt=spec.visualType||'bandGauge';
  if(key==='leadKneeFlexFC'||spec.visualSubType==='eventSnapshotLink') return 'bandGauge';
  if(_VAR_DETAIL_TYPE_KEYS[key]||spec.displayPolicy==='type_context'||vt==='typeCard') return 'typeCard';
  if(_VAR_DETAIL_RISK_KEYS[key]||spec.displayPolicy==='risk_flag'||spec.displayPolicy==='penalty'||vt==='riskPanel') return 'riskPanel';
  if(_VAR_DETAIL_LOAD_KEYS[key]||spec.displayPolicy==='load_context'||((spec.energyRole||[]).indexOf('load')>=0&&vt==='riskPanel')) return 'loadGauge';
  if(spec.displayPolicy==='range_context'||(m&&(m.dir==='range'||m.itype==='optimal'||m.itype==='transition'))) return 'rangeGauge';
  if((m&&m.unit==='ms')||/Timing|Lag$/.test(key)||vt==='timingLollipop') return 'timingGauge';
  if(vt==='timeSeriesWithEvents'||(vt==='timeSeriesWithImpulse'&&typeof _FC_SER!=='undefined'&&_FC_SER[key])) return 'timeSeriesWithEvents';
  if(vt==='rangeBand') return 'rangeGauge';
  return 'bandGauge';
}
