function _varDetailVizHtml(key,m,spec,card,stageKey){
  var vt=_varDetailResolveVizType(key,spec,m);
  var html='', isFb=false;
  if(vt==='riskPanel') html=_varDetailRiskPanelHtml(m,key,spec);
  else if(vt==='typeCard') html=_varDetailTypeCardHtml(m,key,spec);
  else if(vt==='loadGauge') html=_varDetailLoadGaugeHtml(m,key,spec);
  else if(vt==='rangeGauge') html=_varDetailRangeGaugeHtml(m,key,spec);
  else if(vt==='timingGauge') html=_varDetailTimingGaugeHtml(m,key,spec);
  else html=_varDetailBandGaugeHtml(m,key,spec);
  if(spec&&spec.placeholder){ html+='<div class="note" style="margin-top:6px;color:var(--fg2)">메타 보강 중 · 값·규준·아래 이벤트표 참고</div>'; isFb=true; }
  _vdP1Log(key,vt,stageKey,isFb);
  return {html:html,vt:vt};
}
function _varStickRiskPanelHtml(m,key,spec){
  var val=(m&&m.value!=null)?(m.value+(m.unit||spec.unit||'')):'—';
  var col=(m&&m.warn)?'var(--red)':'var(--amber)';
  return '<div class="varvis-risk varvis-risk-stick" style="padding:10px 12px;background:rgba(255,77,77,.08);border:1px solid var(--red);border-radius:8px">'
    +'<div style="font-size:12px;font-weight:700;color:var(--red)">위험·주의</div>'
    +'<div style="margin-top:6px;font-size:22px;font-weight:800;color:'+col+'">'+val+'</div>'
    +(m&&m.warn?'<div style="margin-top:4px;font-size:12px;font-weight:700;color:var(--amber)">'+m.warn+'</div>':'')+'</div>';
}
function _varStickTypeCardHtml(m,key,spec){
  var txt=(m&&m.value!=null)?String(m.value):'—';
  if(key==='windupType'&&typeof phases!=='undefined'&&phases.windupType&&typeof DATA!=='undefined'&&DATA.phases){
    try{ var wt=phases.windupType(DATA.phases); if(wt&&wt.easy) txt=wt.easy+(wt.name?(' ('+wt.name+')'):''); }catch(e){}
  }
  if(key==='strideType'&&typeof phases!=='undefined'&&phases.strideType&&DATA&&DATA.phases){
    try{ var st=phases.strideType(DATA.phases); if(st&&st.easy) txt=st.easy+(st.name?(' ('+st.name+')'):''); }catch(e){}
  }
  if(key==='blockingType'&&typeof DATA!=='undefined'&&DATA.phases&&DATA.phases.blockingType){
    var bt=DATA.phases.blockingType; txt=(bt.easy||bt.label||bt.key||txt);
  }
  return '<div class="varvis-type varvis-type-stick" style="padding:12px;background:var(--bg2);border-radius:8px;border:1px solid var(--line)">'
    +'<div style="font-size:12px;color:var(--fg2)">유형</div>'
    +'<div style="font-size:20px;font-weight:800;margin-top:4px">'+_fvEsc(txt)+'</div></div>';
}
function _varStickLoadGaugeHtml(m,key,spec){
  var val=m&&m.value, band=_varDetailMetricBand(m,key);
  var col=band.code==='weak'||band.code==='caution'?'var(--red)':(band.code==='strong'?'var(--green)':'var(--amber)');
  var pct=50;
  if(val!=null&&isFinite(val)){
    var nm=(typeof BIOMOTION_NORMS!=='undefined')?BIOMOTION_NORMS[key]:null;
    if(nm&&nm.p75>nm.p25){ pct=Math.max(5,Math.min(98,((val-nm.p25)/(nm.p75-nm.p25||1))*100)); }
  }
  return '<div class="varvis-loadgauge varvis-load-stick" style="padding:10px 12px;background:rgba(255,149,78,.06);border:1px solid var(--amber);border-radius:8px">'
    +'<div style="font-size:22px;font-weight:800;color:'+col+'">'+(val!=null?val:'—')+(m.unit||spec.unit||'')+'</div>'
    +'<div style="height:8px;background:var(--bg2);border-radius:4px;margin:8px 0"><div style="width:'+pct+'%;height:100%;background:linear-gradient(90deg,var(--amber),var(--red));border-radius:4px"></div></div>'
    +'<div style="font-size:12px;font-weight:700;color:'+col+'">'+band.label+'</div></div>';
}
function _varStickTimingGaugeHtml(m,key,spec){
  var val=m&&m.value, nm=(typeof BIOMOTION_NORMS!=='undefined')?BIOMOTION_NORMS[key]:null;
  var bar='';
  if(nm&&val!=null&&isFinite(val)){
    var lo=nm.p25, hi=nm.p75, span=hi-lo||1, pos=Math.max(0,Math.min(100,((val-lo)/span)*100));
    bar='<div style="height:8px;background:var(--bg2);border-radius:4px;margin:8px 0;position:relative"><div style="position:absolute;left:0;width:100%;height:100%;background:linear-gradient(90deg,rgba(232,149,78,.25),rgba(70,201,140,.35),rgba(232,149,78,.25));border-radius:4px"></div>'
      +'<div style="position:absolute;left:'+pos+'%;top:-2px;width:3px;height:12px;background:#fff;border-radius:2px;transform:translateX(-50%)"></div></div>'
      +'<div class="sub2">p25–p75: '+lo+' – '+hi+' ms</div>';
  }
  return '<div class="varvis-timinggauge varvis-timing-stick" style="padding:10px 12px;background:var(--bg2);border-radius:8px;border-left:3px solid #8ea9cf">'
    +'<div style="font-size:22px;font-weight:800">'+(val!=null?val:'—')+(m.unit||spec.unit||'ms')+'</div>'+bar+'</div>';
}
function _varStickVizGaugeHtml(key,m,spec){
  var vt=_varDetailResolveVizType(key,spec,m);
  var html='';
  if(vt==='riskPanel') html=_varStickRiskPanelHtml(m,key,spec);
  else if(vt==='typeCard') html=_varStickTypeCardHtml(m,key,spec);
  else if(vt==='loadGauge') html=_varStickLoadGaugeHtml(m,key,spec);
  else if(vt==='rangeGauge') html=_varDetailRangeGaugeHtml(m,key,spec);
  else if(vt==='timingGauge') html=_varStickTimingGaugeHtml(m,key,spec);
  else html=_varDetailBandGaugeHtml(m,key,spec);
  return {html:html,vt:vt};
}
// VAI 왕복: 변인 설명 → 공용 다변량 차트(해당 변인 강조) → 변인 설명
