function _coachRxDrillSection(key){
  try{
    if(typeof coachingPrescription==='undefined'||!coachingPrescription.isPriorityKey) return '';
    if(!coachingPrescription.isPriorityKey(key)){
      return '<div class="note" style="margin-top:8px;color:var(--fg2)"><b>훈련 방향</b> · 코칭 처방 MVP는 16개 핵심 변인만 제공 — Feedback View 핵심 문제·훈련 포인트 참고</div>';
    }
    var drills=coachingPrescription.drillsForKey?coachingPrescription.drillsForKey(key,2):[];
    if(!drills.length) return '';
    var rows=drills.map(function(d){
      return '<li style="margin-bottom:5px"><b>'+(d.nameKo||d.drillId)+'</b> · '+(d.objectiveKo||'')
        +(d.coachingCue?('<br><span class="sub2">우선 확인할 훈련 방향</span> · '+d.coachingCue):'')+'</li>';
    }).join('');
    var caut='';
    var c=coachingPrescription.getCause&&coachingPrescription.getCause(key);
    if(c&&c.caution) caut='<div class="note" style="margin-top:4px;color:var(--fg2)"><b>해석 주의</b> · '+c.caution+'</div>';
    return '<div class="note" style="margin-top:8px;line-height:1.55"><b>우선 확인할 훈련 방향</b> (처방·단정 아님)<ul style="margin:4px 0 0 18px">'+rows+'</ul>'+caut+'</div>';
  }catch(e){ return ''; }
}
