    if(!parts.research.length) return '';
    var inner=parts.research.map(function(c){ return _renderResearchExtraBlock(c.key,c,cfg.pageKey); }).join('');
    return '<details class="card phase-research-extra-acc" style="grid-column:1/-1;border-left:4px solid var(--fg2)" data-page-key="'+cfg.pageKey+'">'
