function _paintVarDetailChart(canvasId,key){
  if(typeof plotWin!=='function'||typeof _FC_SER==='undefined'||!_FC_SER[key]) return;
  var cfg=_FC_SER[key], ft=(typeof _fastTrial==='function')?_fastTrial():null;
  if(!ft) return;
  var spec=(typeof VAR_VIS!=='undefined'&&VAR_VIS.get)?VAR_VIS.get(key):null;
  var stickVt=spec?_resolveStickVisualType(key,spec,null):'eventTimeSeries';
  var tw=_vsResolveTsPlotWindow(key,spec,{impulseArea:stickVt==='impulseArea'});
  var core=_vsCoreEventWindow(spec);
  try{
    plotWin(canvasId,{fast:ft,startEv:tw.startEv,startOff:tw.startOff,endEv:tw.endEv,endOff:tw.endOff,
      lockWindow:tw.lockWindow,varTs:true,shadeCore:core,dimPadding:tw.lockWindow&&!tw.fullRange,peakAbs:true,
      left:{label:'',lines:[{compute:cfg.fn,color:cfg.c||'#5bb6e6',label:(spec&&spec.labelKo)||key,width:2.4}]},
      noGauge:true,fillToZero:(stickVt==='impulseArea'),markPeaks:true});
  }catch(e){}
}
function _initVarDetailCharts(pageKey){
  try{
    var root=document.getElementById('page-'+pageKey); if(!root) return;
    root.querySelectorAll('canvas.var-detail-ts[data-var-ts-key]').forEach(function(cv){
      var key=cv.getAttribute('data-var-ts-key'); if(key&&cv.id) _paintVarDetailChart(cv.id,key);
    });
    if(typeof VAR_DETAIL_P1!=='undefined'&&VAR_DETAIL_P1.initPage) VAR_DETAIL_P1.initPage(pageKey);
  }catch(e){}
}
function _embedPhaseSeriesInHost(phaseKey,hostId){
  var host=document.getElementById(hostId);
  if(!host||host.dataset.embedded==='1') return;
  var scratch=document.createElement('div');
  scratch.id='phch-'+phaseKey;
  scratch.setAttribute('aria-hidden','true');
  scratch.style.cssText='position:fixed;left:-12000px;top:0;width:8px;height:8px;overflow:hidden;pointer-events:none';
  document.body.appendChild(scratch);
  try{ renderPhaseTab(phaseKey); host.innerHTML=scratch.innerHTML; host.dataset.embedded='1'; }catch(e){ host.innerHTML='<div class="note">시계열 로드 오류: '+String(e&&e.message||e)+'</div>'; }
  try{ scratch.remove(); }catch(e){}
  try{ _redrawPhaseCharts(); }catch(e){}
}
function _onPhaseResearchAccToggle(el){
  if(!el||!el.open) return;
  var pageKey=el.getAttribute('data-page-key')||'';
  var stageKeys=(el.getAttribute('data-stage-keys')||'').split(',').filter(Boolean);
  stageKeys.forEach(function(pk){
    _embedPhaseSeriesInHost(pk,'phase-native-'+pageKey+'-'+pk);
  });
  try{
    var sel=document.getElementById('trial-select');
    var ap=document.querySelector('.tab.active');
    if(ap&&ap.dataset.page===pageKey) renderTrialSpecific(sel?parseInt(sel.value,10):0,pageKey);
  }catch(e){}
}
function _openPhaseResearchSection(pageKey){
  try{
    var det=document.querySelector('#page-'+pageKey+' details.phase-research-extra-acc');
    if(det){ if(!det.open) det.open=true; det.scrollIntoView({behavior:'smooth',block:'start'}); return; }
    var first=document.querySelector('#page-'+pageKey+' [data-var-detail-key]');
    if(first){ first.scrollIntoView({behavior:'smooth',block:'start'}); return; }
    setPage(pageKey);
  }catch(e){ try{ setPage(pageKey); }catch(e2){} }
}
