  var useRdV1=_rdV1UseCoachGlance()&&!!_RD_V1_PAGE_TO_FLOW[cfg.pageKey];
  var parts=[], legacy=[];
  if(useRdV1){
    try{ parts.push(_rdV1StageGlanceHtml(cfg,collectFn)); }catch(e){ parts.push('<div class="note">rd-v1 단계 오류: '+String(e&&e.message||e)+'</div>'); }
  }else{
    try{ parts.push(_renderStageCoachIntro(cfg)); }catch(e){ parts.push('<div class="note">단계 설명 오류</div>'); }
    try{ parts.push(_renderStagePriorityBlock(cfg)); }catch(e){}
  }
  try{ parts.push(_rdV1ResearchAnalystBlock(cfg,collectFn)); }catch(e){}
  try{ legacy.push(_renderStageCoachIntro(cfg)); }catch(e){}
  try{ legacy.push(_renderStagePriorityBlock(cfg)); }catch(e){}
