      var tag=isPenalty?' <span style="font-size:9px;color:#e8954e">penalty</span>':((c.isRisk||c.isCriticalRisk)?' <span style="font-size:9px;color:'+P.bad+'">위험</span>':(pr<40?' <span style="font-size:9px;color:'+P.bad+'">결함</span>':''));
