        +'<div style="font-size:12px;font-weight:800;color:'+cCol+'">'+(i+1)+'. '+_ezLabel(c.labelKo)+tag+'</div>'
        +'<div class="note" style="margin-top:4px;font-size:12px;line-height:1.45">'+valTxt+_fvEsc(_coachPriorityCopyLine(c.key,(typeof VAR_VIS!=='undefined'&&VAR_VIS.REGISTRY)?VAR_VIS.REGISTRY[c.key]:null,null,c).slice(0,180))+'</div></div>';
