function _injectVarLabels(key){
  var root=document.getElementById('ed-body-'+key);
  if(!root) return;
  // 변인명 검사 대상: 섹션 헤더(h2·h3·h4·strong) + 표 헤드(th) + 라벨(b, .ev-table td.evl)
  try{ var _SC={windup:'#e8954e',stride:'#3b82f6',blocking:'#3b82f6'}, _scol=_SC[key];
    root.querySelectorAll('.card').forEach(function(card){
      var ttl=card.firstElementChild;
      if(ttl && /font-weight:\s*800/.test(ttl.getAttribute('style')||'')){
        if(ttl.childElementCount===0){ ttl.textContent=(ttl.textContent||'').replace(/^\s*\d+\.\s*/,''); if(_scol) ttl.style.color=_scol; }
      }
    });
  }catch(e){}
  try{ root.querySelectorAll('.card').forEach(function(card){
    if(card.querySelector('.cv-desc-fold')) return;
    var notes=[],kids=card.children;
    for(var _k=0;_k<kids.length;_k++){ var n=kids[_k]; if(n.classList&&n.classList.contains('note')){ var t=n.textContent||''; if(/역할:|측정:|에너지 흐름 해석:|코칭:/.test(t)) notes.push(n); } }
    if(notes.length<2) return;
    var _ttlEl=card.firstElementChild, _ttl=_ttlEl?(_ttlEl.textContent||''):''; var _easy=(typeof _easyFor==='function')?_easyFor(_ttl):null;
    var det=document.createElement('details'); det.className='cv-desc-fold'; det.style.cssText='margin-top:8px;border:1px solid var(--line);border-radius:8px;background:var(--bg2)';
    var sm=document.createElement('summary'); sm.style.cssText='cursor:pointer;padding:8px 11px;font-size:12px;font-weight:700;color:var(--cyan)'; sm.textContent='설명'; det.appendChild(sm);
    var box=document.createElement('div'); box.style.cssText='padding:2px 11px 11px';
    if(_easy){ box.innerHTML=_easyInner(_easy); notes.forEach(function(n){ if(n.parentNode) n.parentNode.removeChild(n); }); det.open=true; }
    else { notes.forEach(function(n){ box.appendChild(n); }); }
    det.appendChild(box); card.appendChild(det);
  }); }catch(e){}
  var nodes=root.querySelectorAll('h2, h3, h4, b, th, strong, .ev-table td.evl');
  nodes.forEach(function(el){
    if(el.dataset.cvCat) return; // 이미 라벨 달림
    if(el.querySelector('.cv-var-badge')) return;
    var txt=(el.textContent||'').trim();
    if(!txt||txt.length>120) return;
    for(var i=0;i<_VAR_CAT_PATTERNS.length;i++){
      var pat=_VAR_CAT_PATTERNS[i][0], cat=_VAR_CAT_PATTERNS[i][1];
      if(txt.indexOf(pat)>=0){
        var s=_VAR_CAT_STYLE[cat];
        var badge=document.createElement('span');
        badge.className='cv-var-badge';
        badge.title=s.l+' 변인';
        // 굵은 세로 막대 + 라벨 텍스트
        badge.innerHTML='<span style="display:inline-block;width:5px;height:15px;background:'+s.c+';margin-right:5px;vertical-align:middle;border-radius:2px"></span><span style="font-size:11px;font-weight:800;color:'+s.c+';vertical-align:middle;margin-right:6px">'+s.l+'</span>';
        badge.style.cssText='display:inline-block;vertical-align:middle';
        el.insertBefore(badge,el.firstChild);
        el.dataset.cvCat=cat;
        try{ el.style.color=s.c; }catch(_){}   /* [2026-05-29] 변인 이름 텍스트도 역할 색(생성/전달/저장/부하) */
        break;
      }
    }
  });
}
function renderEdNode(key){
  if(key==='windup'){ try{ renderEdWindup(); _injectVarLabels(key); }catch(e){} return; }   // 와인드업 = 로딩 평가 전용 화면
  if(key==='xftiming'){ try{ renderEdXFactorTiming(); _injectVarLabels(key); }catch(e){} return; }  // X-factor = 진단 전용 화면
  if(key==='stride'){ try{ renderEdStride(); _injectVarLabels(key); }catch(e){} return; }   // 스트라이드 = 단계평가 전용 화면
  if(key==='blocking'){ try{ renderEdBlocking(); _injectVarLabels(key); }catch(e){} return; }  // 블로킹 = 단계평가 전용 화면
  if(key==='knee'){ try{ renderEdKnee(); _injectVarLabels(key); }catch(e){} return; }  // 무릎전달 = 단계평가 전용 화면
  if(key==='pelvistrunk'){ try{ renderEdPelvisTrunk(); _injectVarLabels(key); }catch(e){} return; }  // 골반→몸통 = 단계평가 전용 화면
  if(key==='trunk'){ try{ renderEdTrunk(); _injectVarLabels(key); }catch(e){} return; }  // 몸통 에너지 = 단계평가 전용 화면
  if(key==='trunkarm'){ try{ renderEdTrunkArm(); _injectVarLabels(key); }catch(e){} return; }  // 몸통→팔 = 단계평가 전용 화면
  if(key==='armball'){ try{ renderEdArmBall(); _injectVarLabels(key); }catch(e){} return; }  // 팔→공 = 단계평가 전용 화면
  var root=document.getElementById('ed-body-'+key); if(!root) return;
  var X=(typeof ETDIAG!=='undefined')?ETDIAG:null;
  if(!X){ root.innerHTML='<div class="card"><div class="note">에너지 전달 진단 데이터 없음 (지면반력+관절파워 있는 Theia 분석 필요)</div></div>'; return; }
  var s=null; (X.stages||[]).forEach(function(x){ if(x.key===key) s=x; });
  if(!s){ root.innerHTML='<div class="card"><div class="note">단계 데이터 없음</div></div>'; return; }
  var c=_edCol(s.status), idx=0, prev=null, next=null;
  for(var i=0;i<_ED_NODES.length;i++){ if(_ED_NODES[i][0]===key){ idx=i; prev=_ED_NODES[i-1]; next=_ED_NODES[i+1]; } }
  function btn(lbl,pg,col){ return '<button class="bm-focus-btn" onclick="setPage(\''+pg+'\')" style="font-size:12px;background:var(--bg1);border:1px solid var(--line);color:'+(col||'var(--fg2)')+';border-radius:6px;padding:6px 12px;cursor:pointer">'+lbl+'</button>'; }
  var html='<div class="card" style="grid-column:1 / -1;border-left:4px solid '+c+'">'
    +'<div style="display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:8px">'
    +'<div style="font-size:17px;font-weight:800">'+(idx+1)+'. '+s.label+_edTagChip(s.tag)+'</div>'
    +'<div style="font-size:13px;font-weight:800;color:'+c+'">'+_edKo(s.status)+(s.score==null?'':' · '+s.score+'점')+'</div></div>'
    +'<div class="note" style="margin-top:8px;font-size:13px">'+s.rep+'</div>';
  if(s.story){
    html+='<div style="margin-top:10px;background:var(--bg2);border-radius:8px;padding:10px 13px;line-height:1.7;font-size:13px">'
      +'<div><b style="color:var(--cyan)">측정</b> — '+s.story.measure+'</div>'
      +'<div style="margin-top:5px"><b style="color:var(--cyan)">에너지 흐름상 의미</b> — '+s.story.meaning+'</div>'
      +'<div style="margin-top:5px"><b style="color:var(--cyan)">개선 방향</b> — '+s.story.improve+'</div></div>';
  }
  html+='<div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap">'
    + btn('이 단계 스틱·스틱게이지·시계열 자세히 보기 →',(_ED_DETAIL[key]||'biomotion'),'var(--cyan)')
    + btn('← 요약','psummary')
    + (prev?btn('‹ '+prev[1],'ed-'+prev[0]):'')
    + (next?btn(next[1]+' ›','ed-'+next[0]):'')
    + '</div></div>';
  // ── 진단3 스트라이드: Hip Hinge 로딩 보존 브리지 (와인드업 로딩이 FC까지 유지됐나) ──
  if(key==='stride' && X.windup){ var Wp=X.windup, hh=Wp.hipHinge, pc=Wp.pelvicClosure;
    var rp=(hh.trunkPelvisRetainedPct);
    html+='<div class="card" style="grid-column:1 / -1;border-left:3px solid var(--cyan)"><div style="font-size:13px;font-weight:800">힘 모으기 보존 — 힙힌지 (힘 모으기 → 앞으로 나가기) <span class="sub2">분석용: 로딩 보존 브리지 · Hip Hinge</span></div>'
      +'<div class="note" style="margin-top:4px">힘 모으기에서 만든 엉덩이 접힘(힙힌지) 자세의 앞발 착지까지 유지 여부 · 접힘 최대 '+(hh.trunkPelvisPeak==null?'–':hh.trunkPelvisPeak+'°')+' → <b>착지 순간 '+(hh.trunkPelvisAtFC==null?'–':hh.trunkPelvisAtFC+'°')+' · 유지율 '+(rp==null?'–':rp+'%')+'</b> · (참고) 골반 닫힘 유지 '+(pc.retainedPct==null?'–':pc.retainedPct+'%')+'</div>'
      +'<div class="note" style="margin-top:4px">'+((rp!=null&&rp<50)?'힘 모으기 자세가 전진 중 풀려 착지까지 미유지 → 착지 후 회전용 힘 감소':'자세가 착지까지 비교적 잘 유지 → 착지 후 전환 준비')+' (착지 이후 상체 앞 숙임은 힙힌지 아닌 몸통 힘 생성 동작 → \'몸통으로 힘 키우기\' 단계에서 평가)</div></div>';
  }
  // ── 진단7 몸통 에너지: FC 이후 몸통 굴곡 = trunk flexion energy 분리 안내 ──
  if(key==='trunk' && X.windup){
    html+='<div class="card" style="grid-column:1 / -1"><div class="note"><b>참고(힙힌지와 구분):</b> FC <b>이후</b> 몸통 앞 굴곡 = 와인드업 힙힌지(로딩) 아닌 <b>몸통 굴곡 에너지(trunk flexion)</b> · 와인드업 힙힌지(진단1)=로딩, 진단7 몸통 굴곡=릴리스 향한 에너지 생성으로 분리 평가</div></div>';
  }
  root.innerHTML=html;
}
