  try{ plotWin('edc-wind-sher',Object.assign({left:{label:'어깨 외회전 (°)',lines:[{compute:function(t){var a=t.series.Pitching_Shoulder_Angle_Z;return a?a.map(function(x){return isFinite(x)?Math.abs(x):NaN;}):null;},color:'#e879f9',label:'어깨 외회전(절대)',width:2.6}]}},W0)); }catch(e){}
  // 스틱 게이지(우측) — 메인 3D 스틱 프레임 연동 · 고정 윈도우[w0,w1] 스케일 + 현재 프레임 수치 오버레이
