  if(cf!=null){var ft=(typeof _fastTrial==='function')?_fastTrial():null;var ifc=(ft&&ft.events&&ft.events.i_fc)||0,dtv=(ft&&ft.meta&&ft.meta.dt)||0.00333;var curMs=(cf-ifc)*dtv*1000;var bp=null,bd=1e9;P.forEach(function(p){var d=Math.abs(p[0]-curMs);if(d<bd){bd=d;bp=p;}});if(bp){ctx.strokeStyle='#0b0d12';ctx.lineWidth=1.5;[[2,1,'#5bd3ff'],[4,3,'#c9a14a'],[6,5,'#9ba5b4']].forEach(function(q){if(bp[q[0]]!=null){ctx.fillStyle=q[2];ctx.beginPath();ctx.arc(gx(bp[q[0]]),gy(bp[q[1]]),5,0,7);ctx.fill();ctx.stroke();}});}}
  // 범례
  ctx.font='11px system-ui';ctx.textAlign='left';ctx.textBaseline='top';
  ctx.fillStyle='#5bd3ff';ctx.fillText('● COM',8,8); ctx.fillStyle='#c9a14a';ctx.fillText('● 앞발',8,22); ctx.fillStyle='#9ba5b4';ctx.fillText('● 뒷발',8,36);
