  if(!drawCopFoot._img && typeof _STRIDE_FOOT_R!=='undefined'){ var im=new Image(); im.onload=function(){try{drawCopFoot(cid);}catch(e){}}; im.src=_STRIDE_FOOT_R; drawCopFoot._img=im; }
  var fimg=drawCopFoot._img;
