// 블로킹 top-view: COM·앞발 경로 + PBG 제동 벡터 (홈 방향=화면 오른쪽, 재생 프레임 마커 동기화)
function drawBlkPath(cid){
  var X=(typeof ETDIAG!=='undefined')?ETDIAG:null, B=X&&X.blocking; var canvas=document.getElementById(cid); if(!canvas||!B||!B.copPath||!B.copPath.length) return;
  var c=clearC(canvas), ctx=c.ctx, w=c.w, h=c.h, P=B.copPath;
  // copPath 점 = [FC기준ms, COM_좌우(1), COM_전진(2), 발_좌우(3), 발_전진(4), 제동크기(5), ML제동(6)]
  // 좌표축: 전진(홈)=화면 가로(오른쪽이 홈), 좌우(ML)=화면 세로 (교수 지시 2026-05-27)
  var aps=[],mls=[]; P.forEach(function(p){ aps.push(p[2]); mls.push(p[1]); if(p[3]!=null){aps.push(p[4]);mls.push(p[3]);} });
  var apmin=Math.min.apply(null,aps),apmax=Math.max.apply(null,aps),mlmin=Math.min.apply(null,mls),mlmax=Math.max.apply(null,mls);
  var firstAP=P[0][2], lastAP=P[P.length-1][2], fwdSign=(lastAP>=firstAP)?1:-1;
  var pad=32, sc=Math.min((w-2*pad)/((apmax-apmin)||1),(h-2*pad)/((mlmax-mlmin)||1));
  function gx(ap){ var v=(fwdSign>=0)?(ap-apmin):(apmax-ap); return pad+v*sc; }   // 전진(홈) → x, 오른쪽=홈
  function gy(ml){ return h-pad-(ml-mlmin)*sc; }                                   // 좌우(ML) → y
  // 홈 방향 화살표(오른쪽)
  ctx.strokeStyle='#3a4452';ctx.fillStyle='#a8b3c2';ctx.lineWidth=1;ctx.font='10px system-ui';ctx.textAlign='right';ctx.textBaseline='bottom';
  ctx.beginPath();ctx.moveTo(pad+6,pad-10);ctx.lineTo(w-16,pad-10);ctx.stroke();ctx.beginPath();ctx.moveTo(w-10,pad-10);ctx.lineTo(w-18,pad-14);ctx.lineTo(w-18,pad-6);ctx.closePath();ctx.fill();ctx.fillText('홈',w-22,pad-4);
  function path(idx,col,wd){ ctx.strokeStyle=col;ctx.lineWidth=wd;ctx.beginPath();var st=true;P.forEach(function(p){var ap=(idx===0)?p[2]:p[4],ml=(idx===0)?p[1]:p[3];if(ap==null||ml==null)return;var x=gx(ap),y=gy(ml);if(st){ctx.moveTo(x,y);st=false;}else ctx.lineTo(x,y);});ctx.stroke(); }
  path(1,'#c9a14a',2.4); path(0,'#5bd3ff',2.6);
  // PBG 제동 벡터(앞발 위치에서 홈 반대=왼쪽) — 제동은 전진을 막는 방향
  var pbgRel=B.events.PBG; var pp=null; P.forEach(function(p){ if(pp==null||Math.abs(p[0]-(pbgRel||0))<Math.abs(pp[0]-(pbgRel||0)))pp=p; });
  if(pp&&pp[3]!=null&&pp[5]!=null){ var bx=gx(pp[4]),by=gy(pp[3]); var L=Math.min(60,pp[5]/20)*fwdSign; // 제동크기 비례 · 홈 반대 방향
    ctx.strokeStyle='#46c98c';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(bx-L,by);ctx.stroke(); // 왼쪽(홈 반대=제동)
    ctx.fillStyle='#46c98c';ctx.beginPath();ctx.moveTo(bx-L-4*Math.sign(L||1),by);ctx.lineTo(bx-L+4*Math.sign(L||1),by-4);ctx.lineTo(bx-L+4*Math.sign(L||1),by+4);ctx.closePath();ctx.fill();
    ctx.fillStyle='#46c98c';ctx.font='10px system-ui';ctx.textAlign='left';ctx.textBaseline='bottom';ctx.fillText('제동(PBG)',bx-L,by-6); }
  // ── 현재 재생 프레임 마커(좌측 3D 스틱 재생과 동기화) ──
  var cf=(typeof _currentFrame!=='undefined'&&_currentFrame!=null)?_currentFrame:null;
  if(cf!=null){ var ft=(typeof _fastTrial==='function')?_fastTrial():null; var ifc=(ft&&ft.events&&ft.events.i_fc)||0, dtv=(ft&&ft.meta&&ft.meta.dt)||0.00333; var curMs=(cf-ifc)*dtv*1000;
    var bp=null,bd=1e9; P.forEach(function(p){ var d=Math.abs(p[0]-curMs); if(d<bd){bd=d;bp=p;} });
    if(bp){ ctx.strokeStyle='#0b0d12';ctx.lineWidth=1.5;
      if(bp[3]!=null){ ctx.fillStyle='#c9a14a';ctx.beginPath();ctx.arc(gx(bp[4]),gy(bp[3]),5,0,7);ctx.fill();ctx.stroke(); }
      ctx.fillStyle='#5bd3ff';ctx.beginPath();ctx.arc(gx(bp[2]),gy(bp[1]),6,0,7);ctx.fill();ctx.stroke(); }
  }
  ctx.fillStyle='#5bd3ff';ctx.font='10px system-ui';ctx.textAlign='left';ctx.textBaseline='top';ctx.fillText('● COM (재생 위치)',8,8); ctx.fillStyle='#c9a14a';ctx.fillText('● 앞발',8,21);
}
// ── 진단5 무릎전달 전용 화면 (개발문서 v1) — 각도 클수록 굴곡, Δ<0=신전 ──
function _knVGRFpct(t){ var a=t.series.FP2_Z,m=_blkMass(); return a?a.map(function(x){return isFinite(x)?Math.abs(x)/(m*9.81)*100:NaN;}):null; }
function _knExtVel(t){ var kv=t.series.Lead_Knee_Ang_Vel_X; if(!kv){var ka=t.series.Lead_Knee_Angle_X,dt=(t.meta&&t.meta.dt)||0.00333;kv=ka?ka.map(function(v,i){return(i===0||!isFinite(ka[i])||!isFinite(ka[i-1]))?NaN:(ka[i]-ka[i-1])/dt;}):null;} return kv?kv.map(function(v){return isFinite(v)?Math.max(0,-v):NaN;}):null; }
function _knCumW(t,sign){ var kp=t.series.Lead_Knee_Power_X,e=t.events||{},iFC=e.i_fc||0,dt=(t.meta&&t.meta.dt)||0.00333; if(!kp)return null; var o=new Array(kp.length),acc=0; for(var i=0;i<kp.length;i++){ if(i<iFC){o[i]=0;} else { var p=kp[i]; if(isFinite(p)){ if(sign>0&&p>0)acc+=p*dt; if(sign<0&&p<0)acc+=Math.abs(p)*dt; } o[i]=acc; } } return o; }
