  function kpi(lbl,val,sub){ return '<div style="flex:1 1 130px;background:var(--bg2);border-radius:8px;padding:9px 11px"><div class="note" style="font-size:11px">'+lbl+'</div><div style="font-size:16px;font-weight:800;margin-top:2px">'+val+'</div>'+(sub?'<div class="note" style="font-size:11px;margin-top:1px">'+sub+'</div>':'')+'</div>'; }
  var vg=K.vgrf,an=K.angle,ve=K.velocity,wk=K.work,pl=K.pelvis,tm=K.timing,ev=K.events,N=K.norm||{};
