  function loopB(){ return '<canvas id="ed-kn-loop" style="width:100%;height:235px;display:block;margin-top:10px"></canvas><div class="note" style="font-size:11px;margin-top:2px;color:var(--fg2)">힘-각도 고리 · x=무릎 각속도(+굴곡/−신전) · y=무릎 파워 · 생성(녹)/흡수(주)</div>'; }
  function _kgVg(f){ return (_kVg&&isFinite(_kVg[f]))?Math.round(_kVg[f]*10)/10:null; }
