  function _kgMom(f){ var R=!(_fkT&&_fkT.meta&&((_fkT.meta.handedness||'R').toUpperCase()==='L')); return _edSV(_fkT,R?'L_Knee_Moment_X':'R_Knee_Moment_X',f,1,true); }  // 리드무릎 버팀 모멘트(절대값)
