// 무릎 work loop: x=각속도, y=파워
function drawKneeLoop(cid){
  var X=(typeof ETDIAG!=='undefined')?ETDIAG:null, K=X&&X.knee5; var canvas=document.getElementById(cid); if(!canvas||!K) return;
  var t=(typeof _fastTrial==='function')?_fastTrial():null; if(!t) return; var c=clearC(canvas), ctx=c.ctx, w=c.w, h=c.h;
  var kv=t.series.Lead_Knee_Ang_Vel_X, kp=t.series.Lead_Knee_Power_X, e=t.events||{}, iFC=e.i_fc, iBR=e.i_br;
  if(!kv||!kp||iFC==null||iBR==null){ ctx.fillStyle='#a8b3c2';ctx.textAlign='center';ctx.fillText('— 무릎 각속도/파워 시계열 없음 —',w/2,h/2); return; }
  var xs=[],ys=[]; for(var i=iFC;i<=iBR&&i<kv.length;i++){ if(isFinite(kv[i])&&isFinite(kp[i])){xs.push(kv[i]);ys.push(kp[i]);} }
  if(!xs.length){ ctx.fillStyle='#a8b3c2';ctx.textAlign='center';ctx.fillText('— 데이터 없음 —',w/2,h/2); return; }
  var xmin=Math.min.apply(null,xs),xmax=Math.max.apply(null,xs),ymin=Math.min.apply(null,ys),ymax=Math.max.apply(null,ys);
  var pad=44, gx=function(x){return pad+(x-xmin)/((xmax-xmin)||1)*(w-pad-14);}, gy=function(y){return h-26-(y-ymin)/((ymax-ymin)||1)*(h-pad-14);};
  ctx.strokeStyle='#252d3a';ctx.lineWidth=1; var x0=gx(0),y0=gy(0);
  ctx.beginPath();ctx.moveTo(x0,14);ctx.lineTo(x0,h-26);ctx.stroke(); ctx.beginPath();ctx.moveTo(pad,y0);ctx.lineTo(w-14,y0);ctx.stroke();
  ctx.fillStyle='#a8b3c2';ctx.font='10px system-ui';ctx.textAlign='center';ctx.fillText('각속도 →(+굴곡 / −신전)',w/2,h-8); ctx.save();ctx.translate(12,h/2);ctx.rotate(-Math.PI/2);ctx.fillText('파워 (+생성 / −흡수)',0,0);ctx.restore();
  var _cf=(typeof _currentFrame!=='undefined'&&_currentFrame!=null)?Math.round(_currentFrame):iBR; var _ci=Math.max(0,Math.min(xs.length-1,_cf-iFC));
  for(var i=0;i<_ci;i++){ var p=ys[i]; ctx.strokeStyle=p>=0?'#46c98c':'#e8954e'; ctx.lineWidth=2; ctx.beginPath();ctx.moveTo(gx(xs[i]),gy(ys[i]));ctx.lineTo(gx(xs[i+1]),gy(ys[i+1]));ctx.stroke(); }
  if(_ci>0&&_ci<xs.length){ ctx.fillStyle='#fff';ctx.strokeStyle='#0b0d12';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(gx(xs[_ci]),gy(ys[_ci]),5,0,7);ctx.fill();ctx.stroke(); }
  ctx.fillStyle='#e8ecf2';ctx.beginPath();ctx.arc(gx(xs[0]),gy(ys[0]),3.5,0,7);ctx.fill(); ctx.fillStyle='#e8ecf2';ctx.textAlign='left';ctx.fillText('FC',gx(xs[0])+5,gy(ys[0]));
  ctx.fillStyle='#46c98c';ctx.textAlign='left';ctx.fillText('● 생성',w-70,18); ctx.fillStyle='#e8954e';ctx.fillText('● 흡수',w-70,31);
}
