  function _pgTrkV(f){ return _edSV(_fpT,'Thorax_Ang_Vel_Z',f,1,true); }
  function _pgPelE(f){ return _edSV(_fpT,'Pelvis_ME_X',f,1); }
  function _pgTrkE(f){ return _edSV(_fpT,'Trunk_ME_X',f,1); }
  var html='<div class="card" style="grid-column:1 / -1;border-left:4px solid var(--cyan)">'
    +'<div style="display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:8px"><div style="font-size:14px;font-weight:800">골반→몸통 회전 증폭 · <span style="color:var(--cyan)">'+P.typeKo+'</span></div><div style="font-size:13px;font-weight:800">증폭 점수 '+v(P.ampScore)+'점</div></div>'
    +'<div class="note" style="margin-top:3px;font-style:italic">이 단계의 질문: 골반이 몸통을 증폭시켰는가?</div>'
    +'<div style="font-size:14px;font-weight:700;line-height:1.6;margin-top:6px">'+P.summary+'</div>'
    +'<div class="note" style="margin-top:5px">골반 = 1단 기어, 몸통 = 그 힘을 키우는 2단 기어 · <b>보는 것:</b> 골반→몸통 회전속도 순서·간격·증폭 gain·에너지 전달 동기화 · <b>안 보는 것:</b> 몸통 자체 에너지 크기(진단7)·팔 전달(진단8) · 코호트 '+(N.n||20)+'명 기준</div></div>';
  html+='<div class="card" style="grid-column:1 / -1"><div style="display:flex;flex-wrap:wrap;gap:8px">'
