function _taComSpeed(t,prox,dist,r){ var fr=t.frames||[],dt=(t.meta&&t.meta.dt)||0.00333,n=fr.length,o=new Array(n); for(var i=0;i<n;i++){var a=fr[i],b=fr[i-1];if(!a||!b||!a[prox]||!a[dist]||!b[prox]||!b[dist]){o[i]=NaN;continue;}var s=0;for(var k=0;k<3;k++){var c1=a[prox][k]+r*(a[dist][k]-a[prox][k]),c0=b[prox][k]+r*(b[dist][k]-b[prox][k]);s+=(c1-c0)*(c1-c0);}o[i]=Math.sqrt(s)/dt/1000;}return o; }
