      cameraUpdatedAfterResize:!!(metrics.autoFitAfterResize!==false),
      orbitControlsDisabledDuringResize:document.body.classList.contains('stick-viewer-resizing'),
      timelineStillWorks:!!document.getElementById('gt-bar'),
