    +'<summary style="cursor:pointer;padding:10px 12px;font-size:12.5px;font-weight:700;color:var(--cyan);background:var(--bg2);border:1px solid var(--line);border-radius:8px">'+summary+'</summary>'
    +'<div class="coach-evidence-advanced-body" style="margin-top:6px">'+innerHtml+'</div></details>';
