// ── 상단 chrome: fixed + spacer(떨림 방지) · 스크롤 누적로 접힘 · 메인스틱 접힘 시 top:0 ──
(function initScrollCollapseNav() {
  const header = document.querySelector('header');
  const nav = document.querySelector('nav.tabs');
  if (!header || !nav) return;

  let chromeWrap = document.getElementById('report-chrome');
  let spacer = document.getElementById('chrome-spacer');
  if (!chromeWrap) {
    chromeWrap = document.createElement('div');
    chromeWrap.id = 'report-chrome';
    header.parentNode.insertBefore(chromeWrap, header);
    chromeWrap.appendChild(header);
    chromeWrap.appendChild(nav);
  }
  if (!spacer) {
    spacer = document.createElement('div');
    spacer.id = 'chrome-spacer';
    chromeWrap.insertAdjacentElement('afterend', spacer);
  }

  const COLLAPSE_Y = 28;
  const DOWN_ACC = 48;
  const UP_ACC = 40;
  const EXPAND_TOP_Y = 10;
  const LOCK_MS = 520;

  let lastY = 0;
  let collapsed = false;
  let ticking = false;
  let lockUntil = 0;
  let downAcc = 0;
  let upAcc = 0;
  let expandedChromeH = 0;
  let collapsedChromeH = 0;
  const layoutRoot = document.querySelector('main.layout') || document.querySelector('.layout');

  const peek = document.createElement('button');
  peek.type = 'button';
  peek.className = 'nav-scroll-peek';
  peek.textContent = '메뉴 · 탭';
  peek.title = '상단 메뉴 펼치기';
  document.body.appendChild(peek);

  function measureChromeHeights() {
    const was = collapsed;
    document.body.classList.remove('scroll-nav-collapsed');
    expandedChromeH = chromeWrap.offsetHeight;
    document.body.classList.add('scroll-nav-collapsed');
    collapsedChromeH = chromeWrap.offsetHeight;
    document.body.classList.toggle('scroll-nav-collapsed', was);
    applySpacerHeight();
  }

  function applySpacerHeight() {
    const h = (collapsed ? collapsedChromeH : expandedChromeH) + 4;
    const px = h + 'px';
    document.documentElement.style.setProperty('--chrome-spacer-h', px);
    document.documentElement.style.setProperty('--chrome-sticky-top', px);
    document.documentElement.style.setProperty('--sticky-subnav-top', px);
    spacer.style.height = px;
  }

  function anchorScrollFix() {
    if (!layoutRoot) return;
    const before = layoutRoot.getBoundingClientRect().top;
    requestAnimationFrame(function () {
      requestAnimationFrame(function () {
        const drift = layoutRoot.getBoundingClientRect().top - before;
        if (Math.abs(drift) > 0.5) window.scrollBy(0, drift);
        lastY = window.scrollY || 0;
      });
    });
  }

  function setCollapsed(on) {
    if (on === collapsed) return;
    if (Date.now() < lockUntil) return;
    collapsed = on;
    document.body.classList.toggle('scroll-nav-collapsed', on);
    applySpacerHeight();
    anchorScrollFix();
    lockUntil = Date.now() + LOCK_MS;
    downAcc = 0;
    upAcc = 0;
  }

  function syncReportChrome() {
    measureChromeHeights();
  }

  window.syncReportChrome = syncReportChrome;

  function onScroll() {
    if (Date.now() < lockUntil) {
      ticking = false;
      return;
    }
    const y = window.scrollY || document.documentElement.scrollTop || 0;
    const dy = y - lastY;
    if (dy > 0.5) {
      downAcc += dy;
      upAcc = 0;
    } else if (dy < -0.5) {
      upAcc += -dy;
      downAcc = 0;
    }
    if (y <= EXPAND_TOP_Y) {
      if (collapsed) setCollapsed(false);
    } else if (!collapsed && y >= COLLAPSE_Y && downAcc >= DOWN_ACC) {
      setCollapsed(true);
    } else if (collapsed && upAcc >= UP_ACC) {
      setCollapsed(false);
    }
    lastY = y;
    ticking = false;
  }

  window.addEventListener(
    'scroll',
    function () {
      if (!ticking) {
        ticking = true;
        requestAnimationFrame(onScroll);
      }
    },
    { passive: true }
  );

  peek.addEventListener('click', function () {
    lockUntil = 0;
    setCollapsed(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  window.addEventListener('resize', function () {
    if (Date.now() < lockUntil) return;
    measureChromeHeights();
  });

  measureChromeHeights();
  lastY = window.scrollY || 0;

  function onInnerScroll(el) {
    if (!el || el.scrollTop <= 20) return;
    if (!collapsed) setCollapsed(true);
  }

  const coachPanel = document.querySelector('.right-panel.feedback-panel');
  if (coachPanel) {
    coachPanel.addEventListener('scroll', function () { onInnerScroll(coachPanel); }, { passive: true });
  }
  if (layoutRoot && layoutRoot !== document.documentElement && layoutRoot !== document.body) {
    layoutRoot.addEventListener('scroll', function () { onInnerScroll(layoutRoot); }, { passive: true });
  }

  if (document.body.classList.contains('coach-today-summary-only') || document.body.classList.contains('coach-feedback-layout')) {
    requestAnimationFrame(function () { if (!collapsed) setCollapsed(true); });
  }
})();

// ═══════════════════════════════════════════════════════════════════
// [2026-05-28 C안 Hybrid] 9단계 탭 색 배지 — 출력(생성)/효율(전달)/저장/부하 분류
// ═══════════════════════════════════════════════════════════════════
function _injectTabBadges(){
  try{
    var TAGS={
      'ed-windup':{c:'#9c8cff',l:'저장'},
      'ed-xftiming':{c:'#46c98c',l:'전달(효율)'},
      'ed-stride':{c:'#5bd3ff',l:'생성(출력)'},
      'ed-blocking':{c:'#5bd3ff',l:'생성(출력)'},
      'ed-knee':{c:'#46c98c',l:'전달(효율)'},
      'ed-pelvistrunk':{c:'#46c98c',l:'전달(효율)'},
      'ed-trunk':{c:'#5bd3ff',l:'생성(출력)'},
      'ed-trunkarm':{c:'#e8954e',l:'부하(팔)'},
      'ed-armball':{c:'#e8954e',l:'부하(팔)'},
      'command':{c:'#f5c542',l:'결과(제구·랩소도)'}
    };
    Object.keys(TAGS).forEach(function(key){
      var t=document.querySelector('.tab[data-page="'+key+'"]');
      if(!t) return;
      t.style.borderBottom='none'; // 하단 라인 제거 (rmode-bar에 범례로 대체)
      t.title=TAGS[key].l+' 노드';
      // 작은 점 → 굵은 세로 막대로
      var existing=t.querySelector('.tab-badge');
      if(existing) existing.remove();
      var bar=document.createElement('span');
      bar.className='tab-badge';
      bar.style.cssText='display:inline-block;width:5px;height:16px;background:'+TAGS[key].c+';margin-right:7px;vertical-align:middle;border-radius:2px';
      t.insertBefore(bar,t.firstChild);
    });
    // 기존 범례 한 줄 제거 (rmode-bar 범례 박스로 대체됨)
    var lg=document.getElementById('_tab-badge-legend');
    if(lg) lg.remove();
  }catch(e){console.warn('tab badge',e);}
}
(function(){ setTimeout(function(){ try{_injectTabBadges();}catch(e){} }, 100); })();

// ═══════════════════════════════════════════════════════════════════
// 트라이얼 비교 모드 wiring
// ═══════════════════════════════════════════════════════════════════
(function compareUI() {
  const btn   = document.getElementById('btn-compare');
  const body  = document.getElementById('cmp-body');
  const selA  = document.getElementById('cmp-a');
  const selB  = document.getElementById('cmp-b');
  const auto  = document.getElementById('cmp-auto');
  const viewSeg  = document.getElementById('cmp-view');
  const alignSeg = document.getElementById('cmp-align');
  const varsEl   = document.getElementById('cmp-vars');
  if (!btn || !selA || !selB) return;

  const SIDE_OFFSET = 1600;   // 좌우 보기 시 ghost 측면 이동량(mm)
  let view = 'overlay', align = 'fc';
  const veloOf = t => (t.rapsodo && isFinite(t.rapsodo.velocity_kmh)) ? t.rapsodo.velocity_kmh : null;

  // 드롭다운 채우기
  DATA.trials.forEach((t, i) => {
    const v = veloOf(t);
    const txt = v ? `${t.meta.trial_label} · ${v.toFixed(1)} km/h` : `${t.meta.trial_label} · (구속없음)`;
    [selA, selB].forEach(s => { const o = document.createElement('option'); o.value = i; o.textContent = txt; s.appendChild(o); });
  });
  // 기본: 빠름 vs 느림
  function fastSlow() {
    const withV = DATA.trials.map((t, i) => ({ i, v: veloOf(t) })).filter(x => x.v != null);
    if (withV.length < 2) return [0, Math.min(1, DATA.trials.length - 1)];
    withV.sort((a, b) => a.v - b.v);
    return [withV[withV.length - 1].i, withV[0].i];   // [빠름, 느림]
  }
  const [fi, si] = fastSlow();
  selA.value = fi; selB.value = si;

  function trA() { return DATA.trials[parseInt(selA.value)]; }
  function trB() { return DATA.trials[parseInt(selB.value)]; }

  function applyCompare() {
    window._cmpB = trB();
    playback.setCompare(true, trA(), trB(), align);
    playback.setGhostOffset(view === 'side' ? SIDE_OFFSET : 0);
    // 오른쪽 차트는 트라이얼 A 를 따라가도록 (setTrial 호출 없이 값만 변경)
    sel.value = parseInt(selA.value);
    renderComparePanel(trA(), trB());
    renderTrialSpecific(parseInt(sel.value));
  }

  btn.addEventListener('click', () => {
    const on = !btn.classList.contains('on');
    btn.classList.toggle('on', on);
    body.hidden = !on;
    sel.disabled = on;
    if (on) { applyCompare(); }
    else { playback.setCompare(false); window._cmpB=null; renderTrialSpecific(parseInt(sel.value)); }
  });
  auto.addEventListener('click', () => {
    const [a, b] = fastSlow();
    selA.value = a; selB.value = b;
    if (btn.classList.contains('on')) applyCompare();
  });
  selA.addEventListener('change', () => { if (btn.classList.contains('on')) applyCompare(); });
  selB.addEventListener('change', () => { if (btn.classList.contains('on')) applyCompare(); });
  viewSeg.querySelectorAll('.seg-btn').forEach(b => b.addEventListener('click', () => {
    viewSeg.querySelectorAll('.seg-btn').forEach(x => x.classList.remove('on'));
    b.classList.add('on'); view = b.dataset.view;
    playback.setGhostOffset(view === 'side' ? SIDE_OFFSET : 0);
  }));
  alignSeg.querySelectorAll('.seg-btn').forEach(b => b.addEventListener('click', () => {
    alignSeg.querySelectorAll('.seg-btn').forEach(x => x.classList.remove('on'));
    b.classList.add('on'); align = b.dataset.align;
    if (btn.classList.contains('on')) applyCompare();
  }));

  // 변인 비교표
  function renderComparePanel(a, b) {
    const ka = a.kseq && a.kseq.segments || {}, kb = b.kseq && b.kseq.segments || {};
    const sa = a.scalars || {}, sb = b.scalars || {};
    const rows = [
      ['구속 (km/h)',      veloOf(a),               veloOf(b),               1],
      ['회전수 (rpm)',     a.rapsodo?.total_spin_rpm, b.rapsodo?.total_spin_rpm, 0],
      ['Shoulder ER max (°)', sa.shoulder_er_max,    sb.shoulder_er_max,      1],
      ['X-Factor max (°)', sa.x_factor_max,          sb.x_factor_max,         1],
      ['Stride (m)',       sa.stride_length,         sb.stride_length,        2],
      ['Lead Knee @BR (°)',sa.lead_knee_br,          sb.lead_knee_br,         1],
      ['Pelvis peak (°/s)',ka.pelvis?.peak_abs,      kb.pelvis?.peak_abs,     0],
      ['Trunk peak (°/s)', ka.trunk?.peak_abs,       kb.trunk?.peak_abs,      0],
      ['Arm peak (°/s)',   ka.arm?.peak_abs,         kb.arm?.peak_abs,        0],
      ['GRF Lead (%BW)',   sa.grf_fp2_peak_pct_bw,   sb.grf_fp2_peak_pct_bw,  1],
      ['GRF Rear (%BW)',   sa.grf_fp1_peak_pct_bw,   sb.grf_fp1_peak_pct_bw,  1],
    ];
    const f = (v, d) => (v == null || !isFinite(v)) ? '—' : v.toFixed(d);
    let html = `<table><thead><tr><th>변인</th><th>A·${a.meta.trial_label.replace('Trial ','T')}</th><th>B·${b.meta.trial_label.replace('Trial ','T')}</th><th>Δ(B−A)</th></tr></thead><tbody>`;
    for (const [lbl, va, vb, d] of rows) {
      let dCell = '—', dCls = 'delta';
      if (va != null && vb != null && isFinite(va) && isFinite(vb)) {
        const diff = vb - va;
        const arrow = diff > 0 ? '▲' : (diff < 0 ? '▼' : '');
        dCls += diff > 0 ? ' up' : (diff < 0 ? ' down' : '');
        dCell = `${arrow}${Math.abs(diff).toFixed(d)}`;
      }
      html += `<tr><td>${lbl}</td><td>${f(va, d)}</td><td>${f(vb, d)}</td><td class="${dCls}">${dCell}</td></tr>`;
    }
    html += `</tbody></table>`;
    varsEl.innerHTML = html;
  }
})();
// ═══════════════════════════════════════════════════════════════════
// Render: 에너지 생성·전달 평가 (Theia 전용) — Phase 1
//  관절 파워 → 일(work, 생성/흡수) → 전신 전진 KE → peak power 시퀀싱
// ═══════════════════════════════════════════════════════════════════
function _enWork(arr, dt, lo, hi) {
  // 구간 [lo,hi] 의 일(work)=∫P dt. 양수=에너지 생성(concentric), 음수=흡수(eccentric).
  let pos = 0, neg = 0;
  if (!arr) return { pos: null, neg: null, net: null };
  const a = Math.max(0, lo), b = Math.min(arr.length - 1, hi);
  for (let i = a; i <= b; i++) {
    const p = arr[i]; if (!isFinite(p)) continue;
    const w = p * dt; if (w >= 0) pos += w; else neg += w;
  }
  return { pos, neg, net: pos + neg };
}
function _enPeak(arr, dt, i_fc, lo, hi) {
  // 구간 내 최대 양(+)파워와 그 시점(ms, FC 기준)
  if (!arr) return { peak: null, t_ms: null };
  let pk = -Infinity, pi = -1;
  const a = Math.max(0, lo), b = Math.min(arr.length - 1, hi);
  for (let i = a; i <= b; i++) { const p = arr[i]; if (isFinite(p) && p > pk) { pk = p; pi = i; } }
  return { peak: pi >= 0 ? pk : null, t_ms: pi >= 0 ? (pi - i_fc) * dt * 1000 : null };
}

// ── 2단계: per-axis 관절 파워 (계산 · ΣM·ω) ──
function _enDeriv(a, dt) {            // 각도(deg) 시계열 → 각속도(rad/s), 중앙차분
  if (!a) return null;
  const w = new Array(a.length).fill(NaN);
  for (let i = 1; i < a.length - 1; i++)
    if (isFinite(a[i+1]) && isFinite(a[i-1])) w[i] = (a[i+1] - a[i-1]) / (2*dt) * Math.PI / 180;
  return w;
}
function _enCorr(a, b, lo, hi) {
  let n=0, sa=0, sb=0, saa=0, sbb=0, sab=0;
  for (let i=Math.max(0,lo); i<=hi && i<a.length && i<b.length; i++) {
    const x=a[i], y=b[i]; if (!isFinite(x)||!isFinite(y)) continue;
    n++; sa+=x; sb+=y; saa+=x*x; sbb+=y*y; sab+=x*y;
  }
  if (n<4) return NaN;
  const cov=sab-sa*sb/n, va=saa-sa*sa/n, vb=sbb-sb*sb/n;
  return (va>0&&vb>0) ? cov/Math.sqrt(va*vb) : NaN;
}
// 관절 per-axis 파워 = M_축 × ω_축. net 파워와 부호 정렬(상관 음수면 전체 반전) + 검증 corr 반환.
function _enAxisPower(trial, momPrefix, angPrefix, netKey) {
  const S=trial.series||{}, dt=trial.meta.dt, ev=trial.events||{};
  const P={};
  for (const ax of ['X','Y','Z']) {
    const M=S[momPrefix+'_'+ax], w=_enDeriv(S[angPrefix+'_'+ax], dt);
    if (!M||!w) { P[ax]=null; continue; }
    const n=Math.min(M.length, w.length), arr=new Array(n);
    for (let i=0;i<n;i++) arr[i]=(isFinite(M[i])&&isFinite(w[i])) ? M[i]*w[i] : NaN;
    P[ax]=arr;
  }
  const axes=['X','Y','Z'].filter(a=>P[a]);
  let summed=null;
  if (axes.length) {
    const n=Math.min(...axes.map(a=>P[a].length)); summed=new Array(n);
    for (let i=0;i<n;i++){ let s=0,ok=false; for(const a of axes){const v=P[a][i]; if(isFinite(v)){s+=v;ok=true;}} summed[i]=ok?s:NaN; }
  }
  const net=S[netKey]; let corr=NaN, flipped=false;
  if (net && summed) {
    corr=_enCorr(summed, net, ev.i_kl_peak||0, ev.i_br||(summed.length-1));
    if (isFinite(corr) && corr<0) { flipped=true; for(const a of axes) P[a]=P[a].map(v=>isFinite(v)?-v:v); corr=-corr; }
  }
  return { P, corr, flipped };
}

function renderEnergy(trial){
  var fast=_fastTrial()||trial, slow=_slowTrial();
  var S=fast.series||{}, ev=fast.events||{}, dt=fast.meta.dt;
  var kl=ev.i_kl_peak, fc=ev.i_fc, mer=ev.i_mer, br=ev.i_br;
  var mass=(fast.grf&&fast.grf.body_weight_N)?fast.grf.body_weight_N/9.80665:(fast.meta.weight_kg||80);
  var WEARLY={startEv:'i_fc',startOff:-1.2,endEv:'i_fc',endOff:0};
  var WLATE={startEv:'i_fc',startOff:0,endEv:'i_br',endOff:0.2};
  var WME9={startEv:'i_fc',startOff:-0.2,endEv:'i_br',endOff:0.2};
  var keFn=function(t){ var bm=(t.grf&&t.grf.body_weight_N)?t.grf.body_weight_N/9.80665:(t.meta.weight_kg||80); return (t.series.COM_Velocity_Y||[]).map(function(v){return isFinite(v)?0.5*bm*v*v:NaN;}); };
  var dme=function(t,key){ var a=t.series[key]; if(!a)return null; var td=t.meta.dt, w=new Array(a.length).fill(NaN); for(var i=1;i<a.length-1;i++) if(isFinite(a[i+1])&&isFinite(a[i-1])) w[i]=(a[i+1]-a[i-1])/(2*td); return w; };
  var trunkFlexWork=function(t){ var ang=t.series.Trunk_Angle_X, lhm=t.series.L_Hip_Moment_X, rhm=t.series.R_Hip_Moment_X, td=t.meta.dt; if(!ang) return null; var w=_dvel(ang,td,1); var cum=new Array(ang.length).fill(NaN), acc=0; for(var i=0;i<ang.length;i++){ var wr=isFinite(w[i])?w[i]*Math.PI/180:0; var M=((lhm&&isFinite(lhm[i]))?lhm[i]:0)+((rhm&&isFinite(rhm[i]))?rhm[i]:0); acc+=M*wr*td; cum[i]=acc; } return cum; };
  // ① 뒷고관절 파워 (FC-1.2~FC)
  plotWin('ch-e1',Object.assign({fast:fast,slow:slow,left:{label:'관절 파워 (W)',lines:[{compute:function(t){return t.series.Back_Hip_Power_X;},color:'#86a8d0',label:'뒷고관절 파워',width:2.6}]}},WEARLY));
  // ② 앞무릎 파워 (FC~BR+0.2)
  plotWin('ch-e2',Object.assign({fast:fast,slow:slow,left:{label:'관절 파워 (W)',lines:[{compute:function(t){return t.series.Lead_Knee_Power_X;},color:'#5bd3ff',label:'앞무릎 파워',width:2.6}]}},WLATE));
  // ③ 앞고관절·어깨·팔꿈치 파워 (FC-1.2~FC)
  plotWin('ch-e3',Object.assign({fast:fast,slow:slow,left:{label:'관절 파워 (W)',lines:[
    {compute:function(t){return t.series.Lead_Hip_Power_X;},color:'#3ecf8e',label:'앞고관절',width:2.2},
    {compute:function(t){return t.series.Pitching_Shoulder_Power_X;},color:'#c084fc',label:'어깨',width:2.2},
    {compute:function(t){return t.series.Pitching_Elbow_Power_X;},color:'#86a8d0',label:'팔꿈치',width:2.2}]}},WEARLY));
  // ④ 전신 전진 운동에너지 ½mv² (KL-0.1~BR+0.2)
  plotWin('ch-e4',{fast:fast,slow:slow,startEv:'i_kl_peak',startOff:-0.1,endEv:'i_br',endOff:0.2,left:{label:'전진 KE (J)',lines:[{compute:keFn,color:'#5bd3ff',label:'전신 전진 KE',width:2.6}]}});
  // ⑤ 골반·몸통·팔 회전에너지 = 분절 ME (FC~BR+0.2)
  plotWin('ch-e5',Object.assign({fast:fast,slow:slow,left:{label:'분절 역학에너지 (J)',lines:[
    {compute:function(t){return t.series.Pelvis_ME_X;},color:'#b07cff',label:'골반',width:2.2},
    {compute:function(t){return t.series.Trunk_ME_X;},color:'#ff6b9d',label:'몸통',width:2.2},
    {compute:function(t){return t.series.Pitching_Humerus_ME_X;},color:'#c084fc',label:'상완',width:2.2}]}},WLATE));
  // ⑥ 몸통 굴곡 일(누적,근사) + 몸통 전체 역학에너지 (FC~BR+0.2)
  plotWin('ch-e6',Object.assign({fast:fast,slow:slow,left:{label:'에너지 (J)',lines:[
    {compute:function(t){return t.series.Trunk_ME_X;},color:'#86a8d0',label:'몸통 전체 역학에너지',width:2.4},
    {compute:trunkFlexWork,color:'#5bd3ff',label:'몸통 굴곡 일(누적,근사)',width:2.0}]}},WLATE));
  // ⑦ 분절 역학에너지 J (FC~BR+0.2)
  plotWin('ch-e7',Object.assign({fast:fast,slow:slow,left:{label:'분절 역학에너지 (J)',lines:[
    {compute:function(t){return t.series.Pelvis_ME_X;},color:'#b07cff',label:'골반',width:2.2},
    {compute:function(t){return t.series.Trunk_ME_X;},color:'#ff6b9d',label:'몸통',width:2.2},
    {compute:function(t){return t.series.Pitching_Humerus_ME_X;},color:'#c084fc',label:'상완',width:2.2}]}},WLATE));
  // ⑧ 분절 파워 dE/dt (FC~BR+0.2)
  plotWin('ch-e8',Object.assign({fast:fast,slow:slow,left:{label:'분절 파워 dE/dt (W)',lines:[
    {compute:function(t){return dme(t,'Pelvis_ME_X');},color:'#b07cff',label:'골반',width:2.2},
    {compute:function(t){return dme(t,'Trunk_ME_X');},color:'#ff6b9d',label:'몸통',width:2.2},
    {compute:function(t){return dme(t,'Pitching_Humerus_ME_X');},color:'#c084fc',label:'상완',width:2.2}]}},WLATE));
  // ⑨ MECHANICAL ENERGY (FC-0.2~BR+0.2)
  plotWin('ch-e9',Object.assign({fast:fast,slow:slow,left:{label:'역학적 에너지 (J)',lines:[
    {compute:function(t){return t.series.Pelvis_ME_X;},color:'#b07cff',label:'골반',width:2.2},
    {compute:function(t){return t.series.Trunk_ME_X;},color:'#ff6b9d',label:'몸통',width:2.2},
    {compute:function(t){return t.series.Pitching_Humerus_ME_X;},color:'#c084fc',label:'위팔',width:2.2}]}},WME9));

  // ⑩ 앞다리 무릎 4변인 (각도·각속도·토크·파워) FC~BR+0.2 + ⑪ work loop
  var RHPe=((DATA.player&&DATA.player.handedness)||'R').toUpperCase()!=='L';
  var kneeMom=function(t){ return RHPe?t.series.L_Knee_Moment_X:t.series.R_Knee_Moment_X; };
  var kneeVel=function(t){ return _dvel(t.series.Lead_Knee_Angle_X, t.meta.dt, 1); };
  var kneePw =function(t){ return t.series.Lead_Knee_Power_X; };
  // [2026-05-26] 앞무릎 각도 + 각속도 한 그래프(좌=각도·우=각속도). ⑩-b 별도 차트는 통합 제거.
  plotWin('ch-knee-ang',Object.assign({fast:fast,slow:slow,
    left:{label:'무릎 각도 (°)',lines:[{compute:function(t){return t.series.Lead_Knee_Angle_X;},color:'#5bd3ff',label:'앞무릎 각도',width:2.6}]},
    right:{label:'각속도 (°/s)',lines:[{compute:kneeVel,color:'#3ecf8e',label:'앞무릎 각속도',width:2.4}]}},WLATE));
  plotWin('ch-knee-tq',Object.assign({fast:fast,slow:slow,left:{label:'토크 (N·m)',lines:[{compute:kneeMom,color:'#86a8d0',label:'앞무릎 토크',width:2.4}]}},WLATE));
  plotWin('ch-knee-pw',Object.assign({fast:fast,slow:slow,left:{label:'파워 (W)',lines:[{compute:kneePw,color:'#c084fc',label:'앞무릎 파워',width:2.4}]}},WLATE));
  plotLoop('ch-knee-loop',{fast:fast,slow:slow,startEv:'i_fc',startOff:0,endEv:'i_br',endOff:0,
    xCompute:kneeVel, yCompute:kneeMom, powCompute:kneePw,
    xLabel:'각속도 (°/s) · +굴곡 / −신전', yLabel:'토크 (N·m)'});

  // ── 표(빠른 공 기준) — 그래프와 매칭 배치 ──
  var f1=function(x,u){return (x==null||!isFinite(x))?'—':x.toFixed(1)+(u||'');};
  var ke=keFn(fast); var keAt=function(i){return (i!=null&&i<ke.length&&isFinite(ke[i]))?ke[i]:null;};
  var kePeak=null; for(var i=0;i<ke.length;i++) if(isFinite(ke[i])&&(kePeak==null||ke[i]>kePeak))kePeak=ke[i];
  var dKE=(keAt(kl)!=null&&keAt(fc)!=null)?(keAt(fc)-keAt(kl)):null;
  var kc=document.getElementById('en-ke-cards');
  if(kc) kc.innerHTML='<div class="stat-card"><div class="lbl">전신 전진 KE peak</div><div class="v">'+f1(kePeak)+' J</div><div class="sub">½·m·v² · m='+f1(mass)+' kg</div></div>'+
    '<div class="stat-card"><div class="lbl">Drive 생성 ΔKE (KL→FC)</div><div class="v">'+f1(dKE)+' J</div><div class="sub">스트라이드 전진 에너지</div></div>'+
    '<div class="stat-card"><div class="lbl">KE @ FC</div><div class="v">'+f1(keAt(fc))+' J</div><div class="sub">앞발 착지 시점</div></div>';
  var joints=[['뒷고관절','Back_Hip_Power_X'],['뒷무릎','Back_Knee_Power_X'],['앞고관절','Lead_Hip_Power_X'],['앞무릎','Lead_Knee_Power_X'],['어깨(투구)','Pitching_Shoulder_Power_X'],['팔꿈치(투구)','Pitching_Elbow_Power_X']];
  var phs=[['Drive (KL→FC)',kl,fc],['Cocking (FC→MER)',fc,mer],['Accel (MER→BR)',mer,br]];
  var wcell=function(w){ if(w==null||!isFinite(w))return '<td style="text-align:right;color:var(--fg2)">—</td>'; var c=w>=0?'var(--green)':'var(--red)'; return '<td style="text-align:right;color:'+c+';font-weight:600">'+(w>=0?'+':'')+w.toFixed(1)+'</td>'; };
  var wt='<table class="ev-table"><thead><tr><th class="evl">관절 · 순(純)일 (J)</th>'+phs.map(function(p){return '<th>'+p[0]+'</th>';}).join('')+'<th>합</th></tr></thead><tbody>';
  joints.forEach(function(j){ var arr=S[j[1]], tot=0, any=false, cells=''; phs.forEach(function(p){ if(arr&&p[1]!=null&&p[2]!=null&&p[2]>p[1]){ var w=_enWork(arr,dt,p[1],p[2]).net; cells+=wcell(w); if(w!=null&&isFinite(w)){tot+=w;any=true;} } else cells+=wcell(null); }); wt+='<tr><td class="evl">'+j[0]+'</td>'+cells+wcell(any?tot:null)+'</tr>'; });
  wt+='</tbody></table><div class="note">순(純)일 = ∫파워 dt (양수=생성/concentric, 음수=흡수/eccentric). 하지는 Drive~Cocking 생성, 상지는 Accel 흡수가 정상.</div>';
  var we=document.getElementById('en-work-table'); if(we) we.innerHTML=wt;
  var seq=joints.map(function(j){ var info=_enPeak(S[j[1]],dt,fc,(kl!=null?kl:0),(br!=null?br:(S[j[1]]?S[j[1]].length-1:0))); return {lbl:j[0],peak:info.peak,t_ms:info.t_ms}; }).filter(function(x){return x.peak!=null;}).sort(function(a,b){return (a.t_ms==null?1e9:a.t_ms)-(b.t_ms==null?1e9:b.t_ms);});
  var stt='<table class="ev-table"><thead><tr><th class="evl">peak power 순서</th><th>peak (W)</th><th>시점 (FC 기준 ms)</th></tr></thead><tbody>';
  seq.forEach(function(x,i){ stt+='<tr><td class="evl">'+(i+1)+'. '+x.lbl+'</td><td style="text-align:right;font-weight:600">'+x.peak.toFixed(0)+'</td><td style="text-align:right;color:var(--fg1)">'+(x.t_ms==null?'—':(x.t_ms>=0?'+':'')+x.t_ms.toFixed(0))+'</td></tr>'; });
  stt+='</tbody></table><div class="note">peak 양(+)파워 발생 순서 = 운동사슬 전달 타이밍. 근위(고관절·무릎)→원위(어깨·팔꿈치) 순서가 이상적.</div>';
  var se=document.getElementById('en-timing-table'); if(se) se.innerHTML=stt;
  // 에너지 흐름 정량(분절 ME peak·타이밍·몸통→팔 전달)
  var ESEG=[['골반','Pelvis_ME_X'],['몸통','Trunk_ME_X'],['상완(투구)','Pitching_Humerus_ME_X']];
  var loi=(kl!=null?kl:0), hii=(br!=null?br:0);
  var pkMax=function(a){ if(!a)return {v:null,i:-1}; var v=-Infinity,bi=-1; for(var i=loi;i<=hii&&i<a.length;i++){var x=a[i]; if(isFinite(x)&&x>v){v=x;bi=i;}} return {v:bi>=0?v:null,i:bi}; };
  var pkSig=function(a){ if(!a)return {v:null,i:-1}; var v=-Infinity,bi=-1; for(var i=loi;i<=hii&&i<a.length;i++){var x=a[i]; if(isFinite(x)&&Math.abs(x)>Math.abs(v)){v=x;bi=i;}} return {v:bi>=0?v:null,i:bi}; };
  var tms=function(i){return (i==null||i<0)?'—':(((i-(fc!=null?fc:0))*dt*1000>=0?'+':'')+((i-(fc!=null?fc:0))*dt*1000).toFixed(0));};
  var rows='', epeak={};
  ESEG.forEach(function(e){ var pe=pkMax(S[e[1]]); epeak[e[1]]=pe; var pp=pkSig(dme(fast,e[1])); rows+='<tr><td class="evl">'+e[0]+'</td><td style="text-align:right">'+(pe.v==null?'—':pe.v.toFixed(0))+' J</td><td style="text-align:right;color:var(--fg1)">'+tms(pe.i)+' ms</td><td style="text-align:right;color:'+(pp.v>=0?'var(--green)':'var(--red)')+'">'+(pp.v==null?'—':(pp.v>=0?'+':'')+pp.v.toFixed(0))+' W</td><td style="text-align:right;color:var(--fg1)">'+tms(pp.i)+' ms</td></tr>'; });
  var Et=S.Trunk_ME_X, Eh=S.Pitching_Humerus_ME_X, tp=epeak.Trunk_ME_X?epeak.Trunk_ME_X.i:-1, hp=epeak.Pitching_Humerus_ME_X?epeak.Pitching_Humerus_ME_X.i:-1, th='';
  if(Et&&Eh&&tp>=0&&hp>tp&&isFinite(Et[tp])&&isFinite(Et[hp])&&isFinite(Eh[tp])&&isFinite(Eh[hp])){ var tl=Et[tp]-Et[hp], ag=Eh[hp]-Eh[tp], r=tl>0?ag/tl*100:null; th='<div class="note"><b>몸통→팔 에너지 핸드오프</b> (몸통 peak '+tms(tp)+'ms → 상완 peak '+tms(hp)+'ms): 몸통 방출 <b>'+tl.toFixed(0)+' J</b> · 상완 획득 <b>'+ag.toFixed(0)+' J</b>'+(r!=null?' · 전달비율 ≈ <b>'+r.toFixed(0)+'%</b>':'')+'.</div>'; }
  var ef=document.getElementById('en-eflow-table');
  if(ef) ef.innerHTML='<table class="ev-table"><thead><tr><th class="evl">분절</th><th>에너지 peak</th><th>시점(FC)</th><th>분절파워 peak</th><th>시점(FC)</th></tr></thead><tbody>'+rows+'</tbody></table>'+th+'<div class="note">dE/dt=분절 파워(양수=유입, 음수=유출/전달). 근위(몸통) 방출 시 원위(상완) 흡수 = 전달(Aguinaldo & Escamilla 2019).</div>';
}
if (typeof window !== 'undefined') window.renderEnergy = renderEnergy;

// 선수용 리포트(buildPlayerHTML)는 modules/player_report.js 단일 출처. 분석 리포트엔 player_report 스크립트가 별도 주입됨(빌더 repl).

/* ── 선수 리포트 v2 A/B (player_report_template_v2.js) ── */
function _ensureFeedbackSummaryForReport(){
  var FS=(typeof FEEDBACK_SUMMARY!=='undefined')?FEEDBACK_SUMMARY:null;
  if(!FS&&typeof DATA!=='undefined'&&DATA&&DATA.feedbackSummary) FS=DATA.feedbackSummary;
  if(!FS&&typeof feedbackSummary!=='undefined'&&feedbackSummary.build&&typeof DATA!=='undefined'&&typeof ETDIAG!=='undefined'){
    FS=feedbackSummary.build(DATA,ETDIAG);
    FEEDBACK_SUMMARY=FS;
    if(DATA) DATA.feedbackSummary=FS;
  }
  return FS;
}
function _capturePlayerReportSlot(slotKey,varKey,caption,done){
  try{
    if(varKey&&typeof applyStickVisualPreset==='function'){
      applyStickVisualPreset({key:varKey,source:'detail',syncPanel:true,renderCoachCue:true});
    }
    setTimeout(function(){
      try{
        if(typeof stick3D!=='undefined'&&stick3D.resize) stick3D.resize();
        if(typeof stick3D!=='undefined'&&stick3D.resetViewToFit) stick3D.resetViewToFit({force:true,allowUserLock:true});
        var png=(typeof stick3D!=='undefined'&&stick3D.capturePngDataUrl)?stick3D.capturePngDataUrl():null;
        window._playerReportCaptures=window._playerReportCaptures||{};
        window._playerReportCaptures[slotKey]={
          dataUrl:png, qaPassed:!!png, variableKey:varKey||'',
          caption:caption||slotKey, overlayPreset:(window._coachOvKey||''), frameEvent:'custom'
        };
      }catch(e){}
      if(typeof done==='function') done();
    },850);
  }catch(e){ if(typeof done==='function') done(); }
}
function _preparePlayerReportCaptures(FS,done){
  window._playerReportCaptures={};
  var issues=(FS&&FS.keyIssues)||[];
  var chain=[];
  if(issues[0]){
    var k0=(issues[0].relatedMetrics&&issues[0].relatedMetrics[0])||'';
    chain.push(['capture_primary_issue',k0,issues[0].title||'1순위']);
  }
  if(issues[1]){
    var k1=(issues[1].relatedMetrics&&issues[1].relatedMetrics[0])||'';
    chain.push(['capture_secondary_issue',k1,issues[1].title||'2순위']);
  }
  chain.push(['capture_arm_or_release','merPk','팔(MER)']);
  var i=0;
  (function next(){
    if(i>=chain.length){
      _syncPlayerReportCaptures(FS);
      if(typeof done==='function') done(window._playerReportCaptures);
      return;
    }
    var it=chain[i++];
    _capturePlayerReportSlot(it[0],it[1],it[2],next);
  })();
}
function _syncPlayerReportCaptures(FS){
  window._playerReportCaptures=window._playerReportCaptures||{};
  var caps=window._playerReportCaptures;
  var png=(typeof stick3D!=='undefined'&&stick3D.capturePngDataUrl)?stick3D.capturePngDataUrl():null;
  var selKey=window._vsSelectedKey||window.selectedVariableKey||'';
  var hi=(FS&&FS.highlight)||{};
  var capBase={ dataUrl:png, qaPassed:!!png, variableKey:selKey, phase:(hi&&hi.phase)||'', overlayPreset:(window._coachOvKey||''), frameEvent:'custom' };
  if(png&&!caps.capture_primary_issue){
    caps.capture_primary_issue=Object.assign({},capBase,{ caption:(hi&&hi.caption)||'현재 Stick overlay · primary issue' });
  }
  if(png&&!caps.capture_arm_or_release&&selKey&&(selKey.indexOf('arm')>=0||selKey.indexOf('hum')>=0||selKey.indexOf('mer')>=0)){
    caps.capture_arm_or_release=Object.assign({},capBase,{ caption:'팔 Stick overlay' });
  }
  return caps;
}
function _openPlayerReportV2(type,doPrint){
  try{
    var PR=(typeof window!=='undefined')?window.playerReportTemplateV2:null;
    if(!PR||!PR.buildTemplateData||!PR.buildReportHTML_A){ alert('선수 리포트 v2 모듈 미로드'); return; }
    if(typeof DATA==='undefined'||!DATA){ alert('분석 데이터 없음 — 먼저 선수 분석 필요'); return; }
    var FS=_ensureFeedbackSummaryForReport();
    var activeVarKey=_vsSelectedKey||window.selectedVariableKey||'';
    _preparePlayerReportCaptures(FS,function(caps){
      try{
        caps=caps||window._playerReportCaptures||{};
        var reportType=(type==='B')?'B_researcher_explanation':'A_summary';
        var data=PR.buildTemplateData(DATA,FS,caps,reportType,{activeVarKey:activeVarKey});
        var html=(type==='B')?PR.buildReportHTML_B(data):PR.buildReportHTML_A(data);
        var smoke=PR.copySmoke(html);
        if(!smoke.ok){ alert('금지 cue 검출 — 출력 중단: '+smoke.found.join(', ')); return; }
        if(type==='A'&&/결함/.test(html)){ alert('A형에 결함 라벨 검출 — 출력 중단'); return; }
        var nm=((DATA.player&&DATA.player.name)||'선수').replace(/\s+/g,'');
        var title=(type==='B')?(nm+'_연구원설명리포트_B형'):(nm+'_선수요약리포트_A형');
        var w=window.open('','_blank');
        if(!w){ alert('팝업 차단됨 — 허용 후 다시 시도'); return; }
        w.document.open(); w.document.write(html); w.document.close();
        try{ w.document.title=title; }catch(e){}
        if(doPrint) setTimeout(function(){ try{ w.focus(); w.print(); }catch(e2){} }, 600);
      }catch(e){ alert('선수 리포트 v2 생성 오류: '+e.message); }
    });
  }catch(e){ alert('선수 리포트 v2 준비 오류: '+e.message); }
}
function _buildPlayerReportV2HTML(DATA,FS,caps,type,activeVarKey){
  var PR=(typeof window!=='undefined')?window.playerReportTemplateV2:null;
  if(!PR||!DATA) return null;
  FS=FS||_ensureFeedbackSummaryForReport();
  caps=caps||{};
  type=(type==='B')?'B_researcher_explanation':'A_summary';
  var data=PR.buildTemplateData(DATA,FS,caps,type,{activeVarKey:activeVarKey||''});
  var html=(type==='B')?PR.buildReportHTML_B(data):PR.buildReportHTML_A(data);
  var smoke=PR.copySmoke(html);
  if(!smoke.ok||((type!=='B')&&/결함/.test(html))) return null;
  return html;
}
function _allPlayersV2HTML(list,type){
  var PR=(typeof window!=='undefined')?window.playerReportTemplateV2:null;
  if(!PR){ alert('선수 리포트 v2 모듈 미로드'); return null; }
  type=(type==='B')?'B':'A';
  var css=null, secs=[];
  list.forEach(function(D){
    if(!D) return;
    var FS=null;
    try{
      if(typeof feedbackSummary!=='undefined'&&feedbackSummary.build&&typeof etDiag!=='undefined'){
        FS=feedbackSummary.build(D,etDiag.compute(D));
      }
    }catch(e){}
    var h=_buildPlayerReportV2HTML(D,FS,{},type,'');
    if(!h) return;
    if(css==null){ var cm=h.match(/<style>([\s\S]*?)<\/style>/); css=cm?cm[1]:''; }
    var bm=h.match(/<div class="wrap">([\s\S]*)<\/div><\/body>/);
    if(bm) secs.push('<section class="wrap" style="page-break-before:always">'+bm[1]+'</section>');
  });
  if(!secs.length) return null;
  var label=(type==='B')?'B형 연구원 설명':'A형 선수 요약';
  return '<!DOCTYPE html><html lang="ko"><head><meta charset="utf-8"><title>전체 선수 '+label+' v2</title>'
    +'<link href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.min.css" rel="stylesheet">'
    +'<style>'+css+'\nsection.wrap:first-of-type{page-break-before:auto}</style></head><body>'
    +'<div class="note noprint" style="margin:12px">'+label+' · '+secs.length+'명 · elite20 밴드=display metadata · 선수값 engine pending</div>'
    +secs.join('')+'</body></html>';
}
function _openAllPlayerReportV2A(list){ var html=_allPlayersV2HTML(list||[],'A'); if(!html){ alert('출력할 A형 v2 리포트 없음'); return; } var w=window.open('','_blank'); if(!w){ alert('팝업 차단'); return; } w.document.open(); w.document.write(html); w.document.close(); setTimeout(function(){ try{ w.focus(); w.print(); }catch(e){} }, 900); }
function _openAllPlayerReportV2B(list){ var html=_allPlayersV2HTML(list||[],'B'); if(!html){ alert('출력할 B형 v2 리포트 없음'); return; } var w=window.open('','_blank'); if(!w){ alert('팝업 차단'); return; } w.document.open(); w.document.write(html); w.document.close(); setTimeout(function(){ try{ w.focus(); w.print(); }catch(e){} }, 900); }
function _openAllPlayerReportV2AFromCompare(){
  try{
    var list=[];
    if(typeof DATA!=='undefined'&&DATA) list.push(DATA);
    if(typeof window!=='undefined'&&window.__COHORT_COMPARE) list=list.concat(window.__COHORT_COMPARE.map(function(s){return s;}).filter(Boolean));
    if(typeof PLAYERS!=='undefined'&&PLAYERS.length){
      PLAYERS.forEach(function(p){ try{ if(p._data) list.push(p._data); }catch(e){} });
    }
    _openAllPlayerReportV2A(list);
  }catch(e){ alert('일괄 A형 v2 오류: '+e.message); }
}
function _openPlayerReportA(){ _openPlayerReportV2('A',true); }
function _openPlayerReportB(){ _openPlayerReportV2('B',true); }
if(typeof window!=='undefined'){ window._openPlayerReportA=_openPlayerReportA; window._openPlayerReportB=_openPlayerReportB; window._openPlayerReportV2=_openPlayerReportV2; window._syncPlayerReportCaptures=_syncPlayerReportCaptures; window._preparePlayerReportCaptures=_preparePlayerReportCaptures; window._openAllPlayerReportV2A=_openAllPlayerReportV2A; window._openAllPlayerReportV2B=_openAllPlayerReportV2B; window._openAllPlayerReportV2AFromCompare=_openAllPlayerReportV2AFromCompare; }

/* ── 선수용 PDF 리포트 (legacy) ── */
function _openPlayerPDF(){
  try{
    if(typeof window==='undefined'||!window.playerReport||!window.playerReport.buildPlayerHTML){ alert('선수 리포트 모듈 미로드'); return; }
    if(typeof DATA==='undefined'||!DATA){ alert('분석 데이터 없음 — 먼저 선수 분석 필요'); return; }
    var html=window.playerReport.buildPlayerHTML(DATA);
    var w=window.open('','_blank');
    if(!w){ alert('팝업 차단됨 — 허용 후 다시 시도'); return; }
    w.document.open(); w.document.write(html); w.document.close();
    setTimeout(function(){ try{ w.focus(); w.print(); }catch(e){} }, 600);
  }catch(e){ alert('선수 리포트 생성 오류: '+e.message); }
}
if(typeof window!=='undefined') window._openPlayerPDF=_openPlayerPDF;
